/* Dastpokht recipe library — Persian home cooking plus a few everyday dishes.
   Each recipe: id, category (x:1 = everyday non-Persian dish), total minutes, servings, n = [kcal, protein, carbs, fat] per serving,
   app = appliances needed (comma = all of, | = any of), t/d = [English, Persian] name and one-liner,
   i = ingredients "key:qty:unit:flag" (flag s = basic staple, o = optional),
   s = steps [minutes before serving, English, Persian], m = what to serve with it for a full meal.
   Nutrition is a per-serving estimate. */
var DP_RECIPES=[];
function R(o){DP_RECIPES.push(o);}

R({id:'ghormeh-sabzi',c:'stew',min:180,sv:4,n:[430,30,18,27],app:'stove',
 t:['Ghormeh sabzi','قورمه‌سبزی'],d:['Iran’s favorite: slow herb stew with kidney beans and dried lime.','محبوب‌ترین خورش ایرانی با سبزی، لوبیا قرمز و لیموعمانی'],
 i:'lamb|beef:500:g;kidney beans:0.75:cup;herbs:5:cup;dried lime:4;onion:1;turmeric:1:tsp:s;oil:6:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[180,'Soak the beans for at least 6 hours beforehand (overnight is best). Fry the diced onion in 2 tbsp oil until golden, stir in the turmeric, then brown the meat.','لوبیا را دست‌کم ۶ ساعت قبل (بهتر است از شب قبل) خیس کنید. پیاز خردشده را در ۲ قاشق روغن طلایی کنید، زردچوبه را اضافه کنید و گوشت را تفت دهید.'],
  [170,'Add the drained beans and 5 cups of hot water. Cover and simmer on low heat.','لوبیای آبکش‌شده و ۵ پیمانه آب داغ را اضافه کنید. درِ قابلمه را بگذارید تا با حرارت ملایم بپزد.'],
  [150,'Fry the chopped herbs in 4 tbsp oil for 15–20 minutes, until dark green and fragrant — don’t let them burn.','سبزی خردشده را در ۴ قاشق روغن ۱۵ تا ۲۰ دقیقه سرخ کنید تا تیره و معطر شود؛ مراقب باشید نسوزد.'],
  [120,'Pierce the dried limes and add them with the fried herbs, salt and pepper. Keep simmering, partly covered.','لیموعمانی‌ها را سوراخ کنید و همراه سبزی سرخ‌شده، نمک و فلفل به خورش اضافه کنید. با درِ نیمه‌باز بگذارید جا بیفتد.'],
  [20,'Taste and adjust the salt and sourness. When it’s ready, a layer of oil rises to the top.','مزه کنید و نمک و ترشی را تنظیم کنید. خورش جاافتاده روغن می‌اندازد.'],
  [0,'Serve with chelo.','با چلو سرو کنید.']],
 m:'chelo,salad-shirazi,sabzi-khordan,doogh'});

R({id:'gheymeh',c:'stew',min:150,sv:4,n:[460,26,30,26],app:'stove',
 t:['Gheymeh','قیمه'],d:['Tomato stew with split peas, dried lime and crispy fries.','خورش لپه با رب گوجه، لیموعمانی و سیب‌زمینی سرخ‌کرده'],
 i:'lamb|beef:400:g;split peas:0.5:cup;onion:1;tomato paste:2:tbsp;dried lime:3;potato:2;saffron:0.25:tsp:o;cinnamon::pinch:o;turmeric:1:tsp:s;oil:5:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[150,'Fry the diced onion until golden, add the turmeric and the diced meat, and brown it.','پیاز را طلایی کنید، زردچوبه و گوشت خردشده را اضافه و تفت دهید.'],
  [140,'Stir in the tomato paste for 2 minutes, then add 4 cups of hot water and the pierced dried limes. Cover and simmer.','رب گوجه را ۲ دقیقه تفت دهید، سپس ۴ پیمانه آب داغ و لیموعمانی‌های سوراخ‌شده را اضافه کنید و بگذارید بپزد.'],
  [90,'Rinse the split peas and add them with salt and pepper; simmer until tender but still whole.','لپه را بشویید و همراه نمک و فلفل اضافه کنید تا بپزد ولی له نشود.'],
  [30,'Cut the potatoes into thin matchsticks and fry until crisp.','سیب‌زمینی را خلالی نازک کنید و سرخ کنید تا ترد شود.'],
  [10,'Add the saffron water and a pinch of cinnamon; taste for salt and sourness.','زعفران دم‌کرده و کمی دارچین را اضافه کنید و نمک و ترشی را تنظیم کنید.'],
  [0,'Serve topped with the fries, with chelo.','با خلال سیب‌زمینی روی آن و در کنار چلو سرو کنید.']],
 m:'chelo,mast-o-khiar,doogh'});

R({id:'fesenjan',c:'stew',min:150,sv:4,n:[640,38,24,44],app:'stove',
 t:['Fesenjan','فسنجان'],d:['Chicken in a rich walnut and pomegranate sauce.','مرغ در سس غلیظ گردو و رب انار'],
 i:'chicken:800:g;walnuts:250:g;pomegranate molasses:0.5:cup;onion:1;sugar:1:tbsp:s;cinnamon::pinch:o;turmeric:1:tsp:s;oil:2:tbsp:s;salt::taste:s',
 s:[[150,'Grind the walnuts finely and toast them in a dry pot over low heat for 5 minutes, stirring.','گردو را ریز آسیاب کنید و ۵ دقیقه در قابلمه خشک با حرارت ملایم تفت دهید و مدام هم بزنید.'],
  [140,'Add 4 cups of water and simmer gently, stirring now and then, until the walnut oil rises — about an hour.','۴ پیمانه آب اضافه کنید و با حرارت ملایم بپزید و گاهی هم بزنید تا روغن گردو بیفتد؛ حدود یک ساعت.'],
  [110,'Meanwhile brown the sliced onion and the chicken pieces with the turmeric.','در این فاصله پیاز و تکه‌های مرغ را با زردچوبه تفت دهید.'],
  [80,'Add the chicken, pomegranate molasses and salt to the walnuts. Simmer until the sauce is dark and thick.','مرغ، رب انار و نمک را به گردو اضافه کنید و بگذارید تا خورش تیره و غلیظ شود.'],
  [15,'Balance sweet and sour: a little sugar if it’s too sour, more molasses if it’s too sweet.','ترش و شیرینی را تنظیم کنید: اگر ترش است کمی شکر، اگر شیرین است رب انار بیشتر.'],
  [0,'Serve with chelo.','با چلو سرو کنید.']],
 m:'chelo,salad-shirazi,doogh'});

R({id:'khoresh-bademjan',c:'stew',min:120,sv:4,n:[480,26,22,33],app:'stove',
 t:['Khoresh bademjan','خورش بادمجان'],d:['Meat and fried eggplant in a tangy tomato sauce.','گوشت و بادمجان سرخ‌کرده در سس گوجه و آبغوره'],
 i:'lamb|beef:400:g;eggplant:4;onion:1;tomato:3;tomato paste:2:tbsp;lemon:1;saffron:0.25:tsp:o;turmeric:1:tsp:s;oil:6:tbsp:s;salt::taste:s',
 s:[[120,'Brown the onion, add the turmeric and meat, then the tomato paste. Add 3 cups of water, cover and simmer.','پیاز را تفت دهید، زردچوبه و گوشت و سپس رب را اضافه کنید، ۳ پیمانه آب بریزید و بگذارید بپزد.'],
  [90,'Peel the eggplants and halve them lengthwise. Salt them for 20 minutes, pat dry and fry until golden.','بادمجان‌ها را پوست بگیرید و از طول نصف کنید، ۲۰ دقیقه نمک بزنید، خشک کنید و طلایی سرخ کنید.'],
  [45,'Lay the eggplants and halved tomatoes over the stew, add lemon juice and saffron, and simmer gently without stirring.','بادمجان و گوجه‌های نصف‌شده را روی خورش بچینید، آبلیمو و زعفران اضافه کنید و بدون هم زدن با حرارت ملایم بپزید.'],
  [0,'Serve carefully so the eggplants stay whole, with chelo.','با احتیاط بکشید تا بادمجان‌ها سالم بمانند و با چلو سرو کنید.']],
 m:'chelo,sabzi-khordan,doogh'});

R({id:'khoresh-karafs',c:'stew',min:120,sv:4,n:[390,27,12,26],app:'stove',
 t:['Khoresh karafs','خورش کرفس'],d:['Celery, parsley and mint stew — light and fresh.','خورش سبک و خوش‌عطر کرفس با جعفری و نعناع'],
 i:'lamb|beef:400:g;celery:1:bunch;parsley:2:cup;mint:0.5:cup;onion:1;lemon:1;turmeric:1:tsp:s;oil:5:tbsp:s;salt::taste:s',
 s:[[120,'Brown the onion, add the turmeric and meat, pour in 3 cups of water, cover and simmer.','پیاز را تفت دهید، زردچوبه و گوشت را اضافه کنید، ۳ پیمانه آب بریزید و بگذارید بپزد.'],
  [80,'Cut the celery into 3 cm pieces and fry for 10 minutes.','کرفس را ۳ سانتی خرد کنید و ۱۰ دقیقه تفت دهید.'],
  [70,'Fry the chopped parsley and mint for 5 minutes, then add them to the pot with the celery.','جعفری و نعناع خردشده را ۵ دقیقه تفت دهید و همراه کرفس به خورش اضافه کنید.'],
  [15,'Add the lemon juice and salt, then taste.','آبلیمو و نمک را اضافه کنید و مزه کنید.'],
  [0,'Serve with chelo.','با چلو سرو کنید.']],
 m:'chelo,mast-o-khiar,doogh'});

R({id:'abgoosht',c:'stew',min:210,sv:4,n:[620,38,52,28],app:'stove|pressure cooker',
 t:['Abgoosht (dizi)','آبگوشت (دیزی)'],d:['Slow lamb, chickpea and potato broth, eaten in two courses.','آبگوشت سنتی گوشت، نخود و سیب‌زمینی در دو مرحله'],
 i:'lamb:600:g;chickpeas:0.5:cup;white beans:0.5:cup;potato:3;tomato:2;tomato paste:1:tbsp;onion:1;dried lime:2;bread:4;turmeric:1:tsp:s;salt::taste:s;black pepper::taste:s',
 s:[[210,'Soak the chickpeas and beans overnight. Put the meat, drained legumes, a whole onion and the turmeric in a pot with 8 cups of water, bring to a boil and skim the foam.','نخود و لوبیا را از شب قبل خیس کنید. گوشت، حبوبات، پیاز درسته و زردچوبه را با ۸ پیمانه آب بجوشانید و کف روی آن را بگیرید.'],
  [200,'Cover and simmer on low for 2½ hours (about 45 minutes in a pressure cooker).','درِ قابلمه را بگذارید و ۲ و نیم ساعت با حرارت ملایم بپزید (در زودپز حدود ۴۵ دقیقه).'],
  [60,'Add the peeled potatoes, tomatoes, tomato paste, dried limes, salt and pepper.','سیب‌زمینی پوست‌کنده، گوجه، رب، لیموعمانی، نمک و فلفل را اضافه کنید.'],
  [15,'Pour the broth into bowls over torn bread. Mash the meat, potatoes and beans into a paste (gusht-koobideh).','آبگوشت را جدا کنید و با نان تریت کنید. گوشت و سیب‌زمینی و حبوبات را بکوبید تا گوشت‌کوبیده شود.'],
  [0,'Serve the broth and the mash with bread, raw onion, herbs and pickles.','آبگوشت و گوشت‌کوبیده را با نان، پیاز خام، سبزی خوردن و ترشی سرو کنید.']],
 m:'sabzi-khordan,doogh'});

R({id:'chelo',c:'rice',min:110,sv:4,n:[390,7,78,6],app:'stove|rice cooker',
 t:['Chelo with tahdig','چلو با ته‌دیگ'],d:['Fluffy steamed rice with a golden crust.','برنج دم‌کشیده و پفکی با ته‌دیگ طلایی'],
 i:'rice:3:cup;potato:1::o;butter:2:tbsp:o;saffron:0.25:tsp:o;oil:4:tbsp:s;salt::taste:s',
 s:[[110,'Rinse the rice several times until the water runs clear, then soak it in salted water for at least an hour.','برنج را چند بار بشویید تا آبش زلال شود و دست‌کم یک ساعت در آب‌نمک خیس کنید.'],
  [50,'Bring a big pot of salted water to a rolling boil. Boil the drained rice 6–8 minutes, until soft outside and still firm in the center. Drain.','آب و نمک را در قابلمه بزرگ بجوشانید. برنج را بریزید و ۶ تا ۸ دقیقه بجوشانید تا بیرونش نرم و مغزش کمی سفت باشد؛ آبکش کنید.'],
  [40,'Heat the oil in the pot, lay thin potato slices over the bottom for tahdig, then pile the rice on top in a mound. Poke a few holes with a spoon handle.','روغن را در قابلمه داغ کنید، ته آن سیب‌زمینی حلقه‌ای بچینید و برنج را به شکل هرم روی آن بریزید. با دسته قاشق چند سوراخ ایجاد کنید.'],
  [35,'Wrap the lid in a towel, cover tightly and steam on low for 35–45 minutes.','درِ قابلمه را دم‌کنی بپیچید، محکم بگذارید و ۳۵ تا ۴۵ دقیقه با حرارت ملایم دم بکشید.'],
  [5,'Mix a cup of rice with the saffron water and butter for the top.','یک پیمانه برنج را با زعفران دم‌کرده و کره مخلوط کنید برای روی دیس.'],
  [0,'Serve the rice with the golden tahdig on the side.','برنج را با ته‌دیگ طلایی سرو کنید.']],
 m:''});

R({id:'kateh',c:'rice',min:45,sv:4,n:[380,7,76,7],app:'stove|rice cooker',
 t:['Kateh','کته'],d:['Quick one-pot rice — the weeknight way.','کته، برنج یک‌قابلمه‌ای و سریع'],
 i:'rice:3:cup;butter:2:tbsp;oil:2:tbsp:s;salt::taste:s',
 s:[[45,'Rinse the rice until the water runs clear.','برنج را بشویید تا آبش زلال شود.'],
  [40,'Put it in a pot with 4½ cups of water, salt and oil, and boil uncovered until the water is absorbed, about 10 minutes.','برنج را با ۴ و نیم پیمانه آب، نمک و روغن بجوشانید تا آب کشیده شود؛ حدود ۱۰ دقیقه.'],
  [30,'Dot with butter, cover with a towel-wrapped lid and cook on low for 30 minutes.','کره را روی برنج بگذارید، درِ دم‌کنی را بگذارید و ۳۰ دقیقه با حرارت ملایم دم بکشد.'],
  [0,'Flip it onto a plate to show off the crust, or just scoop and serve.','برنج را برگردانید تا ته‌دیگ پیدا شود یا بکشید و سرو کنید.']],
 m:''});

R({id:'zereshk-polo',c:'rice',min:90,sv:4,n:[720,42,82,24],app:'stove',
 t:['Zereshk polo ba morgh','زرشک‌پلو با مرغ'],d:['Saffron rice with jewel-red barberries and braised chicken.','زرشک‌پلو با مرغ زعفرانی'],
 i:'rice:3:cup;chicken:1:kg;barberries:0.5:cup;onion:2;saffron:0.5:tsp;butter:2:tbsp;pistachios:2:tbsp:o;sugar:1:tbsp:s;turmeric:1:tsp:s;oil:4:tbsp:s;salt::taste:s',
 s:[[90,'Soak the rice (as for chelo). Brown an onion with the turmeric, add the chicken and sear it, then add 1 cup of water, salt and half the saffron. Cover and simmer 45 minutes.','برنج را خیس کنید (مثل چلو). یک پیاز را با زردچوبه تفت دهید، مرغ را اضافه و سرخ کنید، سپس یک پیمانه آب، نمک و نصف زعفران را بریزید و ۴۵ دقیقه بپزید.'],
  [55,'Parboil and drain the rice, then steam it for 40 minutes, as for chelo.','برنج را آبکش کنید و مثل چلو ۴۰ دقیقه دم بگذارید.'],
  [15,'Rinse the barberries, then sauté them in butter with the sugar for 1–2 minutes — they burn fast.','زرشک را بشویید و با کره و شکر یکی دو دقیقه تفت دهید؛ زود می‌سوزد.'],
  [5,'Mix some of the rice with the rest of the saffron water.','کمی از برنج را با باقی زعفران مخلوط کنید.'],
  [0,'Plate the rice, scatter the saffron rice, barberries and pistachios over it, and serve the chicken with its sauce.','برنج را بکشید، برنج زعفرانی، زرشک و پسته را رویش بریزید و مرغ را با سسش کنار آن سرو کنید.']],
 m:'mast-o-khiar,salad-shirazi,doogh'});

R({id:'loobia-polo',c:'rice',min:90,sv:4,n:[640,28,86,20],app:'stove',
 t:['Loobia polo','لوبیاپلو'],d:['Rice layered with beef, green beans and tomato.','لوبیاپلو با گوشت، لوبیا سبز و رب'],
 i:'beef|ground meat:400:g;rice:3:cup;green beans:300:g;onion:1;tomato paste:3:tbsp;cinnamon:0.5:tsp;advieh:1:tsp:o;turmeric:1:tsp:s;oil:5:tbsp:s;salt::taste:s',
 s:[[90,'Soak the rice. Fry the onion, add the turmeric and the meat, and brown it.','برنج را خیس کنید. پیاز را تفت دهید، زردچوبه و گوشت را اضافه و سرخ کنید.'],
  [75,'Add the chopped green beans and fry 5 minutes. Stir in the tomato paste, cinnamon and a splash of water, and cook 20 minutes.','لوبیا سبز خردشده را اضافه کنید و ۵ دقیقه تفت دهید. رب، دارچین و کمی آب را اضافه کنید و ۲۰ دقیقه بپزید.'],
  [55,'Parboil and drain the rice.','برنج را آبکش کنید.'],
  [45,'Layer the rice and the bean mixture in the pot, finishing with rice. Steam for 40 minutes.','برنج و مخلوط لوبیا را لایه‌لایه در قابلمه بریزید، لایه آخر برنج باشد، و ۴۰ دقیقه دم بگذارید.'],
  [0,'Mix gently and serve with yogurt or salad.','آرام مخلوط کنید و با ماست یا سالاد سرو کنید.']],
 m:'mast-o-khiar,salad-shirazi'});

R({id:'adas-polo',c:'rice',min:90,sv:4,n:[560,16,98,12],app:'stove',
 t:['Adas polo','عدس‌پلو'],d:['Rice with lentils, crispy onions, raisins and dates.','عدس‌پلو با پیازداغ، کشمش و خرما'],
 i:'rice:3:cup;lentils:1:cup;raisins:0.5:cup;dates:8::o;onion:2;butter:2:tbsp;saffron:0.25:tsp:o;cinnamon:0.5:tsp:o;oil:4:tbsp:s;salt::taste:s',
 s:[[90,'Soak the rice. Cook the lentils in water for 15–20 minutes, until just tender, and drain.','برنج را خیس کنید. عدس را ۱۵ تا ۲۰ دقیقه بپزید تا نرم شود ولی له نشود؛ آبکش کنید.'],
  [55,'Parboil and drain the rice, mix it with the lentils and steam for 40 minutes.','برنج را آبکش کنید، با عدس مخلوط کنید و ۴۰ دقیقه دم بگذارید.'],
  [30,'Slice the onions thinly and fry them slowly until deep golden (piaz dagh).','پیاز را نازک خلال کنید و آرام سرخ کنید تا طلایی تیره شود (پیازداغ).'],
  [10,'Warm the raisins and chopped dates in butter for a minute.','کشمش و خرمای خردشده را یک دقیقه در کره تفت دهید.'],
  [0,'Serve topped with saffron, the fried onion, raisins and dates.','با زعفران، پیازداغ، کشمش و خرما روی آن سرو کنید.']],
 m:'mast-o-khiar,sabzi-khordan'});

R({id:'baghali-polo',c:'rice',min:90,sv:4,n:[700,44,84,20],app:'stove',
 t:['Baghali polo ba morgh','باقالی‌پلو با مرغ'],d:['Dill and fava bean rice with saffron chicken.','باقالی‌پلو با شوید و مرغ زعفرانی'],
 i:'rice:3:cup;fava beans:300:g;dill:1:cup;chicken:1:kg;onion:1;saffron:0.5:tsp;butter:2:tbsp;turmeric:1:tsp:s;oil:4:tbsp:s;salt::taste:s',
 s:[[90,'Soak the rice. Brown the onion with the turmeric, add the chicken, then 1 cup of water, salt and half the saffron. Simmer 45 minutes.','برنج را خیس کنید. پیاز را با زردچوبه تفت دهید، مرغ را اضافه کنید، سپس یک پیمانه آب، نمک و نصف زعفران را بریزید و ۴۵ دقیقه بپزید.'],
  [55,'Parboil the rice, adding the fava beans for the last 2 minutes, and drain.','برنج را آبکش کنید؛ باقالی را ۲ دقیقه آخر اضافه کنید.'],
  [45,'Layer the rice and beans with the dill in the pot and steam for 40 minutes.','برنج و باقالی را با شوید لایه‌لایه در قابلمه بریزید و ۴۰ دقیقه دم بگذارید.'],
  [0,'Top with saffron rice and butter, and serve with the chicken.','با برنج زعفرانی و کره تزیین کنید و با مرغ سرو کنید.']],
 m:'mast-o-khiar,salad-shirazi,doogh'});

R({id:'sabzi-polo',c:'rice',min:90,sv:4,n:[680,36,82,22],app:'stove',
 t:['Sabzi polo ba mahi','سبزی‌پلو با ماهی'],d:['Herbed rice with crispy fish — the Nowruz classic.','سبزی‌پلو با ماهی، غذای شب عید'],
 i:'rice:3:cup;herbs:3:cup;fish:600:g;garlic:3:clove:o;flour:2:tbsp;lemon:1::o;turmeric:1:tsp:s;oil:5:tbsp:s;salt::taste:s',
 s:[[90,'Soak the rice. Chop the herbs finely.','برنج را خیس کنید. سبزی را ریز خرد کنید.'],
  [55,'Parboil and drain the rice, mix in the herbs and garlic, and steam for 40 minutes.','برنج را آبکش کنید، سبزی و سیر را مخلوط کنید و ۴۰ دقیقه دم بگذارید.'],
  [20,'Season the fish with salt and turmeric, dust with flour and fry 4 minutes a side.','ماهی را با نمک و زردچوبه مزه‌دار کنید، به آرد بزنید و هر طرف ۴ دقیقه سرخ کنید.'],
  [0,'Serve the green rice with the fish and lemon wedges.','سبزی‌پلو را با ماهی و لیمو سرو کنید.']],
 m:'salad-shirazi,doogh'});

R({id:'tahchin',c:'rice',min:120,sv:6,n:[560,30,72,17],app:'oven|stove',
 t:['Tahchin','ته‌چین مرغ'],d:['A crisp baked cake of saffron-yogurt rice with chicken.','ته‌چین مرغ زعفرانی و ترد'],
 i:'rice:3:cup;chicken:600:g;yogurt:1.5:cup;eggs:2;saffron:0.5:tsp;onion:1;butter:3:tbsp;barberries:0.25:cup:o;oil:3:tbsp:s;salt::taste:s',
 s:[[120,'Soak the rice. Poach the chicken with the onion and salt for 40 minutes, then shred it.','برنج را خیس کنید. مرغ را با پیاز و نمک ۴۰ دقیقه بپزید و ریش‌ریش کنید.'],
  [70,'Parboil and drain the rice. Mix the yogurt, egg yolks, saffron water, salt and half the rice.','برنج را آبکش کنید. ماست، زرده، زعفران، نمک و نصف برنج را مخلوط کنید.'],
  [60,'Butter a baking dish, press in the yogurt rice, add a layer of chicken, then the plain rice. Press down firmly.','ظرف پیرکس را کره بمالید، برنج ماستی را کف آن فشرده کنید، یک لایه مرغ و سپس باقی برنج را بریزید و محکم فشار دهید.'],
  [55,'Cover with foil and bake at 190°C (375°F) for an hour, until the bottom is golden.','روی آن فویل بکشید و یک ساعت در فر ۱۹۰ درجه بپزید تا زیرش طلایی شود.'],
  [0,'Rest 5 minutes, flip onto a platter and scatter barberries on top.','۵ دقیقه صبر کنید، برگردانید و با زرشک تزیین کنید.']],
 m:'salad-shirazi,doogh'});

R({id:'estamboli',c:'rice',min:60,sv:4,n:[520,14,88,12],app:'stove|rice cooker',
 t:['Estamboli polo','استامبولی‌پلو'],d:['Tomato rice with potatoes — cheap, fast and loved.','استامبولی‌پلو، سریع و خوشمزه'],
 i:'rice:3:cup;potato:2;tomato paste:3:tbsp;onion:1;beef|ground meat:250:g:o;turmeric:1:tsp:s;oil:4:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[60,'Rinse the rice. Fry the onion, add the turmeric, the meat if you’re using it, and the diced potatoes; cook 10 minutes.','برنج را بشویید. پیاز را تفت دهید، زردچوبه، گوشت (اختیاری) و سیب‌زمینی نگینی را اضافه کنید و ۱۰ دقیقه تفت دهید.'],
  [45,'Stir in the tomato paste, then add the rice, 4 cups of water, salt and pepper. Boil until the water is absorbed.','رب را تفت دهید، سپس برنج، ۴ پیمانه آب، نمک و فلفل را اضافه کنید و بجوشانید تا آب کشیده شود.'],
  [30,'Cover with a towel-wrapped lid and steam on low for 30 minutes.','درِ دم‌کنی بگذارید و ۳۰ دقیقه با حرارت ملایم دم بکشد.'],
  [0,'Serve with yogurt and pickles.','با ماست و ترشی سرو کنید.']],
 m:'mast-o-khiar,salad-shirazi'});

R({id:'joojeh-kabab',c:'kebab',min:300,sv:4,n:[380,48,6,17],app:'grill|oven|stove',
 t:['Joojeh kabab','جوجه‌کباب'],d:['Saffron and lemon chicken skewers.','جوجه‌کباب زعفرانی با لیمو'],
 i:'chicken:1:kg;yogurt:0.5:cup;onion:1;lemon:1;saffron:0.5:tsp;butter:2:tbsp;tomato:4::o;oil:3:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[300,'Cut the chicken into large cubes. Mix with grated onion, yogurt, lemon juice, saffron water, oil, salt and pepper, and marinate at least 4 hours (overnight is best).','مرغ را درشت خرد کنید و با پیاز رنده‌شده، ماست، آبلیمو، زعفران، روغن، نمک و فلفل مخلوط کنید. دست‌کم ۴ ساعت (بهتر است یک شب) بماند.'],
  [30,'Thread the chicken and tomatoes onto skewers. Light the grill, or turn the oven grill to high.','مرغ و گوجه‌ها را به سیخ بکشید. منقل را روشن کنید یا گریل فر را روی حداکثر بگذارید.'],
  [20,'Grill 12–15 minutes, turning often and brushing with melted butter and saffron.','۱۲ تا ۱۵ دقیقه کباب کنید، مرتب بچرخانید و با کره آب‌شده و زعفران چرب کنید.'],
  [0,'Serve with chelo or bread, the grilled tomatoes and sumac.','با چلو یا نان، گوجه کبابی و سماق سرو کنید.']],
 m:'chelo,salad-shirazi,doogh'});

R({id:'koobideh',c:'kebab',min:60,sv:4,n:[480,34,4,36],app:'grill|oven|stove',
 t:['Kabab koobideh','کباب کوبیده'],d:['Juicy ground-meat kebab — on the grill, in a pan or in the oven.','کباب کوبیده روی منقل، در تابه یا فر'],
 i:'ground meat:600:g;onion:1;sumac:1:tbsp:o;tomato:4::o;butter:1:tbsp:o;salt::taste:s;black pepper::taste:s',
 s:[[60,'Grate the onion and squeeze out the juice. Knead it with the meat, salt and pepper for 5 minutes until sticky, then chill 30 minutes.','پیاز را رنده کنید و آبش را بگیرید. با گوشت، نمک و فلفل ۵ دقیقه ورز دهید تا چسبناک شود و ۳۰ دقیقه در یخچال بگذارید.'],
  [25,'Shape the meat onto wide skewers, or into long patties for a pan or the oven.','گوشت را دور سیخ پهن بکشید، یا برای تابه و فر به شکل کباب دراز فرم دهید.'],
  [15,'Grill over hot coals 4–5 minutes a side, or cook in a hot pan 4 minutes a side, or under the oven grill for 10 minutes.','روی ذغال داغ هر طرف ۴ تا ۵ دقیقه، یا در تابه داغ هر طرف ۴ دقیقه، یا زیر گریل فر ۱۰ دقیقه بپزید.'],
  [0,'Serve with chelo, grilled tomatoes, butter and sumac.','با چلو، گوجه کبابی، کره و سماق سرو کنید.']],
 m:'chelo,salad-shirazi,doogh'});

R({id:'kabab-tabei',c:'kebab',min:40,sv:4,n:[450,30,16,30],app:'stove',
 t:['Kabab tabei','کباب تابه‌ای'],d:['Pan kebab — kebab night without a grill.','کباب تابه‌ای، کباب بدون منقل'],
 i:'ground meat:500:g;onion:1;tomato:3;potato:2::o;turmeric:1:tsp:s;salt::taste:s;black pepper::taste:s;oil:2:tbsp:s',
 s:[[40,'Grate the onion, squeeze it dry, and knead it with the meat, turmeric, salt and pepper.','پیاز رنده‌شده و آب‌گرفته را با گوشت، زردچوبه، نمک و فلفل ورز دهید.'],
  [30,'Press the meat into a large pan in an even layer and score it into strips.','گوشت را در تابه بزرگ یکدست پهن کنید و با کارد به شکل نوار خط بیندازید.'],
  [25,'Cook covered on medium heat for 10 minutes, pour off the juices, add tomato halves and potato slices, and cook 10 minutes more.','با درِ بسته روی حرارت متوسط ۱۰ دقیقه بپزید، آبش را خالی کنید، گوجه و سیب‌زمینی را اضافه کنید و ۱۰ دقیقه دیگر بپزید.'],
  [0,'Serve with rice or bread.','با برنج یا نان سرو کنید.']],
 m:'kateh,salad-shirazi,doogh'});

R({id:'ash-reshteh',c:'soup',min:180,sv:6,n:[420,17,62,12],app:'stove',
 t:['Ash reshteh','آش رشته'],d:['Herb, bean and noodle soup with kashk and fried mint.','آش رشته با کشک، پیازداغ و نعناع‌داغ'],
 i:'herbs:4:cup;spinach:2:cup;reshteh:200:g;chickpeas:0.33:cup;kidney beans:0.33:cup;lentils:0.33:cup;onion:3;garlic:6:clove;kashk:1:cup;dried mint:2:tbsp;turmeric:1:tsp:s;oil:6:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[180,'Soak the chickpeas and beans overnight, then simmer them in 10 cups of water with the turmeric for 1½ hours.','نخود و لوبیا را از شب قبل خیس کنید و با ۱۰ پیمانه آب و زردچوبه یک ساعت و نیم بپزید.'],
  [90,'Add the lentils and cook 20 minutes.','عدس را اضافه کنید و ۲۰ دقیقه بپزید.'],
  [70,'Add the chopped herbs and spinach with salt and pepper, and simmer 30 minutes.','سبزی خردشده و اسفناج را با نمک و فلفل اضافه کنید و ۳۰ دقیقه بپزید.'],
  [50,'Meanwhile fry the sliced onions until golden, then the garlic, and bloom the dried mint in hot oil for a few seconds (nana dagh).','در این فاصله پیازداغ و سیرداغ درست کنید و نعناع خشک را چند ثانیه در روغن داغ تفت دهید (نعناع‌داغ).'],
  [30,'Break in the reshteh noodles with half the fried onion, and cook until the noodles are soft and the ash is thick.','رشته را بشکنید و همراه نصف پیازداغ اضافه کنید تا رشته بپزد و آش غلیظ شود.'],
  [0,'Serve in bowls topped with kashk, fried onion, garlic and mint.','در کاسه بکشید و با کشک، پیازداغ، سیرداغ و نعناع‌داغ تزیین کنید.']],
 m:''});

R({id:'adasi',c:'soup',min:50,sv:4,n:[330,18,50,7],app:'stove',
 t:['Adasi','عدسی'],d:['Creamy lentil soup — the winter breakfast.','عدسی گرم و لعاب‌دار، صبحانه زمستانی'],
 i:'lentils:1.5:cup;onion:1;potato:1::o;cumin:1:tsp:o;lemon:1::o;dried mint:1:tsp:o;bread:2::o;turmeric:1:tsp:s;oil:3:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[50,'Rinse the lentils and simmer them with 5 cups of water and the turmeric for 30 minutes.','عدس را بشویید و با ۵ پیمانه آب و زردچوبه ۳۰ دقیقه بپزید.'],
  [25,'Fry the chopped onion in oil until golden.','پیاز خردشده را در روغن طلایی کنید.'],
  [15,'Add half the onion, the cumin, salt and pepper, and cook until thick and creamy, mashing a little.','نصف پیازداغ، زیره، نمک و فلفل را اضافه کنید و بپزید تا غلیظ و لعاب‌دار شود؛ کمی له کنید.'],
  [0,'Serve with the rest of the onion, a squeeze of lemon and bread.','با باقی پیازداغ، کمی آبلیمو و نان سرو کنید.']],
 m:''});

R({id:'soup-jo',c:'soup',min:60,sv:4,n:[280,18,34,8],app:'stove',
 t:['Soup-e jo','سوپ جو'],d:['Barley and chicken soup with lemon.','سوپ جو با مرغ و لیمو'],
 i:'barley:0.5:cup;chicken:250:g;carrot:1;onion:1;lemon:1;parsley:0.5:cup;tomato paste:1:tbsp:o;cream:0.5:cup:o;turmeric:1:tsp:s;oil:2:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[60,'Rinse the barley. Fry the onion, add the turmeric and the diced chicken, then the barley and 6 cups of water. Simmer 40 minutes.','جو را بشویید. پیاز را تفت دهید، زردچوبه و مرغ خردشده، سپس جو و ۶ پیمانه آب را اضافه کنید و ۴۰ دقیقه بپزید.'],
  [25,'Add the grated carrot and tomato paste and cook 15 minutes more.','هویج رنده‌شده و رب را اضافه کنید و ۱۵ دقیقه دیگر بپزید.'],
  [8,'Stir in the chopped parsley, lemon juice and a splash of cream if you like.','جعفری خردشده، آبلیمو و در صورت تمایل کمی خامه اضافه کنید.'],
  [0,'Serve hot.','داغ سرو کنید.']],
 m:''});

R({id:'nimroo',c:'breakfast',min:10,sv:2,n:[220,14,2,17],app:'stove',
 t:['Nimroo','نیمرو'],d:['Fried eggs with runny yolks — breakfast in 10 minutes.','نیمرو، صبحانه ده‌دقیقه‌ای'],
 i:'eggs:4;butter:1:tbsp:o;bread:2::o;tomato:1::o;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s;turmeric::pinch:s',
 s:[[10,'Heat butter or oil in a pan over medium heat.','کره یا روغن را در تابه روی حرارت متوسط داغ کنید.'],
  [7,'Crack in the eggs, season with salt, pepper and a pinch of turmeric, cover and cook 3–4 minutes until the whites set.','تخم‌مرغ‌ها را بشکنید، نمک و فلفل و کمی زردچوبه بزنید، درش را بگذارید و ۳ تا ۴ دقیقه بپزید تا سفیده ببندد.'],
  [0,'Serve with warm bread and tomato.','با نان تازه و گوجه سرو کنید.']],
 m:'chai'});

R({id:'noon-panir-sabzi',c:'breakfast',min:5,sv:2,n:[380,15,36,20],app:'',
 t:['Bread, cheese & herbs','نان و پنیر و سبزی'],d:['Warm bread, white cheese, fresh herbs and walnuts.','نان تازه، پنیر، سبزی خوردن و گردو'],
 i:'bread:2;cheese:100:g;herbs:1:cup;walnuts:0.25:cup;cucumber:1::o;tomato:1::o',
 s:[[5,'Wash and dry the herbs; slice the cucumber and tomato.','سبزی را بشویید و خشک کنید؛ خیار و گوجه را حلقه کنید.'],
  [0,'Wrap cheese, herbs and walnuts in warm bread.','پنیر، سبزی و گردو را لای نان تازه بپیچید.']],
 m:'chai'});

R({id:'halim',c:'breakfast',min:240,sv:6,n:[420,28,48,12],app:'stove',
 t:['Halim','حلیم'],d:['Slow wheat and meat porridge with cinnamon and butter.','حلیم گندم و گوشت با دارچین و کره'],
 i:'wheat:1.5:cup;chicken|lamb:500:g;onion:1;cinnamon:1:tsp;butter:3:tbsp:o;sugar:3:tbsp:o;salt::taste:s',
 s:[[240,'Soak the wheat overnight, then boil it in plenty of water for 2 hours, stirring now and then.','گندم را از شب قبل خیس کنید و در آب فراوان ۲ ساعت بپزید و گاهی هم بزنید.'],
  [230,'Separately, simmer the meat with the onion and salt for 2 hours, until it falls apart.','جداگانه گوشت را با پیاز و نمک ۲ ساعت بپزید تا کاملاً نرم شود.'],
  [120,'Shred the meat and pound or blend it with the wheat until stringy and smooth.','گوشت را ریش‌ریش کنید و با گندم بکوبید یا در غذاساز بزنید تا کش‌دار و یکدست شود.'],
  [90,'Return it to the pot with some of the broth and cook on low, stirring often, until thick and elastic.','با کمی آب گوشت به قابلمه برگردانید و با حرارت ملایم و هم زدن مداوم بپزید تا غلیظ و کش‌دار شود.'],
  [0,'Serve with melted butter, cinnamon and sugar.','با کره آب‌شده، دارچین و شکر سرو کنید.']],
 m:'chai'});

R({id:'kotlet',c:'main',min:50,sv:4,n:[420,24,24,26],app:'stove|air fryer',
 t:['Kotlet','کتلت'],d:['Pan-fried meat and potato patties.','کتلت گوشت و سیب‌زمینی'],
 i:'ground meat:400:g;potato:2;onion:1;eggs:1;breadcrumbs:0.5:cup:o;turmeric:1:tsp:s;salt::taste:s;black pepper::taste:s;oil:6:tbsp:s',
 s:[[50,'Boil the potatoes until tender, about 20 minutes, then peel and grate them.','سیب‌زمینی را ۲۰ دقیقه بپزید، پوست بگیرید و رنده کنید.'],
  [25,'Mix the meat, potato, grated and squeezed onion, egg, turmeric, salt and pepper into a soft dough.','گوشت، سیب‌زمینی، پیاز رنده‌شده و آب‌گرفته، تخم‌مرغ، زردچوبه، نمک و فلفل را خوب ورز دهید.'],
  [20,'Shape oval patties with wet hands, coat them in breadcrumbs and fry 4 minutes a side until deep brown.','با دست خیس به شکل بیضی فرم دهید، به پودر سوخاری بزنید و هر طرف ۴ دقیقه سرخ کنید تا قهوه‌ای شود.'],
  [0,'Serve with bread, pickles and tomato.','با نان، خیارشور و گوجه سرو کنید.']],
 m:'salad-shirazi'});

R({id:'kuku-sabzi',c:'main',min:50,sv:4,n:[300,13,9,24],app:'stove|oven',
 t:['Kuku sabzi','کوکوسبزی'],d:['Herb frittata packed with greens.','کوکوسبزی پر از سبزی معطر'],
 i:'herbs:4:cup;eggs:5;walnuts:0.25:cup:o;barberries:2:tbsp:o;flour:1:tbsp:o;baking powder:0.5:tsp:o;turmeric:1:tsp:s;salt::taste:s;black pepper::taste:s;oil:4:tbsp:s',
 s:[[50,'Wash the herbs, dry them very well and chop them finely.','سبزی را بشویید، کاملاً خشک کنید و ریز خرد کنید.'],
  [35,'Beat the eggs with turmeric, salt, pepper, flour and baking powder, then fold in the herbs, walnuts and barberries.','تخم‌مرغ‌ها را با زردچوبه، نمک، فلفل، آرد و بکینگ‌پودر هم بزنید و سبزی، گردو و زرشک را اضافه کنید.'],
  [30,'Pour into a hot oiled pan, cover and cook on low 12–15 minutes. Cut into wedges, flip and cook 10 more — or bake at 180°C for 30 minutes.','در تابه روغنی داغ بریزید، درش را بگذارید و با حرارت ملایم ۱۲ تا ۱۵ دقیقه بپزید؛ برش بزنید، برگردانید و ۱۰ دقیقه دیگر بپزید (یا ۳۰ دقیقه در فر ۱۸۰ درجه).'],
  [0,'Serve warm or cold with bread and yogurt.','گرم یا سرد با نان و ماست سرو کنید.']],
 m:'mast-o-khiar'});

R({id:'kuku-sibzamini',c:'main',min:45,sv:4,n:[280,9,30,14],app:'stove',
 t:['Kuku sibzamini','کوکوسیب‌زمینی'],d:['Golden potato patties.','کوکوسیب‌زمینی طلایی'],
 i:'potato:3;eggs:3;onion:1::o;flour:1:tbsp:o;turmeric:1:tsp:s;salt::taste:s;black pepper::taste:s;oil:5:tbsp:s',
 s:[[45,'Boil the potatoes until tender, then peel and grate them.','سیب‌زمینی را بپزید، پوست بگیرید و رنده کنید.'],
  [20,'Mix with the eggs, grated onion, turmeric, salt and pepper.','با تخم‌مرغ، پیاز رنده‌شده، زردچوبه، نمک و فلفل مخلوط کنید.'],
  [15,'Fry spoonfuls as small patties, 3–4 minutes a side.','قاشق‌قاشق در تابه به شکل کوکوهای کوچک بریزید و هر طرف ۳ تا ۴ دقیقه سرخ کنید.'],
  [0,'Serve with bread, herbs and pickles.','با نان، سبزی و ترشی سرو کنید.']],
 m:'salad-shirazi'});

R({id:'mirza-ghasemi',c:'main',min:60,sv:4,n:[240,9,18,15],app:'stove',
 t:['Mirza ghasemi','میرزاقاسمی'],d:['Smoky eggplant with garlic, tomato and egg.','میرزاقاسمی دودی با سیر، گوجه و تخم‌مرغ'],
 i:'eggplant:4;tomato:3;garlic:6:clove;eggs:3;turmeric:1:tsp:s;salt::taste:s;black pepper::taste:s;oil:3:tbsp:s',
 s:[[60,'Char the whole eggplants over a flame or grill (or roast at 220°C for 40 minutes) until soft, then peel and chop them.','بادمجان‌ها را روی شعله یا منقل کبابی کنید (یا ۴۰ دقیقه در فر ۲۲۰ درجه) تا نرم شوند؛ پوست بگیرید و خرد کنید.'],
  [25,'Fry the crushed garlic, add the turmeric and eggplant, and cook 5 minutes.','سیر له‌شده را تفت دهید، زردچوبه و بادمجان را اضافه کنید و ۵ دقیقه تفت دهید.'],
  [20,'Add the grated tomatoes and cook until thick.','گوجه رنده‌شده را اضافه کنید و بپزید تا غلیظ شود.'],
  [8,'Push everything aside, scramble the eggs in the space, then fold it all together and season.','مواد را کنار بزنید، تخم‌مرغ را در وسط هم بزنید و سپس همه را مخلوط کنید و نمک و فلفل بزنید.'],
  [0,'Serve with bread or kateh.','با نان یا کته سرو کنید.']],
 m:'kateh,sabzi-khordan'});

R({id:'kashk-bademjan',c:'main',min:60,sv:4,n:[330,9,22,24],app:'stove',
 t:['Kashk bademjan','کشک بادمجان'],d:['Eggplant and kashk dip with fried mint.','کشک بادمجان با نعناع‌داغ'],
 i:'eggplant:4;onion:2;garlic:4:clove;kashk:0.75:cup;walnuts:0.25:cup;dried mint:1:tbsp;turmeric:1:tsp:s;salt::taste:s;oil:6:tbsp:s',
 s:[[60,'Peel the eggplants, slice them lengthwise and fry until golden (or roast them).','بادمجان‌ها را پوست بگیرید، از طول برش دهید و سرخ کنید (یا در فر کبابی کنید).'],
  [35,'Fry the onions until golden, then the garlic, and keep some aside for the top.','پیازداغ و سیرداغ درست کنید و کمی را برای تزیین کنار بگذارید.'],
  [25,'Mash the eggplants with the onion, garlic, turmeric and ½ cup of water, and simmer 10 minutes.','بادمجان را با پیازداغ، سیرداغ، زردچوبه و نصف پیمانه آب له کنید و ۱۰ دقیقه بپزید.'],
  [10,'Stir in most of the kashk and the chopped walnuts.','بیشتر کشک و گردوی خردشده را اضافه کنید.'],
  [0,'Top with kashk, fried onion, garlic and mint bloomed in oil, and serve with bread.','با کشک، پیازداغ، سیرداغ و نعناع‌داغ تزیین کنید و با نان سرو کنید.']],
 m:'sabzi-khordan'});

R({id:'omlet',c:'breakfast',min:20,sv:2,n:[260,14,12,18],app:'stove',
 t:['Omlet-e gojeh farangi','املت گوجه‌فرنگی'],d:['Eggs scrambled in a quick tomato sauce.','املت گوجه‌فرنگی، ساده و سریع'],
 i:'tomato:4;eggs:4;onion:1::o;garlic:1:clove:o;bread:2::o;turmeric:1:tsp:s;salt::taste:s;black pepper::taste:s;oil:2:tbsp:s',
 s:[[20,'Fry the chopped onion (and garlic) until soft.','پیاز (و سیر) خردشده را تفت دهید تا نرم شود.'],
  [15,'Add the grated or chopped tomatoes with turmeric, salt and pepper, and cook until most of the liquid is gone.','گوجه رنده‌شده یا خردشده را با زردچوبه، نمک و فلفل اضافه کنید و بپزید تا آبش کشیده شود.'],
  [6,'Add the eggs and stir gently until just set.','تخم‌مرغ‌ها را اضافه کنید و آرام هم بزنید تا تازه ببندد.'],
  [0,'Serve straight from the pan with bread.','همان‌جا در تابه با نان سرو کنید.']],
 m:'chai'});

R({id:'makaroni',c:'main',min:60,sv:4,n:[620,30,82,20],app:'stove',
 t:['Makaroni','ماکارونی'],d:['Persian spaghetti with meat sauce and a crispy tahdig.','ماکارونی ایرانی با ته‌دیگ'],
 i:'pasta:500:g;ground meat:400:g;onion:1;tomato paste:4:tbsp;bell pepper:1::o;potato:1::o;saffron:0.25:tsp:o;turmeric:1:tsp:s;oil:5:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[60,'Fry the onion, add the turmeric and ground meat and brown it. Add the pepper, tomato paste and 1 cup of water, and simmer 15 minutes.','پیاز را تفت دهید، زردچوبه و گوشت چرخ‌کرده را اضافه و سرخ کنید؛ فلفل دلمه، رب و یک پیمانه آب را اضافه کنید و ۱۵ دقیقه بپزید.'],
  [40,'Boil the spaghetti in salted water for 6 minutes and drain.','ماکارونی را ۶ دقیقه در آب‌نمک بجوشانید و آبکش کنید.'],
  [35,'Oil the pot, line it with potato slices, then layer the pasta and sauce.','ته قابلمه روغن بریزید، سیب‌زمینی حلقه‌ای بچینید و ماکارونی و سس را لایه‌لایه بریزید.'],
  [30,'Cover with a towel-wrapped lid and steam on low for 30 minutes for a crispy tahdig.','درِ دم‌کنی بگذارید و ۳۰ دقیقه با حرارت ملایم دم بکشد تا ته‌دیگ ترد شود.'],
  [0,'Serve with the tahdig and a salad.','با ته‌دیگ و سالاد سرو کنید.']],
 m:'salad-shirazi,doogh'});

R({id:'yatimcheh',c:'main',min:45,sv:4,n:[280,5,28,17],app:'stove',
 t:['Yatimcheh','یتیمچه'],d:['Eggplant, potato and tomato stew — no meat needed.','یتیمچه بادمجان و گوجه، بدون گوشت'],
 i:'eggplant:3;tomato:3;potato:2::o;onion:1;garlic:3:clove;tomato paste:1:tbsp;turmeric:1:tsp:s;salt::taste:s;black pepper::taste:s;oil:6:tbsp:s',
 s:[[45,'Peel and dice the eggplants and potatoes, and fry them until golden.','بادمجان و سیب‌زمینی را پوست بگیرید، نگینی خرد کنید و طلایی سرخ کنید.'],
  [25,'Fry the onion and garlic, then add the turmeric and tomato paste.','پیاز و سیر را تفت دهید، زردچوبه و رب را اضافه کنید.'],
  [20,'Add the fried vegetables and the diced tomatoes with salt and pepper; cover and cook 15 minutes.','سبزیجات سرخ‌شده و گوجه خردشده را با نمک و فلفل اضافه کنید و با درِ بسته ۱۵ دقیقه بپزید.'],
  [0,'Serve with kateh or bread.','با کته یا نان سرو کنید.']],
 m:'kateh,mast-o-khiar'});

R({id:'salad-shirazi',c:'side',min:15,sv:4,n:[60,2,10,2],app:'',
 t:['Salad shirazi','سالاد شیرازی'],d:['Cucumber, tomato and onion with lemon and mint.','سالاد شیرازی با آبلیمو و نعناع'],
 i:'cucumber:2;tomato:2;onion:1;lemon:1;dried mint:1:tsp:o;oil:1:tbsp:o;salt::taste:s',
 s:[[15,'Dice the cucumbers, tomatoes and onion small and evenly.','خیار، گوجه و پیاز را ریز و یکدست خرد کنید.'],
  [5,'Dress with lemon juice, dried mint, salt and a little olive oil.','با آبلیمو، نعناع خشک، نمک و کمی روغن زیتون مزه‌دار کنید.'],
  [0,'Serve cold.','خنک سرو کنید.']],
 m:''});

R({id:'mast-o-khiar',c:'side',min:10,sv:4,n:[110,6,10,5],app:'',
 t:['Mast-o-khiar','ماست‌وخیار'],d:['Yogurt with cucumber, mint and raisins.','ماست‌وخیار با نعناع و کشمش'],
 i:'yogurt:2:cup;cucumber:2;dried mint:1:tsp;walnuts:2:tbsp:o;raisins:2:tbsp:o;salt::taste:s',
 s:[[10,'Grate or finely dice the cucumbers.','خیار را رنده یا ریز خرد کنید.'],
  [5,'Stir them into the yogurt with the dried mint, salt, walnuts and raisins.','با ماست، نعناع خشک، نمک، گردو و کشمش مخلوط کنید.'],
  [0,'Keep cold until you serve.','تا زمان سرو در یخچال بگذارید.']],
 m:''});

R({id:'borani-esfenaj',c:'side',min:20,sv:4,n:[120,8,8,6],app:'stove',
 t:['Borani esfenaj','بورانی اسفناج'],d:['Spinach and garlic yogurt.','بورانی اسفناج با سیر'],
 i:'spinach:400:g;yogurt:2:cup;garlic:2:clove;onion:1::o;salt::taste:s;black pepper::taste:s;oil:1:tbsp:s',
 s:[[20,'Wilt the washed spinach in a dry pot, squeeze out the water and chop it.','اسفناج شسته‌شده را در قابلمه بدون آب بپزید تا بخوابد، آبش را بگیرید و خرد کنید.'],
  [10,'Fry the garlic (and onion) briefly, add the spinach and cook 3 minutes, then let it cool.','سیر (و پیاز) را کمی تفت دهید، اسفناج را اضافه کنید و ۳ دقیقه تفت دهید؛ بگذارید خنک شود.'],
  [5,'Stir into the yogurt with salt and pepper.','با ماست، نمک و فلفل مخلوط کنید.'],
  [0,'Serve cool.','خنک سرو کنید.']],
 m:''});

R({id:'olivieh',c:'salad',min:90,sv:6,n:[420,14,22,30],app:'stove',
 t:['Salad olivieh','سالاد الویه'],d:['Potato, egg and chicken salad with pickles.','سالاد الویه با مرغ و خیارشور'],
 i:'potato:4;eggs:4;chicken:300:g;pickles:4;mayonnaise:1:cup;peas:0.5:cup:o;carrot:1::o;lemon:1::o;salt::taste:s;black pepper::taste:s',
 s:[[90,'Boil the potatoes and eggs (and the carrot), and poach the chicken with salt for 30 minutes.','سیب‌زمینی و تخم‌مرغ (و هویج) را آب‌پز کنید و مرغ را با نمک ۳۰ دقیقه بپزید.'],
  [50,'Peel and grate or dice the potatoes and eggs, shred the chicken and dice the pickles.','سیب‌زمینی و تخم‌مرغ را پوست بگیرید و رنده یا ریز کنید؛ مرغ را ریش‌ریش و خیارشور را خرد کنید.'],
  [40,'Mix everything with the mayonnaise, lemon juice, salt and pepper, and chill 30 minutes.','همه را با سس مایونز، آبلیمو، نمک و فلفل مخلوط کنید و ۳۰ دقیقه در یخچال بگذارید.'],
  [0,'Serve in bread or with pickles.','لای نان یا با خیارشور سرو کنید.']],
 m:''});

R({id:'sabzi-khordan',c:'side',min:10,sv:4,n:[80,4,4,6],app:'',
 t:['Sabzi khordan','سبزی خوردن'],d:['A plate of fresh herbs, radishes and cheese.','سبزی خوردن با تربچه و پنیر'],
 i:'herbs:2:cup;radish:6::o;cheese:100:g:o;walnuts:0.25:cup:o',
 s:[[10,'Wash the herbs well, pick off the tough stems and dry them.','سبزی را خوب بشویید، ساقه‌های سفت را جدا کنید و خشک کنید.'],
  [0,'Arrange on a plate with radishes, cheese and walnuts.','با تربچه، پنیر و گردو در بشقاب بچینید.']],
 m:''});

R({id:'sholeh-zard',c:'dessert',min:90,sv:6,n:[320,4,68,5],app:'stove',
 t:['Sholeh zard','شله‌زرد'],d:['Saffron and rose water rice pudding.','شله‌زرد با زعفران و گلاب'],
 i:'rice:0.75:cup;sugar:1.25:cup;saffron:0.5:tsp;rose water:0.33:cup;butter:2:tbsp;cardamom:0.5:tsp:o;almonds:2:tbsp:o;pistachios:2:tbsp:o;cinnamon::pinch:o',
 s:[[90,'Rinse the rice and simmer it in 7 cups of water, stirring now and then, until very soft and creamy — about 45 minutes.','برنج را بشویید و در ۷ پیمانه آب بپزید و گاهی هم بزنید تا کاملاً نرم و لعاب‌دار شود؛ حدود ۴۵ دقیقه.'],
  [45,'Add the sugar and cook 15 minutes.','شکر را اضافه کنید و ۱۵ دقیقه بپزید.'],
  [30,'Stir in the saffron, rose water, butter, cardamom and slivered almonds, and cook on low 15 minutes.','زعفران، گلاب، کره، هل و خلال بادام را اضافه کنید و ۱۵ دقیقه با حرارت ملایم بپزید.'],
  [15,'Pour into bowls and let it set.','در کاسه‌ها بکشید تا ببندد.'],
  [0,'Decorate with cinnamon and pistachios.','با دارچین و خلال پسته تزیین کنید.']],
 m:''});

R({id:'shir-berenj',c:'dessert',min:60,sv:4,n:[260,9,44,6],app:'stove',
 t:['Shir berenj','شیربرنج'],d:['Creamy milk and rice pudding.','شیربرنج گرم و خامه‌ای'],
 i:'rice:0.5:cup;milk:4:cup;rose water:2:tbsp:o;cardamom:0.25:tsp:o;sugar:0.33:cup:o;honey|jam:::o',
 s:[[60,'Simmer the rinsed rice in 1½ cups of water until soft, about 20 minutes.','برنج شسته‌شده را در یک و نیم پیمانه آب بپزید تا نرم شود؛ حدود ۲۰ دقیقه.'],
  [40,'Add the milk and cook on low, stirring often, until thick and creamy — about 30 minutes.','شیر را اضافه کنید و با حرارت ملایم و هم زدن مداوم بپزید تا غلیظ شود؛ حدود ۳۰ دقیقه.'],
  [10,'Stir in the rose water and cardamom.','گلاب و هل را اضافه کنید.'],
  [0,'Serve warm or cold with sugar, honey or jam.','گرم یا سرد با شکر، عسل یا مربا سرو کنید.']],
 m:''});

R({id:'halva',c:'dessert',min:30,sv:8,n:[290,3,40,13],app:'stove',
 t:['Halva','حلوا'],d:['Toasted flour sweet with saffron and rose water.','حلوای زعفرانی با گلاب'],
 i:'flour:1:cup;butter:0.5:cup;sugar:0.75:cup;saffron:0.5:tsp;rose water:0.33:cup;cardamom:0.5:tsp:o;almonds|pistachios:2:tbsp:o',
 s:[[30,'Make the syrup: dissolve the sugar in ½ cup of hot water and add the saffron and rose water.','شربت را آماده کنید: شکر را در نصف پیمانه آب داغ حل کنید و زعفران و گلاب را اضافه کنید.'],
  [25,'Toast the flour in a dry pan over low-medium heat, stirring constantly, until nutty and light brown — about 15 minutes.','آرد را در تابه خشک با حرارت ملایم و هم زدن مداوم تفت دهید تا قهوه‌ای روشن و معطر شود؛ حدود ۱۵ دقیقه.'],
  [10,'Stir in the melted butter until smooth, then carefully add the syrup and keep stirring until it pulls away from the pan.','کره آب‌شده را اضافه کنید تا یکدست شود، سپس با احتیاط شربت را بریزید و هم بزنید تا از کناره‌ها جدا شود.'],
  [0,'Spread on a plate, make a pattern with a spoon and decorate with nuts.','در دیس پهن کنید، با قاشق نقش بیندازید و با مغزها تزیین کنید.']],
 m:'chai'});

R({id:'fereni',c:'dessert',min:20,sv:4,n:[200,7,32,5],app:'stove',
 t:['Fereni','فرنی'],d:['Silky rice-flour and rose water pudding.','فرنی نرم با گلاب'],
 i:'rice flour:4:tbsp;milk:3:cup;sugar:4:tbsp;rose water:2:tbsp;cardamom::pinch:o;pistachios:1:tbsp:o',
 s:[[20,'Whisk the rice flour into ½ cup of cold milk until smooth.','آرد برنج را در نصف پیمانه شیر سرد حل کنید تا یکدست شود.'],
  [15,'Warm the rest of the milk with the sugar, whisk in the rice-flour mixture and cook on low, stirring, until thick — about 10 minutes.','باقی شیر را با شکر گرم کنید، مخلوط آرد برنج را اضافه کنید و با هم زدن مداوم روی حرارت ملایم بپزید تا غلیظ شود؛ حدود ۱۰ دقیقه.'],
  [5,'Add the rose water and cardamom.','گلاب و هل را اضافه کنید.'],
  [0,'Serve warm or chilled with pistachios.','گرم یا سرد با پسته سرو کنید.']],
 m:''});

R({id:'cake-yazdi',c:'dessert',min:45,sv:12,n:[230,4,30,11],app:'oven',
 t:['Cake yazdi','کیک یزدی'],d:['Cardamom and rose water cupcakes from Yazd.','کیک یزدی با هل و گلاب'],
 i:'flour:1.5:cup;sugar:1:cup;eggs:3;yogurt:0.5:cup;oil:0.5:cup;cardamom:1:tsp;rose water:2:tbsp;baking powder:1:tsp;pistachios:2:tbsp:o',
 s:[[45,'Heat the oven to 180°C (350°F) and line a muffin tin.','فر را روی ۱۸۰ درجه گرم کنید و قالب کاپ‌کیک را آماده کنید.'],
  [40,'Beat the eggs and sugar until pale, then beat in the oil, yogurt, rose water and cardamom.','تخم‌مرغ و شکر را هم بزنید تا کرم‌رنگ شود، سپس روغن، ماست، گلاب و هل را اضافه کنید.'],
  [30,'Fold in the flour and baking powder, fill the cups two-thirds full and sprinkle with pistachios.','آرد و بکینگ‌پودر را آرام مخلوط کنید، قالب‌ها را تا دو سوم پر کنید و پسته بپاشید.'],
  [25,'Bake 20–25 minutes, until golden and a toothpick comes out clean.','۲۰ تا ۲۵ دقیقه بپزید تا طلایی شود و خلال دندان تمیز بیرون بیاید.'],
  [0,'Let them cool and serve with tea.','بگذارید خنک شود و با چای سرو کنید.']],
 m:'chai'});

R({id:'doogh',c:'drink',min:5,sv:4,n:[75,4,6,4],app:'',
 t:['Doogh','دوغ'],d:['Salty yogurt drink with mint.','دوغ خنک با نعناع'],
 i:'yogurt:2:cup;dried mint:1:tsp;salt::taste:s',
 s:[[5,'Whisk the yogurt with 2 cups of cold water (or sparkling water) and salt until smooth.','ماست را با ۲ پیمانه آب سرد (یا آب گازدار) و نمک هم بزنید تا یکدست شود.'],
  [2,'Add the dried mint and some ice.','نعناع خشک و یخ اضافه کنید.'],
  [0,'Serve cold.','خنک سرو کنید.']],
 m:''});

R({id:'sekanjabin',c:'drink',min:30,sv:6,n:[120,0,31,0],app:'stove',
 t:['Sharbat sekanjabin','شربت سکنجبین'],d:['Mint and vinegar syrup — the cool summer drink.','شربت سکنجبین خنک تابستانی'],
 i:'sugar:2:cup;vinegar:0.5:cup;mint:1:bunch;cucumber:1::o',
 s:[[30,'Dissolve the sugar in 1 cup of water and bring to a boil.','شکر را در یک پیمانه آب حل کنید و بجوشانید.'],
  [20,'Add the vinegar and simmer 15 minutes, until syrupy.','سرکه را اضافه کنید و ۱۵ دقیقه بجوشد تا قوام بیاید.'],
  [5,'Take it off the heat, add the mint, let it cool and lift the mint out.','از روی حرارت بردارید، نعناع را اضافه کنید تا خنک شود و سپس نعناع را خارج کنید.'],
  [0,'Mix 3 tbsp of syrup with cold water, ice and grated cucumber.','۳ قاشق شربت را با آب سرد، یخ و خیار رنده‌شده مخلوط کنید.']],
 m:''});

R({id:'chai',c:'drink',min:15,sv:4,n:[5,0,1,0],app:'stove',
 t:['Chai','چای'],d:['Brewed black tea with cardamom.','چای دم‌کشیده با هل'],
 i:'tea:4:tsp;cardamom:3::o;saffron::pinch:o;sugar:::o',
 s:[[15,'Boil fresh water in the kettle.','آب تازه را در کتری بجوشانید.'],
  [10,'Warm the teapot with hot water, add the tea leaves and cardamom, pour in the boiling water and let it brew on low heat for 10 minutes.','قوری را با آب داغ گرم کنید، چای و هل را بریزید، آب جوش را اضافه کنید و بگذارید ۱۰ دقیقه روی حرارت ملایم دم بکشد.'],
  [0,'Pour into glasses and serve with sugar cubes or dates.','در استکان بریزید و با قند یا خرما سرو کنید.']],
 m:''});

R({id:'shakshuka',c:'breakfast',min:25,sv:2,n:[320,17,18,20],app:'stove',x:1,
 t:['Shakshuka','شکشوکا'],d:['Eggs poached in a spiced tomato and pepper sauce.','تخم‌مرغ در سس گوجه و فلفل'],
 i:'eggs:4;tomato:4;onion:1;bell pepper:1;garlic:2:clove;cumin:1:tsp:o;chili flakes::pinch:o;cheese:50:g:o;bread:2::o;salt::taste:s;oil:2:tbsp:s;black pepper::taste:s',
 s:[[25,'Soften the onion, pepper and garlic in oil for 8 minutes.','پیاز، فلفل دلمه و سیر را ۸ دقیقه در روغن تفت دهید.'],
  [17,'Add the cumin, chili, chopped tomatoes and salt, and simmer until thick, about 8 minutes.','زیره، فلفل، گوجه خردشده و نمک را اضافه کنید و بپزید تا غلیظ شود؛ حدود ۸ دقیقه.'],
  [8,'Make little wells, crack in the eggs, cover and cook 5–6 minutes.','چند گودی ایجاد کنید، تخم‌مرغ‌ها را بشکنید و با درِ بسته ۵ تا ۶ دقیقه بپزید.'],
  [0,'Crumble cheese on top and serve with bread.','پنیر را رویش خرد کنید و با نان سرو کنید.']],
 m:''});

R({id:'egg-fried-rice',c:'rice',min:20,sv:2,n:[450,14,62,15],app:'stove',x:1,
 t:['Egg fried rice','برنج سرخ‌شده با تخم‌مرغ'],d:['Leftover rice turned into dinner in 20 minutes.','برنج مانده، شام بیست‌دقیقه‌ای'],
 i:'rice:2:cup;eggs:2;soy sauce:2:tbsp:o;peas:0.5:cup:o;carrot:1::o;green onion:2::o;garlic:2:clove:o;oil:2:tbsp:s;salt::taste:s',
 s:[[20,'Use cold cooked rice — yesterday’s is perfect. Dice the carrot and slice the green onions.','از برنج پخته سرد استفاده کنید (برنج دیروز عالی است). هویج را نگینی و پیازچه را خرد کنید.'],
  [12,'Scramble the eggs in a very hot pan and set them aside.','تخم‌مرغ‌ها را در تابه داغ هم بزنید و کنار بگذارید.'],
  [10,'Stir-fry the garlic, carrot and peas for 3 minutes, then add the rice and toss until hot.','سیر، هویج و نخودفرنگی را ۳ دقیقه تفت دهید، برنج را اضافه کنید و هم بزنید تا داغ شود.'],
  [3,'Add the soy sauce, the eggs and the green onions.','سس سویا، تخم‌مرغ و پیازچه را اضافه کنید.'],
  [0,'Serve hot.','داغ سرو کنید.']],
 m:''});

R({id:'chicken-curry',c:'main',min:45,sv:4,n:[380,36,12,20],app:'stove',x:1,
 t:['Chicken curry','کاری مرغ'],d:['Simple chicken curry finished with yogurt.','کاری مرغ ساده با ماست'],
 i:'chicken:600:g;onion:1;garlic:3:clove;tomato:2;curry powder:2:tbsp;yogurt|cream:0.5:cup;oil:3:tbsp:s;salt::taste:s',
 s:[[45,'Fry the onion until golden, then add the garlic and curry powder for a minute.','پیاز را طلایی کنید، سیر و پودر کاری را یک دقیقه تفت دهید.'],
  [35,'Add the chicken pieces and brown them, then the chopped tomatoes.','تکه‌های مرغ را اضافه و سرخ کنید، سپس گوجه خردشده را بریزید.'],
  [25,'Add ½ cup of water, cover and simmer 20 minutes.','نصف پیمانه آب اضافه کنید و با درِ بسته ۲۰ دقیقه بپزید.'],
  [5,'Stir in the yogurt or cream off the heat, and season.','ماست یا خامه را بیرون از حرارت اضافه کنید و نمک بزنید.'],
  [0,'Serve with rice.','با برنج سرو کنید.']],
 m:'kateh'});

R({id:'pasta-pomodoro',c:'main',min:25,sv:4,n:[480,15,86,9],app:'stove',x:1,
 t:['Pasta pomodoro','پاستا با سس گوجه'],d:['Pasta in a fresh tomato and garlic sauce.','پاستا با سس گوجه‌فرنگی و سیر'],
 i:'pasta:400:g;tomato:6;garlic:3:clove;cheese:50:g:o;herbs:::o;oil:3:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[25,'Put a big pot of salted water on to boil.','قابلمه بزرگ آب‌نمک را روی گاز بگذارید تا بجوشد.'],
  [20,'Cook the garlic gently in oil, add the chopped tomatoes and salt, and simmer 15 minutes.','سیر را آرام در روغن تفت دهید، گوجه خردشده و نمک را اضافه کنید و ۱۵ دقیقه بپزید.'],
  [12,'Boil the pasta until al dente and save a cup of the cooking water.','پاستا را بجوشانید تا کمی سفت بماند؛ یک پیمانه از آبش را نگه دارید.'],
  [2,'Toss the pasta with the sauce and a splash of the pasta water.','پاستا را با سس و کمی آب پاستا مخلوط کنید.'],
  [0,'Serve with cheese.','با پنیر سرو کنید.']],
 m:''});

R({id:'roast-chicken',c:'main',min:90,sv:4,n:[620,48,34,32],app:'oven',x:1,
 t:['Roast chicken & potatoes','مرغ و سیب‌زمینی تنوری'],d:['Lemon and garlic roast chicken with potatoes.','مرغ و سیب‌زمینی تنوری با لیمو و سیر'],
 i:'chicken:1.5:kg;potato:4;lemon:1;garlic:6:clove;butter:2:tbsp:o;saffron::pinch:o;salt::taste:s;black pepper::taste:s;oil:3:tbsp:s',
 s:[[90,'Heat the oven to 200°C (400°F). Rub the chicken with butter, garlic, lemon, salt and pepper.','فر را روی ۲۰۰ درجه گرم کنید. مرغ را با کره، سیر، لیمو، نمک و فلفل ماساژ دهید.'],
  [80,'Toss the potato wedges with oil and salt and arrange them around the chicken in a roasting tray.','سیب‌زمینی‌های قاچ‌شده را با روغن و نمک اطراف مرغ در سینی فر بچینید.'],
  [75,'Roast about 70 minutes, basting once, until the juices run clear.','حدود ۷۰ دقیقه بپزید و یک بار روی آن را با آب خودش چرب کنید تا آب مرغ شفاف شود.'],
  [5,'Rest the chicken 5 minutes before carving.','۵ دقیقه صبر کنید و سپس تکه کنید.'],
  [0,'Serve with the potatoes and a salad.','با سیب‌زمینی و سالاد سرو کنید.']],
 m:'salad-shirazi'});

R({id:'pancakes',c:'breakfast',min:25,sv:4,n:[330,9,48,11],app:'stove',x:1,
 t:['Pancakes','پنکیک'],d:['Fluffy pancakes in 25 minutes.','پنکیک پفکی در ۲۵ دقیقه'],
 i:'flour:1.5:cup;milk:1.25:cup;eggs:1;baking powder:2:tsp;butter:2:tbsp;honey|jam:::o;sugar:2:tbsp:s;salt::pinch:s',
 s:[[25,'Whisk the flour, baking powder, sugar and salt.','آرد، بکینگ‌پودر، شکر و نمک را مخلوط کنید.'],
  [20,'Whisk in the milk, egg and melted butter until just combined.','شیر، تخم‌مرغ و کره آب‌شده را اضافه کنید و فقط تا یکدست شدن هم بزنید.'],
  [15,'Cook ladlefuls in a lightly oiled pan until bubbles form, flip and cook 1 minute more.','ملاقه‌ملاقه در تابه کمی چرب بریزید تا حباب بزند، برگردانید و یک دقیقه دیگر بپزید.'],
  [0,'Serve with honey or jam.','با عسل یا مربا سرو کنید.']],
 m:''});

/* ---------- quick dishes from one or two things (so even "I have an egg" gets real ideas) ---------- */
R({id:'boiled-eggs',c:'breakfast',min:15,sv:2,n:[145,13,1,10],app:'stove',x:1,
 t:['Boiled eggs','تخم‌مرغ آب‌پز'],d:['Soft, jammy or hard — timings that always work.','عسلی، نیم‌بند یا سفت؛ با زمان‌بندی دقیق'],
 i:'eggs:4;bread:2::o;salt::taste:s;black pepper::taste:s',
 s:[[15,'Bring a small pot of water to a gentle boil and lower the eggs in with a spoon.','آب را در قابلمه‌ی کوچکی به جوش ملایم برسانید و تخم‌مرغ‌ها را با قاشق آرام داخل آب بگذارید.'],
  [12,'Boil 6 minutes for soft and runny, 8 for jammy, 10–11 for hard.','برای عسلی ۶ دقیقه، برای نیم‌بند ۸ دقیقه و برای سفت ۱۰ تا ۱۱ دقیقه بجوشانید.'],
  [3,'Move them straight into cold water for 2 minutes so they peel easily.','بلافاصله ۲ دقیقه در آب سرد بگذارید تا راحت پوست کنده شوند.'],
  [0,'Peel, sprinkle with salt and pepper and serve with bread.','پوست بگیرید، نمک و فلفل بزنید و با نان سرو کنید.']],
 m:'chai'});

R({id:'scrambled-eggs',c:'breakfast',min:8,sv:2,n:[210,14,2,16],app:'stove',x:1,
 t:['Soft scrambled eggs','تخم‌مرغ هم‌زده'],d:['Creamy eggs cooked low and slow — 8 minutes.','تخم‌مرغ نرم و کرمی روی حرارت ملایم؛ هشت‌دقیقه‌ای'],
 i:'eggs:4;butter:1:tbsp:o;milk:2:tbsp:o;chives:1:tbsp:o;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[8,'Beat the eggs with a pinch of salt (and a splash of milk).','تخم‌مرغ‌ها را با کمی نمک (و کمی شیر) هم بزنید.'],
  [6,'Melt butter or oil in a pan over low heat, pour in the eggs and stir slowly with a spatula.','کره یا روغن را در تابه روی حرارت ملایم آب کنید، تخم‌مرغ را بریزید و با کفگیر آرام هم بزنید.'],
  [2,'Take the pan off the heat while they still look a little wet — they finish cooking on their own.','وقتی هنوز کمی خیس به نظر می‌رسد تابه را از روی حرارت بردارید؛ خودش جا می‌افتد.'],
  [0,'Season with pepper and chives and serve on toast.','فلفل و تره بزنید و روی نان تست سرو کنید.']],
 m:'chai'});

R({id:'folded-omelette',c:'breakfast',min:10,sv:1,n:[300,19,2,24],app:'stove',x:1,
 t:['Folded omelette','املت ساده‌ی تاشده'],d:['A plain omelette — add cheese or herbs if you have them.','املت ساده؛ اگر پنیر یا سبزی دارید اضافه کنید'],
 i:'eggs:3;butter:1:tbsp:o;cheese:30:g:o;herbs:2:tbsp:o;oil:1:tsp:s;salt::taste:s;black pepper::taste:s',
 s:[[10,'Beat the eggs well with a pinch of salt and pepper.','تخم‌مرغ‌ها را با کمی نمک و فلفل خوب هم بزنید.'],
  [7,'Heat butter or oil in a non-stick pan over medium heat and pour in the eggs.','کره یا روغن را در تابه‌ی نچسب روی حرارت متوسط داغ کنید و تخم‌مرغ را بریزید.'],
  [5,'As it sets, pull the edges to the middle and tilt the pan so raw egg runs underneath.','هرچه لبه‌ها می‌بندد آن‌ها را به وسط بکشید و تابه را کج کنید تا تخم‌مرغ خام زیرش برود.'],
  [2,'While the top is still a little soft, add cheese or herbs to one half and fold it over.','وقتی رویش هنوز کمی نرم است، پنیر یا سبزی را روی یک نیمه بریزید و املت را تا کنید.'],
  [0,'Slide onto a plate and serve.','در بشقاب بکشید و سرو کنید.']],
 m:'chai'});

R({id:'poached-eggs',c:'breakfast',min:10,sv:1,n:[150,13,1,10],app:'stove',x:1,
 t:['Poached eggs on toast','تخم‌مرغ پوشه روی نان تست'],d:['Silky eggs cooked in barely simmering water.','تخم‌مرغ لطیف که در آب با جوش ملایم می‌پزد'],
 i:'eggs:2;bread:2::o;vinegar:1:tbsp:o;butter:1:tbsp:o;salt::taste:s;black pepper::taste:s',
 s:[[10,'Bring a deep pan of water to a bare simmer and add the vinegar.','آب را در تابه‌ی گود یا قابلمه به جوش خیلی ملایم برسانید و سرکه را اضافه کنید.'],
  [7,'Crack each egg into a cup, stir the water into a gentle swirl and slide the egg into the middle.','هر تخم‌مرغ را در فنجانی بشکنید، آب را آرام بچرخانید و تخم‌مرغ را وسط گرداب بریزید.'],
  [4,'Cook 3 minutes, until the white is set but the yolk is soft. Toast and butter the bread meanwhile.','۳ دقیقه بپزید تا سفیده ببندد ولی زرده نرم بماند. در این فاصله نان را تست کنید و کره بمالید.'],
  [0,'Lift out with a slotted spoon, drain, season and serve on the toast.','با کفگیر سوراخ‌دار بیرون بیاورید، آبش را بگیرید، نمک و فلفل بزنید و روی نان تست سرو کنید.']],
 m:'chai'});

R({id:'tamagoyaki',c:'breakfast',min:15,sv:2,n:[190,13,4,13],app:'stove',x:1,
 t:['Tamagoyaki (rolled omelette)','تاماگویاکی (املت لوله‌ای)'],d:['Sweet-savory Japanese omelette rolled in thin layers.','املت شیرین و شور ژاپنی که لایه‌لایه لوله می‌شود'],
 i:'eggs:4;soy sauce:1:tsp:o;sugar:2:tsp:s;salt::pinch:s;oil:1:tbsp:s',
 s:[[15,'Beat the eggs with the sugar, a pinch of salt and the soy sauce.','تخم‌مرغ‌ها را با شکر، کمی نمک و سس سویا هم بزنید.'],
  [12,'Oil a small pan over medium-low heat and pour in a thin layer of egg.','تابه‌ی کوچکی را روی حرارت ملایم چرب کنید و لایه‌ی نازکی از تخم‌مرغ بریزید.'],
  [10,'When it’s almost set, roll it to one side. Oil the pan, pour in another thin layer, lift the roll so egg runs under it, and roll again.','وقتی تقریباً بست، آن را به یک طرف لوله کنید. تابه را دوباره چرب کنید، لایه‌ی نازک دیگری بریزید، لوله را کمی بلند کنید تا تخم‌مرغ زیرش برود و دوباره لوله کنید.'],
  [3,'Repeat until the egg is used up, then let it rest 2 minutes.','تا تمام شدن تخم‌مرغ تکرار کنید و بعد ۲ دقیقه بگذارید بماند.'],
  [0,'Slice into thick pieces and serve warm or cold.','برش‌های پهن بزنید و گرم یا سرد سرو کنید.']],
 m:''});

R({id:'steamed-egg',c:'side',min:20,sv:2,n:[120,10,1,8],app:'stove|microwave',x:1,
 t:['Steamed egg custard','تخم‌مرغ بخارپز'],d:['Silky, savory egg — just eggs, water and salt.','تخم‌مرغ لطیف و شور؛ فقط با تخم‌مرغ، آب و نمک'],
 i:'eggs:3;green onion:1::o;soy sauce:1:tsp:o;salt::taste:s',
 s:[[20,'Beat the eggs with 1½ times their volume of warm water and ½ tsp salt. Strain for the smoothest result.','تخم‌مرغ‌ها را با یک‌ونیم برابر حجمشان آب ولرم و نصف قاشق چای‌خوری نمک هم بزنید. برای لطافت بیشتر صافش کنید.'],
  [17,'Pour into a heatproof bowl and cover with a plate.','در کاسه‌ی نسوز بریزید و رویش را با بشقاب بپوشانید.'],
  [15,'Steam over gently simmering water for 12–15 minutes (or microwave at medium power, a minute at a time) until just set.','روی آبِ در حال جوش ملایم ۱۲ تا ۱۵ دقیقه بخارپز کنید (یا در مایکروویو با قدرت متوسط، دقیقه‌به‌دقیقه) تا تازه ببندد.'],
  [0,'Top with sliced green onion and a few drops of soy sauce.','پیازچه‌ی خردشده و چند قطره سس سویا رویش بریزید.']],
 m:''});

R({id:'meringues',c:'dessert',min:100,sv:6,n:[70,1,17,0],app:'oven',x:1,
 t:['Meringue kisses','مرنگ'],d:['Crisp little meringues from egg whites and sugar.','شیرینی ترد و پفکی با سفیده‌ی تخم‌مرغ و شکر'],
 i:'eggs:2;vanilla:::o;sugar:0.5:cup:s',
 s:[[100,'Heat the oven to 100 °C. Separate the eggs — keep the yolks for scrambled eggs.','فر را روی ۱۰۰ درجه روشن کنید. سفیده و زرده را جدا کنید (زرده‌ها را برای تخم‌مرغ هم‌زده نگه دارید).'],
  [95,'Whisk the whites until foamy, then add the sugar a spoonful at a time and keep whisking until stiff and glossy.','سفیده‌ها را هم بزنید تا کف کند، بعد شکر را قاشق‌قاشق اضافه کنید و آن‌قدر هم بزنید تا سفت و براق شود.'],
  [85,'Spoon or pipe small mounds onto a lined tray.','با قاشق یا قیف، کپه‌های کوچک روی سینی کاغذکشیده بریزید.'],
  [80,'Bake about 70 minutes, until they lift off the paper easily. Let them cool in the oven.','حدود ۷۰ دقیقه بپزید تا راحت از کاغذ جدا شوند و بگذارید در همان فر خنک شوند.'],
  [0,'Serve, or keep them in an airtight jar.','سرو کنید یا در ظرف دربسته نگه دارید.']],
 m:'chai'});

R({id:'khagineh',c:'breakfast',min:20,sv:2,n:[420,14,50,20],app:'stove',
 t:['Khagineh','خاگینه'],d:['Sweet Persian egg cake soaked in saffron and rose water syrup.','خاگینه‌ی شیرین با شربت زعفران و گلاب'],
 i:'eggs:4;flour:2:tbsp;rose water:1:tbsp:o;saffron:0.25:tsp:o;cardamom:::o;sugar:0.33:cup:s;oil:3:tbsp:s',
 s:[[20,'Make the syrup: simmer the sugar with ⅓ cup water for 3 minutes, then add the saffron and rose water.','شربت را آماده کنید: شکر را با ⅓ پیمانه آب ۳ دقیقه بجوشانید، بعد زعفران و گلاب را اضافه کنید.'],
  [15,'Beat the eggs with the flour until smooth.','تخم‌مرغ‌ها را با آرد هم بزنید تا یکدست شود.'],
  [12,'Heat the oil in a pan, pour in the egg, cover and cook over low heat until the bottom is golden. Flip and brown the other side.','روغن را در تابه داغ کنید، مخلوط تخم‌مرغ را بریزید، درش را بگذارید و روی حرارت ملایم بپزید تا زیرش طلایی شود؛ برگردانید تا طرف دیگرش هم سرخ شود.'],
  [3,'Cut into wedges, pour the syrup over and let it soak in for a minute.','برش بزنید، شربت را رویش بریزید و یک دقیقه بگذارید به خورد خاگینه برود.'],
  [0,'Serve warm with tea.','گرم با چای سرو کنید.']],
 m:'chai'});

R({id:'eshkeneh',c:'soup',min:35,sv:4,n:[220,7,20,13],app:'stove',
 t:['Eshkeneh','اشکنه'],d:['Humble onion and egg soup with dried mint.','سوپ ساده‌ی پیاز و تخم‌مرغ با نعناع خشک'],
 i:'onion:2;eggs:3;flour:1:tbsp;dried mint:1:tbsp:o;fenugreek:1:tbsp:o;potato:1::o;bread:2::o;turmeric:1:tsp:s;oil:3:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[35,'Slice the onions thinly and fry in the oil until golden. Stir in the turmeric, flour and dried mint (and fenugreek) for a minute.','پیازها را نازک خلالی کنید و در روغن طلایی کنید. زردچوبه، آرد و نعناع خشک (و شنبلیله) را اضافه کنید و یک دقیقه تفت دهید.'],
  [28,'Add 4 cups of hot water (and the diced potato), salt and pepper. Simmer 20 minutes.','۴ پیمانه آب داغ (و سیب‌زمینی نگینی)، نمک و فلفل را اضافه کنید و ۲۰ دقیقه بگذارید بجوشد.'],
  [6,'Crack in the eggs one by one without stirring — or beat them first for threads of egg. Cook 5 minutes.','تخم‌مرغ‌ها را یکی‌یکی داخل سوپ بشکنید و هم نزنید؛ یا اول هم بزنید تا رشته‌رشته شود. ۵ دقیقه بپزید.'],
  [0,'Serve hot with bread torn into the bowl.','داغ با نان تریدشده سرو کنید.']],
 m:'sabzi-khordan'});

R({id:'nargesi',c:'main',min:25,sv:3,n:[210,12,9,15],app:'stove',
 t:['Nargesi (spinach and eggs)','نرگسی اسفناج'],d:['Spinach and onion with eggs set on top — quick and filling.','اسفناج و پیاز با تخم‌مرغ روی آن؛ سریع و سیرکننده'],
 i:'spinach:500:g;eggs:4;onion:1;garlic:2:clove:o;turmeric:1:tsp:s;oil:3:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[25,'Fry the chopped onion (and garlic) in the oil until golden, then stir in the turmeric.','پیاز (و سیر) خردشده را در روغن طلایی کنید و زردچوبه را اضافه کنید.'],
  [18,'Add the chopped spinach, salt and pepper and cook until wilted and the water is gone.','اسفناج خردشده، نمک و فلفل را اضافه کنید و بپزید تا بخوابد و آبش کشیده شود.'],
  [8,'Make small hollows and crack an egg into each. Cover and cook 5–6 minutes.','چند گودی کوچک درست کنید و در هر کدام یک تخم‌مرغ بشکنید. درش را بگذارید و ۵ تا ۶ دقیقه بپزید.'],
  [0,'Serve from the pan with bread.','در همان تابه با نان سرو کنید.']],
 m:'mast-o-khiar'});

R({id:'potato-eggs',c:'breakfast',min:25,sv:2,n:[360,13,33,20],app:'stove',
 t:['Potatoes and eggs','سیب‌زمینی و تخم‌مرغ'],d:['Crispy potato cubes with eggs cooked right in the pan.','سیب‌زمینی نگینی ترد با تخم‌مرغ در همان تابه'],
 i:'potato:2;eggs:3;onion:1::o;pickles:2::o;turmeric:0.5:tsp:s;oil:3:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[25,'Peel and dice the potatoes small (and slice the onion).','سیب‌زمینی‌ها را پوست بگیرید و ریز نگینی کنید (و پیاز را خلالی کنید).'],
  [20,'Fry them in the oil over medium heat, stirring now and then, until golden and tender — about 12 minutes.','در روغن روی حرارت متوسط سرخ کنید و گاهی هم بزنید تا طلایی و نرم شود؛ حدود ۱۲ دقیقه.'],
  [7,'Season with salt, pepper and turmeric, crack in the eggs, cover and cook until set.','نمک، فلفل و زردچوبه بزنید، تخم‌مرغ‌ها را رویش بشکنید، درش را بگذارید و بپزید تا ببندد.'],
  [0,'Serve hot with bread and pickles.','داغ با نان و خیارشور سرو کنید.']],
 m:'chai'});

R({id:'spanish-tortilla',c:'main',min:45,sv:4,n:[330,12,27,20],app:'stove',x:1,
 t:['Spanish tortilla','تورتیای اسپانیایی'],d:['Thick potato omelette — good hot or cold.','املت ضخیم سیب‌زمینی؛ هم گرم خوشمزه است هم سرد'],
 i:'potato:4;eggs:6;onion:1::o;oil:0.5:cup:s;salt::taste:s',
 s:[[45,'Slice the potatoes (and onion) thinly and cook them gently in the oil for 15–20 minutes, until soft but not brown.','سیب‌زمینی‌ها (و پیاز) را نازک حلقه کنید و در روغن روی حرارت ملایم ۱۵ تا ۲۰ دقیقه بپزید تا نرم شود ولی رنگ نگیرد.'],
  [25,'Drain off most of the oil. Beat the eggs with salt, mix in the potatoes and let it sit 5 minutes.','بیشتر روغن را خالی کنید. تخم‌مرغ‌ها را با نمک هم بزنید، سیب‌زمینی را اضافه کنید و ۵ دقیقه بگذارید بماند.'],
  [18,'Pour into a hot oiled pan and cook over low heat for about 8 minutes.','در تابه‌ی داغ و چرب بریزید و روی حرارت ملایم حدود ۸ دقیقه بپزید.'],
  [9,'Flip it using a plate and cook the other side for 4–5 minutes.','با کمک یک بشقاب برگردانید و طرف دیگر را ۴ تا ۵ دقیقه بپزید.'],
  [0,'Let it rest a few minutes and cut into wedges.','چند دقیقه بگذارید بماند و برش بزنید.']],
 m:'salad-shirazi'});

R({id:'french-toast',c:'breakfast',min:15,sv:2,n:[340,13,40,14],app:'stove',x:1,
 t:['French toast','نان تست فرانسوی'],d:['Bread soaked in egg and milk, fried golden.','نان خیس‌خورده در تخم‌مرغ و شیر، سرخ و طلایی'],
 i:'bread:4;eggs:2;milk:0.5:cup;cinnamon:0.5:tsp:o;butter:1:tbsp:o;honey|jam:::o;sugar:1:tbsp:s;oil:1:tbsp:s',
 s:[[15,'Whisk the eggs, milk, sugar and cinnamon in a wide dish.','تخم‌مرغ، شیر، شکر و دارچین را در ظرف پهنی هم بزنید.'],
  [12,'Heat butter or oil in a pan over medium heat.','کره یا روغن را در تابه روی حرارت متوسط داغ کنید.'],
  [10,'Dip each slice of bread in the egg for a few seconds on each side and fry 2–3 minutes a side until golden.','هر برش نان را چند ثانیه از هر طرف در مخلوط تخم‌مرغ بخوابانید و هر طرف ۲ تا ۳ دقیقه سرخ کنید تا طلایی شود.'],
  [0,'Serve with honey or jam.','با عسل یا مربا سرو کنید.']],
 m:'chai'});

R({id:'egg-sandwich',c:'breakfast',min:15,sv:2,n:[400,17,31,23],app:'stove',x:1,
 t:['Egg salad sandwich','ساندویچ سالاد تخم‌مرغ'],d:['Chopped boiled eggs and mayo in bread.','تخم‌مرغ آب‌پز خردشده با سس مایونز لای نان'],
 i:'eggs:4;mayonnaise:2:tbsp;bread:4;pickles:2::o;tomato:1::o;lettuce:::o;salt::taste:s;black pepper::taste:s',
 s:[[15,'Hard-boil the eggs for 10 minutes, then cool them in cold water.','تخم‌مرغ‌ها را ۱۰ دقیقه بجوشانید تا سفت شوند و در آب سرد خنک کنید.'],
  [4,'Peel and chop the eggs and mix with the mayonnaise, salt, pepper and chopped pickles.','پوست تخم‌مرغ‌ها را بگیرید، خرد کنید و با سس مایونز، نمک، فلفل و خیارشور خردشده مخلوط کنید.'],
  [0,'Spread on the bread with tomato and lettuce and close the sandwich.','با گوجه و کاهو لای نان بگذارید.']],
 m:''});

R({id:'egg-in-a-hole',c:'breakfast',min:10,sv:2,n:[230,9,15,15],app:'stove',x:1,
 t:['Egg in a hole','تخم‌مرغ در نان'],d:['An egg fried inside a slice of toast.','تخم‌مرغی که وسط برش نان سرخ می‌شود'],
 i:'bread:2;eggs:2;butter:1:tbsp:o;cheese:::o;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[10,'Cut a round hole in the middle of each slice of bread with the rim of a glass.','با لبه‌ی یک لیوان وسط هر برش نان را گرد ببُرید.'],
  [8,'Butter or oil a pan over medium heat, lay in the bread and crack an egg into each hole.','تابه را روی حرارت متوسط با کره یا روغن چرب کنید، نان‌ها را بگذارید و در سوراخ هر کدام یک تخم‌مرغ بشکنید.'],
  [5,'Cook 2–3 minutes, flip carefully and cook 1 minute more. Toast the cut-out circles alongside.','۲ تا ۳ دقیقه بپزید، با احتیاط برگردانید و یک دقیقه دیگر بپزید. دایره‌های نان را هم کنارش برشته کنید.'],
  [0,'Season and serve right away.','نمک و فلفل بزنید و فوراً سرو کنید.']],
 m:'chai'});

R({id:'deviled-eggs',c:'side',min:25,sv:3,n:[230,13,1,19],app:'stove',x:1,
 t:['Deviled eggs','تخم‌مرغ شکم‌پر'],d:['Boiled egg halves filled with a creamy yolk mix.','نیمه‌های تخم‌مرغ آب‌پز پرشده با مخلوط کرمی زرده'],
 i:'eggs:6;mayonnaise:3:tbsp;vinegar:1:tsp:o;chili flakes:::o;parsley:::o;salt::taste:s;black pepper::taste:s',
 s:[[25,'Hard-boil the eggs for 10 minutes, then cool completely in cold water.','تخم‌مرغ‌ها را ۱۰ دقیقه بجوشانید تا سفت شوند و در آب سرد کاملاً خنک کنید.'],
  [10,'Peel, halve lengthwise and pop the yolks into a bowl.','پوست بگیرید، از طول نصف کنید و زرده‌ها را در کاسه‌ای بریزید.'],
  [6,'Mash the yolks with the mayonnaise, vinegar, salt and pepper until smooth.','زرده‌ها را با سس مایونز، سرکه، نمک و فلفل له کنید تا یکدست شود.'],
  [0,'Spoon back into the whites and top with chili flakes or parsley.','مخلوط را با قاشق داخل سفیده‌ها بریزید و رویش پول‌بیبر یا جعفری بپاشید.']],
 m:''});

R({id:'egg-custard',c:'dessert',min:50,sv:4,n:[190,8,23,7],app:'oven',x:1,
 t:['Baked egg custard','کاسترد تخم‌مرغ'],d:['Smooth sweet custard from eggs, milk and sugar.','دسر لطیف با تخم‌مرغ، شیر و شکر'],
 i:'eggs:3;milk:2:cup;vanilla:::o;cinnamon:::o;sugar:0.33:cup:s',
 s:[[50,'Heat the oven to 160 °C and boil a kettle of water.','فر را روی ۱۶۰ درجه روشن کنید و کتری آب را بگذارید جوش بیاید.'],
  [45,'Warm the milk. Whisk the eggs with the sugar and vanilla, then slowly whisk in the warm milk.','شیر را گرم کنید. تخم‌مرغ‌ها را با شکر و وانیل هم بزنید و شیر گرم را کم‌کم در حال هم زدن اضافه کنید.'],
  [40,'Pour into small cups, set them in a deep tray and add hot water halfway up the cups.','در ظرف‌های کوچک بریزید، در سینی گودی بچینید و تا نیمه‌ی ظرف‌ها آب داغ بریزید.'],
  [35,'Bake about 30 minutes, until set at the edges but still a little wobbly in the middle.','حدود ۳۰ دقیقه بپزید تا لبه‌ها ببندد ولی وسطش هنوز کمی لرزان باشد.'],
  [0,'Dust with cinnamon and serve warm or chilled.','دارچین بپاشید و گرم یا سرد سرو کنید.']],
 m:''});

R({id:'banana-pancakes',c:'breakfast',min:15,sv:1,n:[260,13,28,11],app:'stove',x:1,
 t:['Banana pancakes','پنکیک موز'],d:['Pancakes from just a banana and two eggs.','پنکیک فقط با یک موز و دو تخم‌مرغ'],
 i:'banana:1;eggs:2;oats:2:tbsp:o;cinnamon:::o;honey:::o;oil:1:tsp:s',
 s:[[15,'Mash the banana well and beat in the eggs (and the oats and cinnamon).','موز را خوب له کنید و تخم‌مرغ (و جو دوسر و دارچین) را اضافه کنید و هم بزنید.'],
  [10,'Lightly oil a pan over medium-low heat and pour in small pancakes.','تابه را روی حرارت ملایم کمی چرب کنید و پنکیک‌های کوچک بریزید.'],
  [7,'Cook until the edges set, flip gently and cook 1 minute more.','بپزید تا لبه‌ها ببندد، آرام برگردانید و یک دقیقه دیگر بپزید.'],
  [0,'Serve with a drizzle of honey.','با کمی عسل سرو کنید.']],
 m:''});

R({id:'egg-curry',c:'main',min:35,sv:3,n:[300,14,12,22],app:'stove',x:1,
 t:['Egg curry','کاری تخم‌مرغ'],d:['Boiled eggs in a spiced onion and tomato sauce.','تخم‌مرغ آب‌پز در سس ادویه‌دار پیاز و گوجه'],
 i:'eggs:6;onion:2;tomato:3;garlic:3:clove:o;curry powder:1:tbsp:o;chili:::o;turmeric:1:tsp:s;oil:3:tbsp:s;salt::taste:s',
 s:[[35,'Hard-boil the eggs for 10 minutes, cool, peel and make a few shallow cuts in each.','تخم‌مرغ‌ها را ۱۰ دقیقه بجوشانید، خنک کنید، پوست بگیرید و روی هر کدام چند برش سطحی بزنید.'],
  [30,'Fry the chopped onion in the oil until golden, then add the garlic, turmeric and curry powder for a minute.','پیاز خردشده را در روغن طلایی کنید، بعد سیر، زردچوبه و پودر کاری را اضافه کنید و یک دقیقه تفت دهید.'],
  [22,'Add the chopped tomatoes, salt and ½ cup water and simmer until thick, about 10 minutes.','گوجه‌ی خردشده، نمک و نصف پیمانه آب را اضافه کنید و حدود ۱۰ دقیقه بپزید تا غلیظ شود.'],
  [10,'Add the eggs and simmer 8 minutes, spooning the sauce over them.','تخم‌مرغ‌ها را اضافه کنید و ۸ دقیقه بپزید و سس را رویشان بریزید.'],
  [0,'Serve with rice or bread.','با برنج یا نان سرو کنید.']],
 m:'chelo'});

R({id:'baked-potatoes',c:'side',min:60,sv:4,n:[260,6,42,8],app:'oven|microwave|air fryer',x:1,
 t:['Baked potatoes','سیب‌زمینی تنوری'],d:['Fluffy baked potatoes with butter, cheese or yogurt.','سیب‌زمینی پخته‌ی پفکی با کره، پنیر یا ماست'],
 i:'potato:4;butter:2:tbsp:o;cheese:::o;yogurt:::o;chives:::o;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[60,'Heat the oven to 200 °C. Scrub the potatoes, prick them with a fork and rub with oil and salt.','فر را روی ۲۰۰ درجه روشن کنید. سیب‌زمینی‌ها را خوب بشویید، با چنگال سوراخ کنید و روغن و نمک بمالید.'],
  [55,'Bake about 50 minutes until soft inside (or microwave 8–10 minutes, turning once).','حدود ۵۰ دقیقه بپزید تا داخلش نرم شود (یا در مایکروویو ۸ تا ۱۰ دقیقه و یک بار برگردانید).'],
  [0,'Split open, fluff with a fork and top with butter, cheese, yogurt or chives.','از وسط باز کنید، با چنگال پفکی کنید و کره، پنیر، ماست یا تره رویش بریزید.']],
 m:''});

R({id:'mashed-potatoes',c:'side',min:30,sv:4,n:[240,5,38,8],app:'stove',x:1,
 t:['Mashed potatoes','پوره‌ی سیب‌زمینی'],d:['Smooth, buttery mash in 30 minutes.','پوره‌ی نرم و کره‌ای در ۳۰ دقیقه'],
 i:'potato:5;butter:3:tbsp;milk:0.5:cup;salt::taste:s;black pepper::taste:s',
 s:[[30,'Peel and quarter the potatoes and boil in salted water for about 20 minutes, until very soft.','سیب‌زمینی‌ها را پوست بگیرید، چهار تکه کنید و در آب نمک حدود ۲۰ دقیقه بپزید تا کاملاً نرم شود.'],
  [8,'Drain well and let them steam dry for a minute. Warm the milk with the butter.','خوب آبکش کنید و یک دقیقه بگذارید بخارشان برود. شیر را با کره گرم کنید.'],
  [4,'Mash the potatoes, then beat in the warm milk and butter and season.','سیب‌زمینی‌ها را له کنید، شیر و کره‌ی گرم را اضافه کنید، هم بزنید و نمک و فلفل بزنید.'],
  [0,'Serve hot.','داغ سرو کنید.']],
 m:''});

R({id:'fried-potatoes',c:'side',min:30,sv:3,n:[290,4,38,14],app:'stove|air fryer|oven',
 t:['Fried potatoes','سیب‌زمینی سرخ‌کرده'],d:['Golden, crisp potato wedges or fries.','سیب‌زمینی سرخ‌کرده‌ی طلایی و ترد'],
 i:'potato:4;ketchup:::o;oil:0.5:cup:s;salt::taste:s',
 s:[[30,'Cut the potatoes into sticks or wedges, rinse and dry them well.','سیب‌زمینی‌ها را خلالی یا قاچی کنید، بشویید و کاملاً خشک کنید.'],
  [22,'Fry in hot oil in batches until golden and crisp (or toss with a little oil and air-fry at 200 °C for 18–20 minutes).','دسته‌دسته در روغن داغ سرخ کنید تا طلایی و ترد شود (یا با کمی روغن در هواپز با ۲۰۰ درجه ۱۸ تا ۲۰ دقیقه بپزید).'],
  [0,'Drain on paper, salt right away and serve.','روی دستمال کاغذی بگذارید تا روغنش گرفته شود، فوراً نمک بزنید و سرو کنید.']],
 m:''});

R({id:'grilled-cheese',c:'breakfast',min:10,sv:1,n:[440,18,31,28],app:'stove',x:1,
 t:['Grilled cheese sandwich','ساندویچ پنیر داغ'],d:['Crisp buttery bread with melted cheese.','نان ترد و کره‌ای با پنیر آب‌شده'],
 i:'bread:2;cheese:60:g;butter:1:tbsp:o;tomato:1::o;oil:1:tsp:s',
 s:[[10,'Butter the outside of the bread (or brush with oil) and put the cheese (and tomato) between the slices.','بیرون برش‌های نان را کره (یا روغن) بمالید و پنیر (و گوجه) را بینشان بگذارید.'],
  [7,'Cook in a pan over medium-low heat, about 3 minutes a side, pressing gently, until golden and the cheese melts.','در تابه روی حرارت ملایم هر طرف حدود ۳ دقیقه بپزید و کمی فشار دهید تا طلایی شود و پنیر آب شود.'],
  [0,'Cut in half and serve hot.','از وسط نصف کنید و داغ سرو کنید.']],
 m:''});

R({id:'tomato-soup',c:'soup',min:35,sv:4,n:[130,3,14,7],app:'stove',x:1,
 t:['Tomato soup','سوپ گوجه‌فرنگی'],d:['Simple tomato soup with onion and garlic.','سوپ ساده‌ی گوجه‌فرنگی با پیاز و سیر'],
 i:'tomato:8;onion:1;garlic:2:clove:o;butter:2:tbsp:o;cream:0.25:cup:o;basil:::o;sugar:1:tsp:s;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[35,'Chop the onion, garlic and tomatoes.','پیاز، سیر و گوجه‌ها را خرد کنید.'],
  [30,'Soften the onion and garlic in butter or oil for 5 minutes.','پیاز و سیر را ۵ دقیقه در کره یا روغن تفت دهید تا نرم شود.'],
  [25,'Add the tomatoes, 2 cups water, sugar, salt and pepper and simmer 20 minutes.','گوجه‌ها، ۲ پیمانه آب، شکر، نمک و فلفل را اضافه کنید و ۲۰ دقیقه بپزید.'],
  [4,'Blend until smooth (or mash well) and stir in the cream.','با گوشت‌کوب برقی یا مخلوط‌کن صاف کنید (یا خوب له کنید) و خامه را اضافه کنید.'],
  [0,'Serve hot with bread.','داغ با نان سرو کنید.']],
 m:'grilled-cheese'});

R({id:'garlic-bread',c:'side',min:15,sv:4,n:[210,5,26,10],app:'oven|air fryer|stove',x:1,
 t:['Garlic bread','نان سیر'],d:['Toasty bread with garlic butter.','نان برشته با کره‌ی سیر'],
 i:'bread:6;butter:4:tbsp;garlic:3:clove;parsley:::o;cheese:::o;salt::pinch:s',
 s:[[15,'Heat the oven to 200 °C. Mix soft butter with crushed garlic, a pinch of salt and chopped parsley.','فر را روی ۲۰۰ درجه روشن کنید. کره‌ی نرم را با سیر له‌شده، کمی نمک و جعفری خردشده مخلوط کنید.'],
  [10,'Spread it on the bread (and add cheese if you like).','روی نان‌ها بمالید (و اگر دوست دارید پنیر هم بریزید).'],
  [8,'Bake 7–8 minutes until golden, or toast in a pan, butter side down.','۷ تا ۸ دقیقه بپزید تا طلایی شود، یا در تابه با سمت کره‌ای رو به پایین برشته کنید.'],
  [0,'Serve warm.','گرم سرو کنید.']],
 m:'tomato-soup'});

R({id:'aglio-olio',c:'main',min:20,sv:2,n:[560,13,72,24],app:'stove',x:1,
 t:['Spaghetti aglio e olio','اسپاگتی با سیر و روغن'],d:['Pasta tossed with garlic, oil and chili — 20 minutes.','پاستا با سیر، روغن و فلفل؛ بیست‌دقیقه‌ای'],
 i:'pasta:200:g;garlic:4:clove;chili flakes:0.5:tsp:o;parsley:::o;cheese:::o;oil:4:tbsp:s;salt::taste:s',
 s:[[20,'Boil the pasta in well-salted water until just tender. Keep a cup of the cooking water.','پاستا را در آب نمک بپزید تا تازه نرم شود. یک لیوان از آب پاستا را نگه دارید.'],
  [8,'Meanwhile, warm the oil with the thinly sliced garlic over low heat until pale golden, then add the chili flakes.','در این فاصله روغن را با سیر نازک‌برش‌خورده روی حرارت ملایم گرم کنید تا سیر کمی طلایی شود و پول‌بیبر را اضافه کنید.'],
  [3,'Toss in the drained pasta with a splash of the cooking water until glossy.','پاستای آبکش‌شده و کمی از آب پاستا را اضافه کنید و هم بزنید تا براق شود.'],
  [0,'Finish with parsley (and cheese) and serve.','جعفری (و پنیر) رویش بریزید و سرو کنید.']],
 m:''});

R({id:'shir-moz',c:'drink',min:5,sv:2,n:[230,9,40,5],app:'blender',
 t:['Banana milkshake (shir moz)','شیر موز'],d:['Banana blended with cold milk — breakfast in a glass.','موز و شیر سرد؛ صبحانه در یک لیوان'],
 i:'banana:2;milk:2:cup;honey|dates:::o;walnuts:::o;cinnamon:::o',
 s:[[5,'Put the bananas, cold milk and a little honey or a few dates in the blender.','موز، شیر سرد و کمی عسل یا چند خرما را در مخلوط‌کن بریزید.'],
  [2,'Blend until smooth and frothy.','مخلوط کنید تا یکدست و کف‌دار شود.'],
  [0,'Pour into glasses and dust with cinnamon.','در لیوان بریزید و کمی دارچین بپاشید.']],
 m:''});

R({id:'tuna-sandwich',c:'main',min:10,sv:2,n:[380,24,31,17],app:'',x:1,
 t:['Tuna sandwich','ساندویچ تن ماهی'],d:['Tuna, mayo and pickles in bread — no cooking.','تن ماهی، مایونز و خیارشور لای نان؛ بدون پخت'],
 i:'tuna:1;bread:4;mayonnaise:2:tbsp:o;onion:0.5::o;pickles:2::o;tomato:1::o;lemon:::o;black pepper::taste:s',
 s:[[10,'Drain the tuna and mash it with the mayonnaise, finely chopped onion and pickles, a squeeze of lemon and pepper.','روغن تن ماهی را بگیرید و آن را با مایونز، پیاز و خیارشور ریزخردشده، کمی آب‌لیمو و فلفل مخلوط کنید.'],
  [0,'Fill the bread with the tuna and sliced tomato.','مخلوط تن ماهی و گوجه‌ی حلقه‌شده را لای نان بگذارید.']],
 m:''});

/* ---------- international dishes (cu = cuisine; k = how to tell it’s done: almost, perfect, overcooked) ---------- */
R({id:'pizza-margherita',c:'main',min:120,sv:4,n:[760,27,100,27],app:'oven',cu:'it',col:'#D9533A',
 t:['Pizza margherita','پیتزا مارگاریتا'],d:['Thin, crisp pizza with tomato sauce, melted mozzarella and fresh basil.','پیتزای نازک و ترد با سس گوجه، موتزارلای آب‌شده و ریحان تازه'],
 i:'flour:500:g;yeast:7:g;tomato:4;garlic:1:clove:o;cheese:250:g;basil:1:bunch;oregano:1:tsp:o;oil:4:tbsp:s;sugar:1:tsp:s;salt:1:tsp:s',
 s:[[120,'Mix the flour, yeast, sugar, salt, 2 tbsp oil and 320 ml warm water, then knead 10 minutes until smooth and springy. Cover and leave somewhere warm to double, about 1 hour.','آرد، خمیرمایه، شکر، نمک، ۲ قاشق روغن و ۳۲۰ میلی‌لیتر آب ولرم را مخلوط کنید و ۱۰ دقیقه ورز دهید تا خمیر صاف و کشسان شود. رویش را بپوشانید و حدود ۱ ساعت جای گرم بگذارید تا دو برابر شود.'],
  [70,'Grate the tomatoes, discarding the skins, and simmer with the garlic, oregano, a pinch of salt and 1 tbsp oil until thick, about 10 minutes. Leave to cool.','گوجه‌ها را رنده کنید و پوستشان را دور بریزید، بعد با سیر، پونه‌کوهی، کمی نمک و ۱ قاشق روغن حدود ۱۰ دقیقه بپزید تا غلیظ شود. بگذارید خنک شود.'],
  [50,'Heat the oven as hot as it goes (at least 250°C) with a baking tray inside.','فر را با یک سینی داخلش روی بالاترین دما (دست‌کم ۲۵۰ درجه) روشن کنید.'],
  [25,'Halve the dough and stretch each piece into a thin 30 cm round on floured baking paper. Spread with the sauce and tear over the mozzarella.','خمیر را دو قسمت کنید و هر تکه را روی کاغذ روغنی آردپاشی‌شده به شکل دایره‌ی نازک ۳۰ سانتی باز کنید. سس را رویش بمالید و موتزارلا را تکه‌تکه رویش بریزید.'],
  [18,'Slide one pizza, on its paper, onto the hot tray and bake 8–9 minutes, then bake the second.','یکی از پیتزاها را با کاغذش روی سینی داغ بکشید و ۸ تا ۹ دقیقه بپزید، بعد پیتزای دوم را بپزید.'],
  [0,'Scatter with basil, drizzle with the last of the oil, slice and serve hot.','ریحان رویش بریزید، باقی روغن را رویش بچکانید، برش بزنید و داغ سرو کنید.']],
 k:[['The base is pale underneath and the cheese has melted but not bubbled.','The rim is puffed and spotted brown, the base sounds crisp when tapped, and the cheese bubbles in places.','The rim is dark and hard and the cheese has turned brown and oily; next time bake on a lower shelf.'],
    ['زیر نان هنوز رنگ‌پریده است و پنیر آب شده ولی حباب نزده.','لبه‌ها پف کرده و خال‌خال قهوه‌ای شده، زیر نان با ضربه‌ی انگشت ترد صدا می‌دهد و پنیر جاهایی قل می‌زند.','لبه‌ها تیره و سفت شده و پنیر قهوه‌ای و روغنی شده؛ دفعه‌ی بعد پیتزا را در طبقه‌ی پایین‌تر بپزید.']],
 m:'caprese-salad'});

R({id:'spaghetti-bolognese',c:'main',min:90,sv:4,n:[790,42,84,31],app:'stove',cu:'it',col:'#9E3B22',
 t:['Spaghetti bolognese','اسپاگتی بولونز'],d:['Spaghetti with a slow-simmered beef, tomato and vegetable sauce.','اسپاگتی با سس گوشت، گوجه و سبزیجات که آرام و طولانی پخته شده'],
 i:'pasta:400:g;ground meat:500:g;onion:1;carrot:1;celery:1;garlic:2:clove;tomato:5;tomato paste:2:tbsp;milk:100:ml:o;oregano:1:tsp:o;cheese:50:g:o;oil:2:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[90,'Finely chop the onion, carrot and celery, chop the tomatoes and crush the garlic.','پیاز، هویج و کرفس را ریز خرد کنید، گوجه‌ها را خرد و سیر را له کنید.'],
  [80,'Soften the onion, carrot, celery and garlic in the oil over medium heat for 8 minutes, then add the beef and cook, breaking it up, until browned all over — about 8 minutes.','پیاز، هویج، کرفس و سیر را ۸ دقیقه روی حرارت متوسط در روغن تفت دهید تا نرم شوند، بعد گوشت را اضافه کنید و با قاشق از هم باز کنید تا همه‌جایش قهوه‌ای شود؛ حدود ۸ دقیقه.'],
  [62,'Stir in the tomato paste for a minute, then add the tomatoes, milk, oregano, salt, pepper and 250 ml water. Partly cover and simmer gently for 45 minutes, stirring now and then.','رب را اضافه کنید و یک دقیقه تفت دهید، بعد گوجه، شیر، پونه‌کوهی، نمک، فلفل و ۲۵۰ میلی‌لیتر آب را بریزید. در قابلمه را نیمه‌باز بگذارید و ۴۵ دقیقه روی حرارت ملایم بپزید و گاهی هم بزنید.'],
  [22,'Put a big pot of well-salted water on to boil.','قابلمه‌ی بزرگی آب‌نمک روی گاز بگذارید تا بجوشد.'],
  [12,'Boil the spaghetti until al dente, about 10 minutes, and save a cup of the cooking water.','اسپاگتی را حدود ۱۰ دقیقه بجوشانید تا کمی سفت بماند و یک پیمانه از آبش را نگه دارید.'],
  [0,'Drain, toss the spaghetti with some of the sauce and a splash of the water, and serve topped with the rest of the sauce and grated parmesan.','آب اسپاگتی را بگیرید، آن را با مقداری از سس و کمی از آب پاستا مخلوط کنید و با بقیه‌ی سس و پنیر پارمزان رنده‌شده رویش سرو کنید.']],
 k:[['The sauce is thin and watery and tastes sharp of raw tomato.','Thick, glossy and deep red-brown; a spoon drawn through the pan leaves a trail that slowly closes.','The sauce is thick and catching on the bottom; stir in a splash of hot water and lower the heat.'],
    ['سس رقیق و آبکی است و طعم گوجه‌ی خام و ترش می‌دهد.','سس غلیظ، براق و قرمز متمایل به قهوه‌ای است؛ اگر قاشق را از وسط قابلمه بکشید، جایش آرام بسته می‌شود.','سس خیلی غلیظ شده و ته می‌گیرد؛ کمی آب داغ اضافه کنید و حرارت را کم کنید.']],
 m:'garlic-bread'});

R({id:'beef-lasagna',c:'main',min:135,sv:6,n:[745,38,51,42],app:'stove,oven',cu:'it',col:'#C1552E',
 t:['Beef lasagna','لازانیا گوشت'],d:['Layers of pasta, beef ragù and creamy white sauce, baked until golden.','لایه‌های لازانیا، سس گوشت و سس سفید خامه‌ای که در فر طلایی می‌شود'],
 i:'pasta:250:g;ground meat:600:g;onion:1;carrot:1;garlic:3:clove;tomato:5;tomato paste:2:tbsp;butter:60:g;flour:60:g;milk:800:ml;cheese:200:g;oregano:1:tsp:o;oil:2:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[135,'Finely chop the onion, carrot and garlic and soften them in the oil for 8 minutes, then add the beef and brown it well.','پیاز، هویج و سیر را ریز خرد کنید و ۸ دقیقه در روغن تفت دهید تا نرم شوند، بعد گوشت را اضافه کنید و خوب سرخ کنید.'],
  [115,'Add the tomato paste, chopped tomatoes, oregano, salt, pepper and 200 ml water and simmer, partly covered, for 40 minutes until thick.','رب، گوجه‌ی خردشده، پونه‌کوهی، نمک، فلفل و ۲۰۰ میلی‌لیتر آب را اضافه کنید و با در نیمه‌باز ۴۰ دقیقه بپزید تا غلیظ شود.'],
  [80,'Make the white sauce: melt the butter, stir in the flour for a minute, then whisk in the milk a little at a time and cook, stirring, until thick and smooth. Season with salt. Heat the oven to 190°C.','سس سفید را درست کنید: کره را آب کنید، آرد را اضافه کنید و یک دقیقه هم بزنید، بعد شیر را کم‌کم اضافه کنید و مدام هم بزنید تا غلیظ و یکدست شود. نمک بزنید. فر را روی ۱۹۰ درجه روشن کنید.'],
  [65,'In a deep baking dish, layer meat sauce, uncooked lasagna sheets and white sauce three or four times, finishing with white sauce and the grated cheese.','در یک ظرف پیرکس گود، سس گوشت، ورقه‌های خام لازانیا و سس سفید را سه چهار لایه روی هم بچینید و لایه‌ی آخر را سس سفید و پنیر رنده‌شده بگذارید.'],
  [55,'Bake for 40 minutes until bubbling and golden, then let it rest out of the oven for 15 minutes so the layers set.','۴۰ دقیقه بپزید تا روی آن طلایی شود و قل بزند، بعد ۱۵ دقیقه بیرون از فر بگذارید تا لایه‌ها جا بیفتند.'],
  [0,'Cut into squares and serve.','مربعی برش بزنید و سرو کنید.']],
 k:[['The edges bubble but the centre is still pale and a knife meets firm pasta.','Golden and blistered on top, bubbling at the edges, and a knife slides through the centre with no resistance.','The top is dark brown and the edges have dried out; spoon a little warm sauce over each piece.'],
    ['کناره‌ها قل می‌زند ولی وسطش هنوز کم‌رنگ است و چاقو به لازانیای سفت می‌خورد.','رویش طلایی و حباب‌حباب است، کناره‌ها قل می‌زند و چاقو بدون مقاومت از وسطش رد می‌شود.','رویش قهوه‌ای تیره شده و کناره‌ها خشک شده؛ موقع سرو کمی سس گرم روی هر تکه بریزید.']],
 m:'caprese-salad,garlic-bread'});

R({id:'fettuccine-alfredo',c:'main',min:20,sv:4,n:[760,23,74,41],app:'stove',cu:'it',col:'#EBD9A8',
 t:['Fettuccine alfredo','فتوچینی آلفردو'],d:['Ribbon pasta in a silky butter, cream and parmesan sauce.','پاستای روبانی با سس لطیف کره، خامه و پنیر پارمزان'],
 i:'pasta:400:g;butter:50:g;cream:250:ml;cheese:100:g;garlic:1:clove:o;parsley:::o;salt::taste:s;black pepper::taste:s',
 s:[[20,'Bring a big pot of salted water to the boil and finely grate the parmesan.','قابلمه‌ی بزرگ آب‌نمک را بجوشانید و پنیر پارمزان را ریز رنده کنید.'],
  [12,'Cook the fettuccine until just al dente, about 9 minutes, and save a cup of the cooking water.','فتوچینی را حدود ۹ دقیقه بجوشانید تا کمی سفت بماند و یک پیمانه از آبش را نگه دارید.'],
  [8,'Meanwhile melt the butter in a wide pan, add the garlic for 30 seconds, then the cream, and simmer gently for 3 minutes.','در همین فاصله کره را در تابه‌ی پهن آب کنید، سیر را ۳۰ ثانیه تفت دهید، بعد خامه را اضافه کنید و ۳ دقیقه آرام بجوشانید.'],
  [3,'Off the heat, toss the drained pasta in the cream with the parmesan and a splash of pasta water until glossy and coating every strand.','زیر گاز را خاموش کنید و پاستای آبکش‌شده را با پنیر و کمی آب پاستا در خامه هم بزنید تا سس براق شود و به همه‌ی رشته‌ها بچسبد.'],
  [0,'Season with black pepper, scatter with parsley and serve at once.','فلفل سیاه بزنید، جعفری رویش بریزید و فوراً سرو کنید.']],
 k:[['The sauce is thin and pools at the bottom of the pan.','Silky and glossy, it clings to every ribbon and leaves a creamy coat on the spoon.','The sauce has gone thick, clumpy or oily; loosen it with a splash of hot pasta water, tossing fast.'],
    ['سس رقیق است و ته تابه جمع می‌شود.','سس لطیف و براق است، به همه‌ی رشته‌ها می‌چسبد و روی قاشق لایه‌ی خامه‌ای می‌گذارد.','سس خیلی غلیظ، گلوله‌گلوله یا روغنی شده؛ کمی آب داغ پاستا اضافه کنید و سریع هم بزنید.']],
 m:'caprese-salad'});

R({id:'pesto-pasta',c:'main',min:20,sv:4,n:[660,19,74,32],app:'stove,blender|food processor',cu:'it',col:'#5E8C31',
 t:['Pesto pasta','پاستا پستو'],d:['Pasta tossed in a bright basil, garlic, nut and parmesan pesto.','پاستا با سس پستوی ریحان، سیر، مغز و پنیر پارمزان'],
 i:'pasta:400:g;basil:2:bunch;garlic:1:clove;walnuts|almonds:40:g;cheese:60:g;lemon:0.5::o;oil:80:ml:s;salt::taste:s;black pepper::taste:s',
 s:[[20,'Put a big pot of salted water on to boil. Lightly toast the nuts in a dry pan for 3 minutes.','قابلمه‌ی بزرگ آب‌نمک را روی گاز بگذارید تا بجوشد. مغزها را ۳ دقیقه در تابه‌ی خشک کمی تفت دهید.'],
  [15,'Blend the basil leaves, garlic, nuts, grated parmesan, a squeeze of lemon and a pinch of salt, pouring in the oil, until you have a thick, bright green paste.','برگ‌های ریحان، سیر، مغزها، پنیر پارمزان رنده‌شده، کمی آبلیمو و کمی نمک را در مخلوط‌کن بریزید و در حین کار روغن را کم‌کم اضافه کنید تا سسی غلیظ و سبز روشن به دست آید.'],
  [12,'Cook the pasta until al dente, about 10 minutes, and save a cup of the cooking water.','پاستا را حدود ۱۰ دقیقه بجوشانید تا کمی سفت بماند و یک پیمانه از آبش را نگه دارید.'],
  [2,'Drain and, off the heat, toss the pasta with the pesto and a few spoons of the pasta water until creamy.','آب پاستا را بگیرید و بیرون از گاز آن را با پستو و چند قاشق از آب پاستا مخلوط کنید تا سس کرمی شود.'],
  [0,'Serve straight away with extra parmesan and black pepper.','فوراً با کمی پنیر پارمزان اضافه و فلفل سیاه سرو کنید.']],
 k:[['The pasta bends but has a white, chalky dot in the middle.','Al dente — tender with a slight bite, and the pesto clings in a creamy, bright green coat.','The pasta is soft and swollen, or the pesto has turned dark and dull from the heat; toss in a little fresh basil and keep it off the heat.'],
    ['پاستا خم می‌شود ولی وسطش یک نقطه‌ی سفید و گچی دارد.','پاستا نرم است ولی کمی زیر دندان مقاومت می‌کند و پستو مثل لایه‌ای کرمی و سبز روشن به آن چسبیده.','پاستا وا رفته و باد کرده یا پستو از حرارت تیره و بی‌رنگ شده؛ کمی ریحان تازه اضافه کنید و دیگر روی گاز نگذارید.']],
 m:'bruschetta'});

R({id:'mushroom-risotto',c:'rice',min:45,sv:4,n:[500,14,65,20],app:'stove',cu:'it',col:'#C9B48A',
 t:['Mushroom risotto','ریزوتو قارچ'],d:['Creamy risotto with golden mushrooms, butter and parmesan.','ریزوتوی کرمی با قارچ طلایی، کره و پنیر پارمزان'],
 i:'rice:300:g;mushrooms:400:g;onion:1;garlic:2:clove;butter:40:g;cheese:60:g;parsley:::o;lemon:0.5::o;oil:2:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[45,'Warm 1.2 litres of stock or salted water in a pan and keep it hot. Slice the mushrooms and finely chop the onion and garlic.','۱٫۲ لیتر آب‌مرغ یا آب‌نمک را در قابلمه‌ای گرم کنید و داغ نگه دارید. قارچ‌ها را ورقه کنید و پیاز و سیر را ریز خرد کنید.'],
  [38,'Fry the mushrooms in half the oil and a knob of the butter over high heat until golden, about 6 minutes; season and set aside.','قارچ‌ها را با نصف روغن و کمی از کره روی حرارت زیاد حدود ۶ دقیقه تفت دهید تا طلایی شوند؛ نمک و فلفل بزنید و کنار بگذارید.'],
  [30,'In the same pan soften the onion and garlic in the rest of the oil for 4 minutes, then add the short-grain risotto rice and stir for 2 minutes until the grains turn glassy at the edges.','در همان تابه پیاز و سیر را با بقیه‌ی روغن ۴ دقیقه تفت دهید تا نرم شوند، بعد برنج دانه‌کوتاه ریزوتو را اضافه کنید و ۲ دقیقه هم بزنید تا لبه‌ی دانه‌ها شفاف شود.'],
  [24,'Add the hot stock a ladle at a time, stirring often and letting each ladle almost disappear before the next, for about 20 minutes. Stir the mushrooms back in for the last 5 minutes.','آب داغ را ملاقه‌ملاقه اضافه کنید و مرتب هم بزنید و هر بار صبر کنید تا تقریباً جذب شود؛ حدود ۲۰ دقیقه. ۵ دقیقه‌ی آخر قارچ‌ها را دوباره اضافه کنید.'],
  [3,'Off the heat, beat in the remaining butter, the parmesan and a squeeze of lemon; cover and rest 2 minutes.','زیر گاز را خاموش کنید، بقیه‌ی کره، پنیر پارمزان و کمی آبلیمو را اضافه کنید و محکم هم بزنید؛ درش را بگذارید و ۲ دقیقه صبر کنید.'],
  [0,'Serve in warm bowls with parsley and black pepper.','در کاسه‌های گرم با جعفری و فلفل سیاه سرو کنید.']],
 k:[['The rice is chalky in the centre and the liquid sits separately around it.','The grains are tender with a slight bite and the risotto is creamy and loose — it slowly spreads when spooned onto a plate.','Mushy grains in a stiff, gluey mass; beat in a ladle of hot water and a little butter.'],
    ['وسط دانه‌های برنج هنوز گچی است و مایع جدا دور برنج مانده.','دانه‌ها نرم‌اند ولی کمی زیر دندان مقاومت می‌کنند و ریزوتو کرمی و روان است؛ وقتی در بشقاب می‌کشید آرام پهن می‌شود.','دانه‌ها له شده‌اند و ریزوتو سفت و چسبناک شده؛ یک ملاقه آب داغ و کمی کره اضافه کنید و هم بزنید.']],
 m:'caprese-salad'});

R({id:'bruschetta',c:'side',min:15,sv:4,n:[245,5,31,11],app:'oven|toaster|grill|stove',cu:'it',col:'#C8452F',
 t:['Bruschetta','بروسکتا'],d:['Toasted bread rubbed with garlic and piled with fresh tomato and basil.','نان برشته‌ی سیرمالیده با گوجه‌فرنگی تازه و ریحان'],
 i:'bread:8;tomato:4;garlic:1:clove;basil:1:bunch;vinegar:1:tsp:o;oil:3:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[15,'Dice the tomatoes, tear the basil and mix both with 2 tbsp oil, a few drops of vinegar, salt and pepper. Leave to sit.','گوجه‌ها را مکعبی خرد کنید، ریحان را با دست ریز کنید و هر دو را با ۲ قاشق روغن، چند قطره سرکه، نمک و فلفل مخلوط کنید. بگذارید بماند.'],
  [7,'Toast the bread slices until golden and crisp, 2–3 minutes a side.','برش‌های نان را هر طرف ۲ تا ۳ دقیقه برشته کنید تا طلایی و ترد شوند.'],
  [2,'Rub each warm toast with the cut side of the halved garlic clove and drizzle with the rest of the oil.','روی هر نان داغ، سمت بریده‌ی حبه‌ی سیر را بمالید و بقیه‌ی روغن را رویش بچکانید.'],
  [0,'Spoon the tomatoes on top just before serving so the bread stays crisp.','درست پیش از سرو، گوجه‌ها را روی نان بریزید تا نان ترد بماند.']],
 k:[['The bread is warm but still pale and bends when you lift it.','Golden, crisp at the edges and firm enough that the garlic grates against it.','Dark brown and bitter at the edges; scrape off the burnt bits with a knife.'],
    ['نان گرم شده ولی هنوز کم‌رنگ است و وقتی بلندش می‌کنید خم می‌شود.','نان طلایی است، لبه‌هایش ترد است و آن‌قدر سفت شده که سیر روی آن رنده می‌شود.','لبه‌ها قهوه‌ای تیره و تلخ شده؛ قسمت‌های سوخته را با چاقو بتراشید.']],
 m:'minestrone'});

R({id:'caprese-salad',c:'salad',min:10,sv:4,n:[285,15,5,23],app:'',cu:'it',col:'#E25A4A',
 t:['Caprese salad','سالاد کاپرزه'],d:['Ripe tomatoes, fresh mozzarella and basil with a drizzle of olive oil.','گوجه‌فرنگی رسیده، موتزارلای تازه و ریحان با کمی روغن زیتون'],
 i:'tomato:4;cheese:250:g;basil:1:bunch;vinegar:1:tsp:o;oil:3:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[10,'Slice the tomatoes and mozzarella into rounds about 1 cm thick.','گوجه‌ها و موتزارلا را حلقه‌هایی به ضخامت حدود ۱ سانتی‌متر ببرید.'],
  [5,'Arrange them on a platter, overlapping and alternating, with a basil leaf tucked between each.','آن‌ها را یکی در میان و کمی روی هم در دیس بچینید و بین هر کدام یک برگ ریحان بگذارید.'],
  [0,'Season with salt and pepper, drizzle with the oil and a few drops of vinegar, and serve at room temperature.','نمک و فلفل بزنید، روغن و چند قطره سرکه رویش بچکانید و در دمای اتاق سرو کنید.']],
 k:[['The tomatoes are firm, pale and fridge-cold, with little smell.','Deep red tomatoes that give slightly when pressed and smell sweet, with soft, milky mozzarella at room temperature.','The tomatoes are mushy and the plate is watery from sitting in salt too long; drain the juices and season again just before serving.'],
    ['گوجه‌ها سفت و کم‌رنگ‌اند، از یخچال سردند و بوی زیادی ندارند.','گوجه‌ها قرمز پررنگ‌اند، با فشار انگشت کمی نرم می‌شوند و بوی شیرین می‌دهند و موتزارلا نرم و شیری و هم‌دمای اتاق است.','گوجه‌ها له شده‌اند و بشقاب از ماندن زیاد در نمک آب انداخته؛ آبش را خالی کنید و درست پیش از سرو دوباره نمک بزنید.']],
 m:'bruschetta'});

R({id:'minestrone',c:'soup',min:50,sv:6,n:[280,11,37,9],app:'stove',cu:'it',col:'#C0663A',
 t:['Minestrone','سوپ مینسترونه'],d:['Hearty Italian vegetable soup with beans and small pasta.','سوپ سبزیجات ایتالیایی با لوبیا و ماکارونی ریز'],
 i:'onion:1;carrot:2;celery:2;zucchini:1;potato:1;garlic:2:clove;tomato:3;tomato paste:1:tbsp;white beans|kidney beans:400:g;pasta:100:g;green beans:100:g:o;spinach|cabbage:100:g:o;basil|parsley:::o;cheese:40:g:o;oil:3:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[50,'Dice the onion, carrots, celery, zucchini, potato and tomatoes and crush the garlic.','پیاز، هویج، کرفس، کدو، سیب‌زمینی و گوجه را مکعبی خرد کنید و سیر را له کنید.'],
  [40,'Soften the onion, carrot and celery in the oil over medium heat for 8 minutes, then add the garlic and tomato paste for 1 minute.','پیاز، هویج و کرفس را ۸ دقیقه روی حرارت متوسط در روغن تفت دهید تا نرم شوند، بعد سیر و رب را اضافه کنید و ۱ دقیقه تفت دهید.'],
  [31,'Add the potato, zucchini, green beans, tomatoes, salt and 1.5 litres of water, bring to the boil and simmer 15 minutes.','سیب‌زمینی، کدو، لوبیا سبز، گوجه، نمک و ۱٫۵ لیتر آب را اضافه کنید، بگذارید جوش بیاید و ۱۵ دقیقه بپزد.'],
  [15,'Stir in the small pasta and the cooked or canned beans and simmer until the pasta is tender, about 10 minutes. Add the shredded greens for the last 3 minutes.','ماکارونی ریز و لوبیای پخته یا کنسروی را اضافه کنید و حدود ۱۰ دقیقه بپزید تا ماکارونی نرم شود. ۳ دقیقه‌ی آخر سبزی برگی خردشده را اضافه کنید.'],
  [0,'Check the seasoning and serve with torn basil, a drizzle of oil and grated parmesan.','نمک و فلفل را تنظیم کنید و با ریحان، کمی روغن و پنیر پارمزان رنده‌شده سرو کنید.']],
 k:[['The potato still resists a fork and the pasta has a hard white core.','The potato cubes crush easily against the side of the pot, the pasta is tender and the broth is thick and tomatoey.','The pasta is bloated and has soaked up the broth, and the vegetables have gone to mush; thin it with a little boiling water.'],
    ['سیب‌زمینی هنوز جلوی چنگال مقاومت می‌کند و وسط ماکارونی سفید و سفت است.','تکه‌های سیب‌زمینی با فشار قاشق به دیواره‌ی قابلمه راحت له می‌شوند، ماکارونی نرم است و آب سوپ غلیظ و گوجه‌ای است.','ماکارونی باد کرده و آب سوپ را کشیده و سبزیجات له شده‌اند؛ کمی آب جوش اضافه کنید تا رقیق شود.']],
 m:'bruschetta,garlic-bread'});

R({id:'tiramisu',c:'dessert',min:270,sv:8,n:[400,4,31,28],app:'mixer',cu:'it',col:'#8B5E3C',
 t:['Tiramisu','تیرامیسو'],d:['Coffee-soaked ladyfingers layered with whipped cream and mascarpone, dusted with cocoa.','بیسکویت لیدی‌فینگر خیس‌خورده در قهوه با لایه‌های خامه و ماسکارپونه و پودر کاکائو'],
 i:'cream:300:ml;cheese:250:g;chocolate:2:tbsp;vanilla:1:tsp:o;sugar:80:g:s',
 s:[[270,'Brew 300 ml strong coffee, stir in 1 tbsp of the sugar and leave it to cool in a wide bowl.','۳۰۰ میلی‌لیتر قهوه‌ی غلیظ دم کنید، ۱ قاشق از شکر را در آن حل کنید و در یک کاسه‌ی پهن بگذارید خنک شود.'],
  [260,'Whip the cold cream with the rest of the sugar and the vanilla to soft peaks, then fold in the mascarpone until smooth and thick.','خامه‌ی سرد را با بقیه‌ی شکر و وانیل بزنید تا قله‌های نرم بدهد، بعد پنیر ماسکارپونه را آرام در آن هم بزنید تا یکدست و غلیظ شود.'],
  [250,'Dip about 200 g ladyfingers one at a time into the coffee, a second each side, and lay them in a dish. Spread over half the cream, then repeat with another layer of dipped biscuits and the rest of the cream.','حدود ۲۰۰ گرم بیسکویت لیدی‌فینگر را یکی‌یکی هر طرف یک ثانیه در قهوه بزنید و در ظرف بچینید. نصف خامه را رویش پخش کنید، بعد یک لایه‌ی دیگر بیسکویت قهوه‌زده و بقیه‌ی خامه را بچینید.'],
  [240,'Cover and chill for 4 hours, or overnight, to set.','رویش را بپوشانید و ۴ ساعت یا یک شب در یخچال بگذارید تا خودش را بگیرد.'],
  [0,'Dust thickly with cocoa through a sieve, cut into squares and serve cold.','با الک یک لایه‌ی پرپشت پودر کاکائو رویش بپاشید، مربعی برش بزنید و سرد سرو کنید.']],
 k:[['The cream is foamy and runs off the whisk.','Soft, billowy peaks that hold their shape but droop at the tip, and the cream looks smooth and glossy.','The cream looks grainy and is starting to split; gently fold in a few spoons of cold, unwhipped cream.'],
    ['خامه کف کرده ولی از همزن می‌ریزد.','خامه قله‌های نرم و پفکی می‌دهد که شکلشان را نگه می‌دارند ولی نوکشان کمی خم می‌شود، و خامه صاف و براق است.','خامه دانه‌دانه شده و دارد جدا می‌شود؛ چند قاشق خامه‌ی سرد زده‌نشده را آرام در آن هم بزنید.']],
 m:''});

R({id:'crepes',c:'breakfast',min:40,sv:4,n:[350,12,48,13],app:'stove',cu:'fr',col:'#E3B66B',
 t:['Crêpes','کرپ'],d:['Thin, lacy French pancakes with the sweet filling of your choice.','پنکیک‌های نازک و توری فرانسوی با هر مغز شیرینی که دوست دارید'],
 i:'flour:150:g;eggs:3;milk:350:ml;butter:30:g;vanilla:1:tsp:o;jam|honey|chocolate:::o;banana:::o;lemon:::o;sugar:1:tbsp:s;salt::pinch:s',
 s:[[40,'Whisk the flour, sugar and salt, beat in the eggs, then the milk a little at a time until smooth. Stir in half the melted butter and the vanilla and leave the batter to rest for 20 minutes.','آرد، شکر و نمک را مخلوط کنید، تخم‌مرغ‌ها را اضافه کنید و شیر را کم‌کم بریزید و هم بزنید تا مایه یکدست شود. نصف کره‌ی آب‌شده و وانیل را اضافه کنید و بگذارید مایه ۲۰ دقیقه استراحت کند.'],
  [18,'Heat a non-stick pan over medium-high heat and brush it with a little of the remaining butter.','یک تابه‌ی نچسب را روی حرارت نسبتاً زیاد داغ کنید و کمی از بقیه‌ی کره را کفش بمالید.'],
  [16,'Pour in a small ladle of batter and swirl to coat the base thinly. Cook about 1 minute until the edges lift, flip and cook 30 seconds more. Repeat, stacking the crêpes on a plate.','یک ملاقه‌ی کوچک مایه در تابه بریزید و تابه را بچرخانید تا کفش را نازک بپوشاند. حدود ۱ دقیقه بپزید تا لبه‌ها جدا شوند، برگردانید و ۳۰ ثانیه دیگر بپزید. همین کار را تکرار کنید و کرپ‌ها را روی هم در بشقاب بچینید.'],
  [0,'Fill or fold with jam, honey, chocolate or sliced banana and a squeeze of lemon, and serve warm.','با مربا، عسل، شکلات یا موز حلقه‌شده و کمی آبلیمو پر یا تا کنید و گرم سرو کنید.']],
 k:[['The top is still wet and shiny and the edges stick to the pan.','The edges curl and lift away, the underside is golden with lacy brown spots, and it slides when you shake the pan.','Dark, stiff and brittle; lower the heat and use a little less batter for the next one.'],
    ['روی کرپ هنوز خیس و براق است و لبه‌هایش به تابه چسبیده.','لبه‌ها جمع شده و از تابه جدا می‌شوند، زیرش طلایی با خال‌های قهوه‌ای توری است و با تکان دادن تابه سُر می‌خورد.','کرپ تیره، سفت و شکننده شده؛ حرارت را کم کنید و برای بعدی کمی مایه‌ی کمتری بریزید.']],
 m:'chai'});

R({id:'spinach-quiche',c:'main',min:90,sv:6,n:[520,15,30,38],app:'stove,oven',cu:'fr',col:'#D9B25C',
 t:['Spinach and cheese quiche','کیش اسفناج و پنیر'],d:['Buttery pastry filled with a soft egg custard, spinach and cheese.','خمیر کره‌ای با مایه‌ی نرم تخم‌مرغ و خامه، اسفناج و پنیر'],
 i:'flour:200:g;butter:100:g;eggs:4;cream:200:ml;milk:100:ml;spinach:300:g;cheese:120:g;onion:1;garlic:1:clove:o;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[90,'Rub the flour, cold butter and a pinch of salt together into crumbs, add 3–4 tbsp cold water and press into a dough. Roll out, line a 23 cm tart tin and chill 20 minutes.','آرد، کره‌ی سرد و کمی نمک را با سر انگشت به هم بمالید تا شبیه خرده‌نان شود، ۳ تا ۴ قاشق آب سرد اضافه کنید و خمیر را جمع کنید. خمیر را باز کنید، در قالب تارت ۲۳ سانتی بچینید و ۲۰ دقیقه در یخچال بگذارید.'],
  [75,'Meanwhile soften the chopped onion and garlic in the oil, add the spinach and cook until wilted, then squeeze out all the water. Heat the oven to 190°C.','در همین فاصله پیاز و سیر خردشده را در روغن تفت دهید، اسفناج را اضافه کنید و بپزید تا بخوابد، بعد آبش را با فشار دست کاملاً بگیرید. فر را روی ۱۹۰ درجه روشن کنید.'],
  [58,'Prick the pastry base, line it with baking paper filled with dried beans or rice, and bake 15 minutes; remove the paper and bake 5 minutes more.','کف خمیر را با چنگال سوراخ کنید، کاغذ روغنی رویش بگذارید و رویش حبوبات یا برنج خام بریزید و ۱۵ دقیقه بپزید؛ بعد کاغذ را بردارید و ۵ دقیقه دیگر بپزید.'],
  [38,'Whisk the eggs, cream, milk, salt and pepper. Scatter the spinach and grated cheese in the pastry case, pour over the custard and bake at 170°C for about 28 minutes.','تخم‌مرغ‌ها، خامه، شیر، نمک و فلفل را هم بزنید. اسفناج و پنیر رنده‌شده را کف خمیر پخش کنید، مایه را رویش بریزید و در دمای ۱۷۰ درجه حدود ۲۸ دقیقه بپزید.'],
  [0,'Let it settle for 10 minutes, then slice and serve warm or at room temperature.','بگذارید ۱۰ دقیقه بماند تا جا بیفتد، بعد برش بزنید و گرم یا در دمای اتاق سرو کنید.']],
 k:[['The custard wobbles like liquid in the middle and a knife comes out wet.','Set at the edges with a slight wobble in the very centre, puffed and golden, and a knife pushed in near the middle comes out clean.','Puffed high, cracked and weeping liquid, with a dark crust; let it cool fully so it settles, and serve with a salad.'],
    ['مایه وسطش مثل مایع می‌لرزد و چاقو خیس بیرون می‌آید.','کناره‌ها سفت شده و فقط وسطِ وسط کمی می‌لرزد، رویش پف کرده و طلایی است و چاقویی که نزدیک وسط فرو می‌کنید تمیز بیرون می‌آید.','خیلی پف کرده، ترک خورده و آب انداخته و لبه‌ها تیره شده؛ بگذارید کامل خنک شود تا بنشیند و با سالاد سرو کنید.']],
 m:'greek-salad'});

R({id:'ratatouille',c:'main',min:70,sv:4,n:[285,4,23,20],app:'stove',cu:'fr',col:'#B8452E',
 t:['Ratatouille','راتاتویی'],d:['Provençal summer stew of eggplant, zucchini, peppers and tomatoes.','خوراک تابستانی جنوب فرانسه با بادمجان، کدو، فلفل دلمه‌ای و گوجه‌فرنگی'],
 i:'eggplant:1;zucchini:2;bell pepper:2;onion:1;tomato:5;garlic:3:clove;tomato paste:1:tbsp:o;oregano:1:tsp:o;basil|parsley:::o;oil:6:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[70,'Cut the eggplant, zucchini and peppers into 2 cm chunks, slice the onion, chop the tomatoes and crush the garlic.','بادمجان، کدو و فلفل دلمه‌ای را تکه‌های ۲ سانتی ببرید، پیاز را خلالی کنید، گوجه‌ها را خرد و سیر را له کنید.'],
  [58,'Fry the eggplant in 3 tbsp oil over medium-high heat until golden, about 8 minutes, then the zucchini for 5 minutes; lift out and set aside.','بادمجان را با ۳ قاشق روغن روی حرارت نسبتاً زیاد حدود ۸ دقیقه تفت دهید تا طلایی شود، بعد کدو را ۵ دقیقه تفت دهید؛ هر دو را بردارید و کنار بگذارید.'],
  [44,'In the same pot soften the onion and peppers in the rest of the oil for 8 minutes, then add the garlic, tomatoes, tomato paste, oregano and salt.','در همان قابلمه پیاز و فلفل دلمه‌ای را با بقیه‌ی روغن ۸ دقیقه تفت دهید تا نرم شوند، بعد سیر، گوجه، رب، پونه‌کوهی و نمک را اضافه کنید.'],
  [34,'Return the eggplant and zucchini, cover and simmer gently for 30 minutes, stirring carefully now and then, until everything is soft and the sauce is thick.','بادمجان و کدو را برگردانید، درش را بگذارید و ۳۰ دقیقه روی حرارت ملایم بپزید و گاهی آرام هم بزنید تا همه‌چیز نرم و سس غلیظ شود.'],
  [0,'Stir in torn basil and a drizzle of oil and serve warm with bread or rice.','ریحان را با دست ریز کنید و با کمی روغن اضافه کنید و گرم با نان یا برنج سرو کنید.']],
 k:[['The eggplant is still spongy and white inside and the juices are thin.','The vegetables are silky and tender but still hold their shape, the sauce is thick and glossy, and it smells sweet of tomato and garlic.','Everything has collapsed into mush and is catching on the bottom; stir in a splash of water and serve it as a sauce.'],
    ['بادمجان هنوز اسفنجی و داخلش سفید است و آبش رقیق است.','سبزیجات لطیف و نرم‌اند ولی هنوز شکلشان را نگه داشته‌اند، سس غلیظ و براق است و بوی شیرین گوجه و سیر می‌دهد.','همه‌چیز له شده و ته گرفته؛ کمی آب اضافه کنید، هم بزنید و مثل یک سس سرو کنید.']],
 m:'garlic-bread'});

R({id:'french-onion-soup',c:'soup',min:80,sv:4,n:[435,16,41,23],app:'stove,oven',cu:'fr',col:'#9C6B3A',
 t:['French onion soup','سوپ پیاز فرانسوی'],d:['Deeply caramelised onions in a rich broth under a lid of cheesy toast.','پیاز کاراملی‌شده در آب‌گوشت غلیظ با نان برشته و پنیر آب‌شده رویش'],
 i:'onion:1:kg;butter:40:g;flour:1:tbsp;garlic:2:clove;bread:4;cheese:150:g;soy sauce:1:tbsp:o;vinegar:1:tsp:o;oil:1:tbsp:s;sugar:1:tsp:s;salt::taste:s;black pepper::taste:s',
 s:[[80,'Halve and thinly slice the onions.','پیازها را از وسط نصف کنید و نازک خلالی کنید.'],
  [70,'Cook the onions in the butter and oil with a pinch of salt over medium-low heat, stirring often, until deep golden brown and jammy — 40 to 45 minutes. Add the sugar after 15 minutes.','پیازها را با کره، روغن و کمی نمک روی حرارت ملایم تا متوسط بپزید و مرتب هم بزنید تا قهوه‌ای طلایی پررنگ و مربایی شوند؛ ۴۰ تا ۴۵ دقیقه. بعد از ۱۵ دقیقه شکر را اضافه کنید.'],
  [27,'Stir in the garlic and flour for a minute, then pour in 1.2 litres of hot beef stock (or water with the soy sauce), scraping the bottom, and simmer 15 minutes. Add the vinegar, salt and pepper.','سیر و آرد را اضافه کنید و یک دقیقه تفت دهید، بعد ۱٫۲ لیتر آب‌گوشت داغ (یا آب با سس سویا) را بریزید، ته قابلمه را بتراشید و ۱۵ دقیقه بپزید. سرکه، نمک و فلفل را اضافه کنید.'],
  [10,'Turn on the oven grill. Toast the bread slices, ladle the soup into ovenproof bowls, float a toast on each and pile on the grated cheese.','گریل فر را روشن کنید. برش‌های نان را برشته کنید، سوپ را در کاسه‌های نسوز بریزید، روی هر کاسه یک نان بگذارید و پنیر رنده‌شده را رویش بریزید.'],
  [4,'Grill until the cheese is melted, bubbling and browned in spots, 3–4 minutes.','زیر گریل ۳ تا ۴ دقیقه بگذارید تا پنیر آب شود، قل بزند و جاهایی قهوه‌ای شود.'],
  [0,'Serve straight away, and warn everyone that the bowls are hot.','فوراً سرو کنید و بگویید کاسه‌ها داغ است.']],
 k:[['The onions are soft and golden but still pale in places, and smell sharp.','Deep amber-brown, soft and sticky like jam, with a sweet, nutty smell.','Dark, bitter-smelling bits are sticking to the pot; add a splash of water, scrape, and lower the heat.'],
    ['پیازها نرم و طلایی شده‌اند ولی جاهایی هنوز کم‌رنگ‌اند و بوی تند می‌دهند.','پیازها کهربایی و قهوه‌ای پررنگ، نرم و چسبناک مثل مربا شده‌اند و بوی شیرین و فندقی می‌دهند.','تکه‌های تیره با بوی تلخ ته قابلمه چسبیده؛ کمی آب بریزید، ته قابلمه را بتراشید و حرارت را کم کنید.']],
 m:''});

R({id:'paella',c:'rice',min:60,sv:6,n:[540,34,60,17],app:'stove',cu:'es',col:'#E0A33A',
 t:['Chicken and shrimp paella','پائیا مرغ و میگو'],d:['Saffron rice cooked in a wide pan with chicken, shrimp, peppers and peas.','برنج زعفرانی با مرغ، میگو، فلفل دلمه‌ای و نخودفرنگی که در تابه‌ی پهن پخته می‌شود'],
 i:'rice:400:g;chicken:600:g;shrimp:300:g;onion:1;bell pepper:1;tomato:2;garlic:3:clove;peas:100:g;saffron::pinch;paprika:2:tsp;lemon:1;parsley:::o;oil:4:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[60,'Cut the chicken into bite-size pieces, dice the onion and pepper, grate the tomatoes and crush the garlic. Soak the saffron in 2 tbsp hot water.','مرغ را تکه‌های کوچک کنید، پیاز و فلفل دلمه‌ای را خرد کنید، گوجه‌ها را رنده و سیر را له کنید. زعفران را در ۲ قاشق آب داغ دم کنید.'],
  [48,'In a wide pan brown the chicken in the oil with salt for 8 minutes. Push it aside and fry the onion, pepper and garlic for 5 minutes, then stir in the paprika and grated tomato and cook 3 minutes.','در تابه‌ی پهن مرغ را با روغن و نمک ۸ دقیقه سرخ کنید. مرغ را کنار تابه بزنید و پیاز، فلفل و سیر را ۵ دقیقه تفت دهید، بعد پاپریکا و گوجه‌ی رنده‌شده را اضافه کنید و ۳ دقیقه بپزید.'],
  [32,'Add the rice and stir to coat, then pour in 1.1 litres of hot stock or water with the saffron and salt. Spread the rice evenly and simmer over medium heat without stirring for 12 minutes.','برنج را اضافه کنید و هم بزنید تا به روغن آغشته شود، بعد ۱٫۱ لیتر آب‌مرغ یا آب داغ را با زعفران و نمک بریزید. برنج را یکدست پخش کنید و بدون هم زدن ۱۲ دقیقه روی حرارت متوسط بپزید.'],
  [20,'Scatter over the peas and press the shrimp into the rice. Cook 8–10 minutes more on low until the liquid is absorbed, then raise the heat for 1–2 minutes to crisp the bottom.','نخودفرنگی را رویش بپاشید و میگوها را در برنج فرو کنید. ۸ تا ۱۰ دقیقه دیگر روی حرارت ملایم بپزید تا آب کشیده شود، بعد ۱ تا ۲ دقیقه حرارت را زیاد کنید تا ته آن برشته شود.'],
  [8,'Take off the heat, cover with a clean cloth or foil and rest 5 minutes.','از روی گاز بردارید، رویش را با دستمال تمیز یا فویل بپوشانید و ۵ دقیقه صبر کنید.'],
  [0,'Serve from the pan with lemon wedges and parsley.','در همان تابه با قاچ‌های لیمو و جعفری سرو کنید.']],
 k:[['Liquid is still bubbling around the edges and the rice has a hard centre.','The liquid is gone, the grains are tender and separate, the shrimp are pink, and the pan crackles softly with a toasty smell — a thin, crisp crust like tahdig has formed.','A sharp burnt smell and a black crust underneath; leave the bottom behind and serve only from the top.'],
    ['هنوز دور تابه آب قل می‌زند و وسط دانه‌های برنج سفت است.','آب کاملاً کشیده شده، دانه‌ها نرم و جدا از هم‌اند، میگوها صورتی شده‌اند و تابه آرام جلز و ولز می‌کند و بوی برشتگی می‌دهد؛ ته آن مثل ته‌دیگ نازک و ترد شده.','بوی تند سوختگی می‌آید و ته آن سیاه شده؛ ته را نتراشید و فقط از روی آن سرو کنید.']],
 m:'gazpacho'});

R({id:'gazpacho',c:'soup',min:75,sv:4,n:[210,4,19,14],app:'blender|food processor',cu:'es',col:'#D2462F',
 t:['Gazpacho','گازپاچو'],d:['Chilled Spanish soup of ripe tomatoes, cucumber, pepper and garlic.','سوپ سرد اسپانیایی با گوجه‌ی رسیده، خیار، فلفل دلمه‌ای و سیر'],
 i:'tomato:1:kg;cucumber:1;bell pepper:1;onion:0.5;garlic:1:clove;vinegar:2:tbsp;bread:1::o;oil:4:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[75,'Roughly chop the tomatoes, most of the cucumber and pepper, the onion and garlic; finely dice a little cucumber and pepper and keep it for the top.','گوجه‌ها، بیشتر خیار و فلفل دلمه‌ای، پیاز و سیر را درشت خرد کنید؛ کمی خیار و فلفل را ریز خرد کنید و برای روی سوپ نگه دارید.'],
  [65,'Blend the vegetables with the bread (soaked in water and squeezed), vinegar, salt and pepper until smooth, then blend in the oil in a thin stream.','سبزیجات را با نان (خیس‌خورده و آب‌گرفته)، سرکه، نمک و فلفل در مخلوط‌کن کاملاً صاف کنید، بعد روغن را آرام و باریک در حین کار اضافه کنید.'],
  [60,'Taste, adjust the salt and vinegar, and chill for at least an hour.','بچشید، نمک و سرکه را تنظیم کنید و دست‌کم یک ساعت در یخچال بگذارید.'],
  [0,'Stir, pour into chilled bowls and top with the diced cucumber, pepper and a drizzle of oil.','هم بزنید، در کاسه‌های سرد بریزید و خیار و فلفل ریزشده و کمی روغن رویش بریزید.']],
 k:[['Thin, watery and pale pink, and only cool rather than cold.','Smooth, silky and bright orange-red, ice-cold, and fresh-tasting with a gentle tang of vinegar and garlic.','Pale, foamy and orange from over-blending the oil; let it settle in the fridge and stir before serving.'],
    ['رقیق، آبکی و صورتی کم‌رنگ است و فقط خنک است، نه سرد.','صاف، لطیف و قرمز نارنجی روشن است، کاملاً سرد است و طعمی تازه با ترشی ملایم سرکه و سیر دارد.','از زیاد مخلوط کردن روغن، کم‌رنگ، کف‌دار و نارنجی شده؛ بگذارید در یخچال بنشیند و پیش از سرو هم بزنید.']],
 m:'paella'});

R({id:'greek-salad',c:'salad',min:10,sv:4,n:[330,9,14,27],app:'',cu:'gr',col:'#7FA650',
 t:['Greek salad','سالاد یونانی'],d:['Chunky tomatoes, cucumber, onion and olives under a slab of feta and oregano.','گوجه، خیار، پیاز و زیتون درشت‌خردشده با یک تکه پنیر فتا و پونه‌کوهی'],
 i:'tomato:4;cucumber:1;onion:1;olives:80:g;cheese:200:g;oregano:1:tsp;bell pepper:1::o;vinegar:1:tbsp:o;oil:4:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[10,'Cut the tomatoes into wedges, the cucumber into thick half-moons, the pepper into strips and the red onion into thin rings.','گوجه‌ها را قاچ کنید، خیار را نیم‌دایره‌های ضخیم، فلفل دلمه‌ای را خلالی و پیاز قرمز را حلقه‌های نازک ببرید.'],
  [4,'Toss the vegetables and olives in a bowl with a pinch of salt, the vinegar and half the oil.','سبزیجات و زیتون را در کاسه با کمی نمک، سرکه و نصف روغن مخلوط کنید.'],
  [0,'Lay the feta on top in one piece, sprinkle with oregano and black pepper, drizzle with the rest of the oil and serve.','پنیر فتا را یک‌تکه روی سالاد بگذارید، پونه‌کوهی و فلفل سیاه رویش بپاشید، بقیه‌ی روغن را رویش بچکانید و سرو کنید.']],
 k:[['The tomatoes are hard and pale and the salad tastes flat.','Ripe tomatoes that smell sweet, crunchy cucumber, and juices pooling with the oil at the bottom of the bowl, ready to mop up with bread.','The salad sat too long after salting and is limp and swimming in water; drain it and dress it again just before serving.'],
    ['گوجه‌ها سفت و کم‌رنگ‌اند و سالاد بی‌مزه است.','گوجه‌ها رسیده‌اند و بوی شیرین می‌دهند، خیار ترد است و آب سالاد با روغن ته کاسه جمع شده و می‌شود با نان برش داشت.','سالاد بعد از نمک زدن زیادی مانده و وا رفته و در آب غوطه‌ور است؛ آبش را خالی کنید و پیش از سرو دوباره روغن و سرکه بزنید.']],
 m:'chicken-souvlaki'});

R({id:'chicken-souvlaki',c:'kebab',min:100,sv:4,n:[560,60,37,17],app:'grill|stove|oven',cu:'gr',col:'#C98B45',
 t:['Chicken souvlaki','سوولاکی مرغ'],d:['Lemon, garlic and oregano chicken skewers, grilled and served in warm pita.','سیخ‌های مرغ با لیمو، سیر و پونه‌کوهی که کباب می‌شود و در نان پیتای گرم سرو می‌شود'],
 i:'chicken:700:g;lemon:1;garlic:3:clove;oregano:2:tsp;bread:4;paprika:1:tsp:o;tomato:2::o;onion:1::o;oil:4:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[100,'Cut the chicken into 3 cm cubes and mix with the lemon juice, crushed garlic, oregano, paprika, oil, salt and pepper. Cover and marinate in the fridge for at least an hour. Soak wooden skewers in water.','مرغ را مکعب‌های ۳ سانتی ببرید و با آبلیمو، سیر له‌شده، پونه‌کوهی، پاپریکا، روغن، نمک و فلفل مخلوط کنید. رویش را بپوشانید و دست‌کم یک ساعت در یخچال بگذارید. سیخ‌های چوبی را در آب خیس کنید.'],
  [30,'Thread the chicken onto the skewers and heat the grill or a griddle pan until very hot. Slice the tomatoes and onion.','مرغ‌ها را به سیخ بکشید و گریل یا تابه‌ی گریل را خیلی داغ کنید. گوجه و پیاز را خلالی کنید.'],
  [20,'Grill the skewers for 10–12 minutes, turning every few minutes, until charred at the edges and cooked through.','سیخ‌ها را ۱۰ تا ۱۲ دقیقه کباب کنید و هر چند دقیقه برگردانید تا لبه‌ها کمی کبابی و داخلشان کاملاً پخته شود.'],
  [5,'Rest the skewers for a few minutes and warm the pitas on the grill, 30 seconds a side.','سیخ‌ها را چند دقیقه کنار بگذارید و نان پیتا را هر طرف ۳۰ ثانیه روی گریل گرم کنید.'],
  [0,'Serve the chicken in the warm pitas with tomato, onion and tzatziki.','مرغ را در نان پیتای گرم با گوجه، پیاز و تزاتزیکی سرو کنید.']],
 k:[['The inside of a cube is still pink and glassy and the juices run cloudy.','Golden with charred edges, firm when pressed, white right through with clear juices.','Dry, stringy and shrunken on the skewer; brush with a little oil and lemon and serve with plenty of tzatziki.'],
    ['داخل تکه‌ها هنوز صورتی و شیشه‌ای است و آبش کدر است.','رویش طلایی با لبه‌های کمی کبابی است، با فشار انگشت سفت است و داخلش کاملاً سفید و آبش شفاف است.','مرغ خشک و رشته‌رشته شده و روی سیخ جمع شده؛ کمی روغن و آبلیمو رویش بزنید و با تزاتزیکی زیاد سرو کنید.']],
 m:'tzatziki,greek-salad'});

R({id:'tzatziki',c:'side',min:20,sv:4,n:[130,9,5,8],app:'',cu:'gr',col:'#EDEFE4',
 t:['Tzatziki','تزاتزیکی'],d:['Greece’s garlicky cousin of mast-o-khiar: thick yogurt, grated cucumber and dill.','پسرخاله‌ی یونانی ماست و خیار: ماست غلیظ با خیار رنده‌شده، سیر و شوید'],
 i:'yogurt:400:g;cucumber:1;garlic:1:clove;dill|mint:2:tbsp;lemon:0.5::o;oil:1:tbsp:s;salt::taste:s',
 s:[[20,'Coarsely grate the cucumber, toss with a pinch of salt and leave in a sieve for 10 minutes.','خیار را درشت رنده کنید، کمی نمک بزنید و ۱۰ دقیقه در آبکش بگذارید.'],
  [8,'Squeeze the cucumber hard in your hands or a clean cloth to get rid of as much water as you can.','خیار را با دست یا در یک پارچه‌ی تمیز محکم فشار دهید تا هر چه بیشتر آبش گرفته شود.'],
  [5,'Stir the cucumber into the thick yogurt (strain it first if it is thin) with the crushed garlic, chopped dill, a squeeze of lemon and salt.','خیار را با سیر له‌شده، شوید خردشده، کمی آبلیمو و نمک در ماست غلیظ هم بزنید (اگر ماست رقیق است، اول آبش را بگیرید).'],
  [0,'Spread in a bowl, drizzle with the oil and serve cold with bread or souvlaki.','در کاسه پهن کنید، روغن را رویش بچکانید و سرد با نان یا سوولاکی سرو کنید.']],
 k:[['Loose and runny, with water pooling at the edges of the bowl.','Thick enough to hold a swirl from the spoon, cool and creamy, with a clear bite of garlic.','Thin and watery after standing; pour off the liquid or stir in a spoon of thicker yogurt.'],
    ['شل و روان است و دور کاسه آب جمع شده.','آن‌قدر غلیظ است که رد قاشق رویش می‌ماند، خنک و کرمی است و تندی سیر به‌خوبی حس می‌شود.','بعد از ماندن رقیق و آبکی شده؛ آبش را خالی کنید یا یک قاشق ماست غلیظ‌تر اضافه کنید.']],
 m:'chicken-souvlaki'});

R({id:'moussaka',c:'main',min:120,sv:6,n:[590,27,21,42],app:'stove,oven',cu:'gr',col:'#B7703A',
 t:['Beef moussaka','موساکا گوشت'],d:['Baked layers of roasted eggplant, cinnamon-spiced beef and creamy white sauce.','لایه‌های بادمجان کبابی، گوشت چرخ‌کرده با دارچین و سس سفید خامه‌ای که در فر پخته می‌شود'],
 i:'eggplant:3;ground meat:600:g;onion:1;garlic:2:clove;tomato:3;tomato paste:2:tbsp;cinnamon:0.5:tsp;oregano:1:tsp:o;butter:50:g;flour:50:g;milk:600:ml;eggs:1;cheese:60:g;oil:5:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[120,'Heat the oven to 220°C. Slice the eggplants into 1 cm rounds, brush both sides with oil, sprinkle with salt and roast on trays for 25 minutes until soft and golden.','فر را روی ۲۲۰ درجه روشن کنید. بادمجان‌ها را حلقه‌های ۱ سانتی ببرید، دو طرفشان روغن بمالید، نمک بزنید و در سینی ۲۵ دقیقه در فر بپزید تا نرم و طلایی شوند.'],
  [110,'Meanwhile fry the chopped onion and garlic in 1 tbsp oil, add the beef and brown it. Stir in the tomato paste, chopped tomatoes, cinnamon, oregano, salt, pepper and 150 ml water and simmer 25 minutes until thick.','در همین فاصله پیاز و سیر خردشده را در ۱ قاشق روغن تفت دهید، گوشت را اضافه کنید و سرخ کنید. رب، گوجه‌ی خردشده، دارچین، پونه‌کوهی، نمک، فلفل و ۱۵۰ میلی‌لیتر آب را اضافه کنید و ۲۵ دقیقه بپزید تا غلیظ شود.'],
  [75,'Make the white sauce: melt the butter, stir in the flour for a minute, whisk in the milk gradually and cook until thick. Off the heat, beat in the egg and half the cheese. Turn the oven down to 180°C.','سس سفید را درست کنید: کره را آب کنید، آرد را اضافه کنید و یک دقیقه هم بزنید، شیر را کم‌کم اضافه کنید و هم بزنید تا غلیظ شود. از روی گاز بردارید و تخم‌مرغ و نصف پنیر را در آن هم بزنید. دمای فر را روی ۱۸۰ درجه کم کنید.'],
  [62,'In a baking dish layer half the eggplant, all the meat sauce, then the rest of the eggplant. Pour over the white sauce and sprinkle with the remaining cheese.','در ظرف پیرکس نصف بادمجان‌ها، همه‌ی سس گوشت و بعد بقیه‌ی بادمجان‌ها را لایه‌لایه بچینید. سس سفید را رویش بریزید و بقیه‌ی پنیر را رویش بپاشید.'],
  [55,'Bake for 40 minutes until deep golden on top, then let it rest 15 minutes so it slices cleanly.','۴۰ دقیقه بپزید تا رویش طلایی پررنگ شود، بعد ۱۵ دقیقه صبر کنید تا تمیز برش بخورد.'],
  [0,'Cut into squares and serve warm.','مربعی برش بزنید و گرم سرو کنید.']],
 k:[['The white sauce is pale and wobbly and the edges are barely bubbling.','The top is puffed, deep golden and lightly blistered, the edges bubble, and the centre feels set when pressed.','The top is dark brown and the sauce has shrunk from the edges; scrape off any burnt patches and let it rest well before cutting.'],
    ['سس سفید رنگ‌پریده است و می‌لرزد و کناره‌ها به‌زور قل می‌زنند.','رویش پف کرده، طلایی پررنگ و کمی حباب‌دار است، کناره‌ها قل می‌زند و وسطش با فشار انگشت سفت شده.','رویش قهوه‌ای تیره شده و سس از کناره‌ها جمع شده؛ قسمت‌های سوخته را بتراشید و پیش از برش خوب صبر کنید.']],
 m:'greek-salad,tzatziki'});

R({id:'beef-tacos',c:'main',min:30,sv:4,n:[480,27,36,24],app:'stove',cu:'mx',col:'#C2612B',
 t:['Beef tacos','تاکو گوشت'],d:['Spiced beef in warm tortillas with salsa and cheese.','گوشت ادویه‌دار در نان تورتیای گرم با سالسا و پنیر'],
 i:'tortilla:8;ground meat:500:g;onion:1;tomato:2;lettuce:::o;cheese:100:g:o;cumin:1:tsp;paprika:1:tsp:o;chili flakes::pinch:o;lemon:1::o;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[30,'Finely chop the onion and tomatoes and shred the lettuce.','پیاز و گوجه را ریز خرد کنید و کاهو را خلالی کنید.'],
  [22,'Fry half the onion in the oil, add the beef and cook, breaking it up, until browned — about 8 minutes.','نصف پیاز را در روغن تفت دهید، گوشت را اضافه کنید و با قاشق از هم باز کنید تا قهوه‌ای شود؛ حدود ۸ دقیقه.'],
  [12,'Stir in the cumin, paprika, chili, salt and 3 tbsp water and cook 5 minutes more.','زیره، پاپریکا، فلفل، نمک و ۳ قاشق آب را اضافه کنید و ۵ دقیقه دیگر بپزید.'],
  [5,'Warm the tortillas in a dry pan, 20 seconds a side.','نان تورتیا را در تابه‌ی خشک هر طرف ۲۰ ثانیه گرم کنید.'],
  [0,'Fill with beef, tomato, onion, lettuce and cheese, and squeeze over lemon.','گوشت، گوجه، پیاز، کاهو و پنیر را لای نان بگذارید و کمی آبلیمو بزنید.']],
 k:[['The beef is still pink in places and watery in the pan.','Browned all over with no pink, the spices smell toasted and the pan is almost dry.','Dry, dark and crunchy bits; add a splash of water to loosen it.'],
    ['گوشت جاهایی هنوز صورتی است و در تابه آب دارد.','گوشت همه‌جا قهوه‌ای و بدون صورتی است، بوی ادویه‌ی تفت‌خورده می‌آید و تابه تقریباً خشک است.','گوشت خشک و تیره و ترد شده؛ کمی آب اضافه کنید تا نرم شود.']],
 m:'guacamole,mexican-rice'});

R({id:'chicken-burrito',c:'main',min:40,sv:4,n:[680,42,72,24],app:'stove',cu:'mx',col:'#D9A45B',
 t:['Chicken burrito','بوریتو مرغ'],d:['A big flour tortilla rolled around spiced chicken, rice, beans and cheese.','نان تورتیای بزرگ پر از مرغ ادویه‌دار، برنج، لوبیا و پنیر'],
 i:'tortilla:4;chicken:500:g;rice:1:cup;kidney beans:1:cup;onion:1;bell pepper:1;tomato:2;cheese:100:g;cumin:1:tsp;paprika:1:tsp;chili flakes::pinch:o;coriander:::o;avocado:1::o;lemon:1::o;oil:2:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[40,'Rinse the rice, add 1½ cups water, a little salt and a drop of oil, and cook covered on low heat for 20 minutes.','برنج را بشویید، یک و نیم پیمانه آب، کمی نمک و چند قطره روغن اضافه کنید و با درِ بسته روی حرارت ملایم ۲۰ دقیقه بپزید.'],
  [35,'Cut the chicken into thin strips and toss with the cumin, paprika, chili, salt and pepper. Slice the onion and pepper and dice the tomatoes.','مرغ را نواری باریک ببرید و با زیره، پاپریکا، فلفل قرمز، نمک و فلفل سیاه مخلوط کنید. پیاز و فلفل دلمه‌ای را خلالی و گوجه را مکعبی خرد کنید.'],
  [25,'Fry the chicken in the hot oil over high heat for 7–8 minutes until golden, then add the onion and pepper and cook 4 minutes more.','مرغ را در روغن داغ روی حرارت زیاد ۷ تا ۸ دقیقه تفت دهید تا طلایی شود، بعد پیاز و فلفل دلمه‌ای را اضافه کنید و ۴ دقیقه‌ی دیگر بپزید.'],
  [12,'Warm the drained beans with a splash of water, mash them lightly and season. Fluff the rice and stir in chopped coriander and a squeeze of lime.','لوبیای آبکش‌شده را با کمی آب گرم کنید، کمی له کنید و نمک بزنید. برنج را با چنگال از هم باز کنید و گشنیز خردشده و کمی آبلیمو را قاطی کنید.'],
  [5,'Warm the tortillas, then lay rice, beans, chicken, tomato, cheese and sliced avocado down the middle, fold in the sides and roll up tightly.','نان‌ها را گرم کنید، برنج، لوبیا، مرغ، گوجه، پنیر و برش‌های آووکادو را وسط نان بچینید، دو طرف را تا کنید و محکم لوله کنید.'],
  [0,'Toast seam-side down in a dry pan for a minute a side until golden, cut in half and serve.','لبه‌ی نان را رو به پایین در تابه‌ی خشک بگذارید و هر طرف یک دقیقه برشته کنید تا طلایی شود، از وسط نصف کنید و سرو کنید.']],
 k:[['The thickest strips are still pink in the middle when you cut one open.','White right through, golden at the edges, and the juices run clear.','Dry and stringy; mix it with the beans and a squeeze of lime to moisten it.'],
    ['ضخیم‌ترین تکه‌ها وقتی بازشان می‌کنید هنوز وسطشان صورتی است.','مرغ تا مغز سفید است، لبه‌هایش طلایی شده و آبش شفاف است.','مرغ خشک و رشته‌رشته شده؛ آن را با لوبیا و کمی آبلیمو مخلوط کنید تا نرم شود.']],
 m:'guacamole'});

R({id:'cheese-quesadilla',c:'main',min:15,sv:2,n:[670,33,52,37],app:'stove',cu:'mx',col:'#E3B25A',
 t:['Cheese quesadilla','کسادیا پنیری'],d:['Crisp golden tortillas with a gooey melted-cheese filling.','نان تورتیای ترد و طلایی با مغز پنیر آب‌شده و کش‌دار'],
 i:'tortilla:4;cheese:200:g;bell pepper:0.5::o;green onion:2::o;chili:1::o;corn:3:tbsp:o;oil:1:tsp:s',
 s:[[15,'Grate the cheese and finely chop the pepper, green onions and chili.','پنیر را رنده کنید و فلفل دلمه‌ای، پیازچه و فلفل تند را ریز خرد کنید.'],
  [10,'Brush a wide pan with a little oil, lay in a tortilla, scatter over half the cheese, vegetables and corn and top with a second tortilla.','تابه‌ی پهنی را کمی چرب کنید، یک نان تورتیا در آن بگذارید، نصف پنیر و سبزیجات و ذرت را رویش بریزید و یک نان دیگر رویش بگذارید.'],
  [7,'Cook over medium-low heat for 2–3 minutes until golden underneath, flip with the help of a plate and cook 2 minutes more. Repeat with the rest.','روی حرارت ملایم تا متوسط ۲ تا ۳ دقیقه بپزید تا زیرش طلایی شود، با کمک یک بشقاب برگردانید و ۲ دقیقه‌ی دیگر بپزید. با بقیه‌ی مواد هم همین کار را تکرار کنید.'],
  [0,'Rest for a minute, cut into wedges and serve with salsa or guacamole.','یک دقیقه صبر کنید، قاچ کنید و با سالسا یا گواکامولی سرو کنید.']],
 k:[['The tortilla is still pale and the cheese at the edges is still firm.','Golden and crisp in spots, and the cheese oozes at the edges when you press the top.','Dark brown, brittle and smelling scorched; lower the heat for the next one.'],
    ['نان هنوز رنگ‌پریده است و پنیرِ کناره‌ها آب نشده.','نان جابه‌جا طلایی و ترد شده و وقتی رویش فشار می‌دهید پنیر از کناره‌ها بیرون می‌زند.','نان قهوه‌ای تیره و شکننده شده و بوی سوختگی می‌دهد؛ برای بعدی حرارت را کم کنید.']],
 m:'guacamole'});

R({id:'guacamole',c:'side',min:10,sv:4,n:[180,2,11,15],app:'',cu:'mx',col:'#8DB33E',
 t:['Guacamole','گواکامولی'],d:['Creamy, chunky avocado dip with lime, onion and coriander.','دیپ آووکادوی خامه‌ای با لیمو، پیاز و گشنیز'],
 i:'avocado:3;lemon:1;tomato:1;onion:0.5;coriander:0.5:bunch;chili:1::o;garlic:1:clove:o;salt::taste:s',
 s:[[10,'Very finely chop the onion, tomato, chili and coriander and crush the garlic.','پیاز، گوجه، فلفل تند و گشنیز را خیلی ریز خرد کنید و سیر را له کنید.'],
  [5,'Halve the avocados, remove the stones, scoop the flesh into a bowl and mash with a fork, leaving some chunks.','آووکادوها را نصف کنید، هسته را دربیاورید، گوشتش را با قاشق در کاسه بریزید و با چنگال له کنید، طوری که کمی تکه‌تکه بماند.'],
  [2,'Stir in the chopped vegetables, lime juice and salt, then taste and adjust.','سبزیجات خردشده، آبلیمو و نمک را اضافه کنید و هم بزنید، بعد بچشید و مزه‌اش را تنظیم کنید.'],
  [0,'Serve straight away with tortilla chips or tacos, or press cling film onto the surface if it has to wait.','فوراً با چیپس تورتیا یا تاکو سرو کنید، یا اگر قرار است بماند، سلفون را مستقیم روی سطحش بچسبانید.']],
 k:[['The avocado feels hard when pressed and mashes into stiff, pale lumps.','Ripe avocado gives gently under your thumb and mashes into a bright green, creamy dip with small chunks.','Mashed to a smooth paste or turning brown on top; stir in more lime and a little chopped tomato and serve right away.'],
    ['آووکادو با فشار انگشت سفت است و به تکه‌های سفت و کم‌رنگ له می‌شود.','آووکادوی رسیده زیر انگشت کمی نرم می‌شود و دیپی سبز روشن و خامه‌ای با تکه‌های کوچک درست می‌شود.','کاملاً پوره شده یا رویش قهوه‌ای شده؛ کمی آبلیمو و گوجه‌ی خردشده‌ی دیگر اضافه کنید و فوراً سرو کنید.']],
 m:'beef-tacos,loaded-nachos'});

R({id:'loaded-nachos',c:'main',min:30,sv:4,n:[710,35,50,41],app:'stove,oven',cu:'mx',col:'#E0A83C',
 t:['Loaded nachos','ناچو مخصوص'],d:['Homemade tortilla chips piled with spiced beef, beans, melted cheese and fresh salsa.','چیپس تورتیای خانگی با گوشت ادویه‌دار، لوبیا، پنیر آب‌شده و سالسای تازه'],
 i:'tortilla:6;ground meat:300:g;cheese:200:g;kidney beans:1:cup:o;tomato:2;onion:1;chili:1::o;cumin:1:tsp;paprika:1:tsp;yogurt:4:tbsp:o;olives:::o;coriander:::o;lemon:1::o;oil:2:tbsp:s;salt::taste:s',
 s:[[30,'Heat the oven to 200 °C. Cut each tortilla into 8 triangles, toss with 1 tbsp oil and a pinch of salt and spread out on two trays.','فر را روی ۲۰۰ درجه روشن کنید. هر نان تورتیا را ۸ مثلث ببرید، با یک قاشق روغن و کمی نمک مخلوط کنید و در دو سینی پهن کنید.'],
  [25,'Bake for 6–8 minutes until crisp and golden. Meanwhile fry half the onion in the remaining oil, add the meat and cook, breaking it up, until browned.','۶ تا ۸ دقیقه بپزید تا ترد و طلایی شود. در همین فاصله نصف پیاز را در بقیه‌ی روغن تفت دهید، گوشت را اضافه کنید و با قاشق از هم باز کنید تا قهوه‌ای شود.'],
  [15,'Stir the cumin, paprika, salt and drained beans into the meat and cook 3 minutes more.','زیره، پاپریکا، نمک و لوبیای آبکش‌شده را به گوشت اضافه کنید و ۳ دقیقه‌ی دیگر بپزید.'],
  [12,'Pile the chips onto one big tray, spoon over the meat and beans, cover with grated cheese and bake 5–6 minutes. Meanwhile chop the tomatoes, the rest of the onion, the chili and the coriander.','چیپس‌ها را در یک سینی بزرگ روی هم بریزید، گوشت و لوبیا را رویش پخش کنید، پنیر رنده‌شده را بپاشید و ۵ تا ۶ دقیقه در فر بگذارید. در همین فاصله گوجه، باقی پیاز، فلفل تند و گشنیز را خرد کنید.'],
  [0,'Scatter over the fresh salsa and olives, add spoonfuls of yogurt, squeeze over lime and serve at once.','سالسای تازه و زیتون را رویش بریزید، چند قاشق ماست بگذارید، کمی آبلیمو بزنید و فوراً سرو کنید.']],
 k:[['The cheese has softened but still holds its shreds.','The cheese is fully melted and bubbling in spots and the chip edges are golden.','The cheese has turned brown and hard and the chip tips are dark; pile on the toppings generously to soften it.'],
    ['پنیر نرم شده اما هنوز رشته‌رشته است.','پنیر کاملاً آب شده و جابه‌جا حباب می‌زند و لبه‌ی چیپس‌ها طلایی است.','پنیر قهوه‌ای و سفت شده و نوک چیپس‌ها تیره است؛ رویش را حسابی با سالسا و ماست بپوشانید تا نرم شود.']],
 m:'guacamole'});

R({id:'chili-con-carne',c:'stew',min:75,sv:6,n:[470,30,26,27],app:'stove',cu:'mx',col:'#8E3B22',
 t:['Chili con carne','چیلی کان کارنه'],d:['A rich, smoky beef and kidney bean chili, slow-simmered in tomato.','خوراک غلیظ و دودیِ گوشت و لوبیا قرمز که آرام در گوجه جا می‌افتد'],
 i:'ground meat:750:g;kidney beans:500:g;onion:2;garlic:3:clove;bell pepper:1;tomato:4;tomato paste:2:tbsp;cumin:2:tsp;paprika:2:tsp;chili flakes:1:tsp;oregano:1:tsp:o;cinnamon::pinch:o;chocolate:15:g:o;coriander:::o;yogurt:::o;oil:2:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[75,'Finely chop the onions, garlic and pepper, and grate the tomatoes.','پیاز، سیر و فلفل دلمه‌ای را ریز خرد کنید و گوجه‌ها را رنده کنید.'],
  [65,'Fry the onions in the oil over medium heat until soft and golden, about 8 minutes, then add the garlic and pepper for 2 minutes.','پیاز را در روغن روی حرارت متوسط حدود ۸ دقیقه تفت دهید تا نرم و طلایی شود، بعد سیر و فلفل دلمه‌ای را اضافه کنید و ۲ دقیقه تفت دهید.'],
  [55,'Turn up the heat, add the meat and brown it well, breaking it up, for 8–10 minutes. Stir in the spices and tomato paste and fry for 1 minute.','حرارت را زیاد کنید، گوشت را اضافه کنید و ۸ تا ۱۰ دقیقه با قاشق از هم باز کنید تا خوب قهوه‌ای شود. ادویه‌ها و رب را اضافه کنید و یک دقیقه تفت دهید.'],
  [45,'Add the tomatoes, 1 cup water, salt and pepper, bring to a boil, then half-cover and simmer on low for 30 minutes, stirring now and then.','گوجه، یک پیمانه آب، نمک و فلفل را اضافه کنید، بگذارید جوش بیاید، بعد در قابلمه را نیمه‌باز بگذارید و روی حرارت ملایم ۳۰ دقیقه بپزید و گاهی هم بزنید.'],
  [15,'Stir in the drained beans and the chocolate and simmer uncovered for 15 minutes until thick.','لوبیای آبکش‌شده و شکلات را اضافه کنید و با درِ باز ۱۵ دقیقه بپزید تا غلیظ شود.'],
  [0,'Taste for salt and heat and serve with rice, a spoonful of yogurt and chopped coriander.','نمک و تندی‌اش را بچشید و تنظیم کنید و با برنج، یک قاشق ماست و گشنیز خردشده سرو کنید.']],
 k:[['Still thin and watery; a spoon drawn across the pot leaves no trail.','Thick and glossy with a thin sheen of red oil on top; a spoon drawn through leaves a trail that slowly closes.','Very thick and catching on the bottom with a scorched smell; add a splash of hot water and do not scrape up the burnt bits.'],
    ['هنوز رقیق و آبکی است و قاشق را که از وسطش رد کنید جایش نمی‌ماند.','غلیظ و براق است و لایه‌ی نازکی روغن قرمز رویش نشسته؛ قاشق را که رد کنید جایش آرام بسته می‌شود.','خیلی غلیظ شده، ته گرفته و بوی سوختگی می‌دهد؛ کمی آب جوش اضافه کنید و ته‌مانده‌ی سوخته را هم نزنید.']],
 m:'mexican-rice,guacamole'});

R({id:'chicken-enchiladas',c:'main',min:60,sv:4,n:[690,50,55,30],app:'stove,oven',cu:'mx',col:'#B8472A',
 t:['Chicken enchiladas','انچیلادا مرغ'],d:['Tortillas rolled around shredded chicken, baked in red chili sauce under melted cheese.','نان تورتیای پر از مرغ ریش‌ریش که با سس قرمز و پنیر در فر پخته می‌شود'],
 i:'tortilla:8;chicken:500:g;cheese:200:g;onion:1;garlic:2:clove;tomato:4;tomato paste:2:tbsp;paprika:2:tsp;cumin:1:tsp;chili flakes:0.5:tsp:o;oregano:1:tsp:o;yogurt:::o;coriander:::o;oil:2:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[60,'Put the chicken in a pan, cover with water, add a little salt and simmer for 20 minutes until cooked through.','مرغ را در قابلمه بگذارید، رویش آب بریزید، کمی نمک بزنید و ۲۰ دقیقه بپزید تا کاملاً پخته شود.'],
  [55,'Meanwhile fry the chopped onion and garlic in the oil for 5 minutes, stir in the spices and tomato paste, then add the grated tomatoes, 1 cup water and salt and simmer 15 minutes. Heat the oven to 190 °C.','در همین فاصله پیاز و سیر خردشده را ۵ دقیقه در روغن تفت دهید، ادویه‌ها و رب را اضافه کنید، بعد گوجه‌ی رنده‌شده، یک پیمانه آب و نمک را بریزید و ۱۵ دقیقه بپزید. فر را روی ۱۹۰ درجه روشن کنید.'],
  [38,'Shred the chicken with two forks and mix it with a third of the sauce and half the cheese.','مرغ را با دو چنگال ریش‌ریش کنید و با یک‌سوم سس و نصف پنیر مخلوط کنید.'],
  [32,'Spread a little sauce in a baking dish. Fill each tortilla with chicken, roll up and lay seam-side down, then pour over the rest of the sauce and scatter over the remaining cheese.','کف ظرف پیرکس کمی سس بریزید. هر نان را با مرغ پر کنید، لوله کنید و با لبه رو به پایین در ظرف بچینید، بعد بقیه‌ی سس را رویش بریزید و باقی پنیر را بپاشید.'],
  [25,'Bake for 20 minutes until bubbling and golden.','۲۰ دقیقه در فر بپزید تا سس قل بزند و رویش طلایی شود.'],
  [0,'Rest for 5 minutes, top with yogurt and coriander and serve.','۵ دقیقه صبر کنید، رویش ماست و گشنیز بریزید و سرو کنید.']],
 k:[['The cheese has melted but is still pale and the sauce only bubbles in the middle.','The sauce bubbles at the edges, the cheese has golden spots and the tortilla ends are lightly crisp.','The tortilla edges are hard and dark and the sauce has dried at the sides; spoon over a little warm sauce or yogurt before serving.'],
    ['پنیر آب شده اما هنوز رنگ‌پریده است و سس فقط وسط ظرف قل می‌زند.','سس کناره‌ها قل می‌زند، پنیر جابه‌جا طلایی شده و سر نان‌ها کمی ترد است.','لبه‌ی نان‌ها سفت و تیره شده و سسِ کناره‌ها خشک شده؛ قبل از سرو کمی سس گرم یا ماست رویش بریزید.']],
 m:'mexican-rice,guacamole'});

R({id:'mexican-rice',c:'rice',min:35,sv:4,n:[380,7,64,11],app:'stove',cu:'mx',col:'#D8703A',
 t:['Mexican red rice','برنج قرمز مکزیکی'],d:['Fluffy toasted rice cooked in a garlicky tomato broth.','برنج دون‌دون و تفت‌خورده که در سس گوجه و سیر دم می‌کشد'],
 i:'rice:1.5:cup;tomato:2;onion:0.5;garlic:2:clove;tomato paste:1:tbsp;cumin:0.5:tsp;peas:0.5:cup:o;carrot:1::o;chili:1::o;coriander:::o;lemon:1::o;oil:3:tbsp:s;salt::taste:s',
 s:[[35,'Rinse the rice until the water runs clear and drain well. Finely grate the tomatoes, onion and garlic together, and dice the carrot.','برنج را آن‌قدر بشویید تا آبش زلال شود و خوب آبکش کنید. گوجه، پیاز و سیر را با هم ریز رنده کنید و هویج را مکعبی خرد کنید.'],
  [28,'Heat the oil in a pot and fry the rice over medium heat, stirring, for 5–6 minutes until golden and nutty-smelling.','روغن را در قابلمه داغ کنید و برنج را روی حرارت متوسط ۵ تا ۶ دقیقه مدام هم بزنید و تفت دهید تا طلایی شود و بوی بوداده بدهد.'],
  [22,'Stir in the tomato mixture, tomato paste and cumin and cook 2 minutes, then add 2 cups hot water, salt, the carrot, peas and whole chili and bring to a boil.','مخلوط گوجه، رب و زیره را اضافه کنید و ۲ دقیقه تفت دهید، بعد ۲ پیمانه آب داغ، نمک، هویج، نخودفرنگی و فلفل تند درسته را بریزید و بگذارید جوش بیاید.'],
  [18,'Cover tightly, turn the heat to the lowest setting and cook for 15 minutes without lifting the lid.','در قابلمه را محکم ببندید، حرارت را تا آخر کم کنید و ۱۵ دقیقه بدون برداشتن در بپزید.'],
  [3,'Turn off the heat and leave covered to rest for 3 minutes.','زیر قابلمه را خاموش کنید و بگذارید ۳ دقیقه با درِ بسته بماند.'],
  [0,'Fluff with a fork, scatter over coriander and serve with lime wedges.','با چنگال از هم باز کنید، گشنیز رویش بپاشید و با قاچ لیمو سرو کنید.']],
 k:[['Liquid still pools at the bottom and the grains are firm in the centre.','All the liquid is absorbed, small steam holes dot the surface and the grains are tender, separate and orange-red.','Mushy and sticking, with a toasty smell from the bottom; spread it on a tray to steam off and leave the crust behind.'],
    ['هنوز ته قابلمه آب هست و وسط دانه‌ها سفت است.','آب کاملاً کشیده شده، روی برنج سوراخ‌های کوچک بخار پیداست و دانه‌ها نرم، دون‌دون و نارنجی‌قرمزند.','برنج شفته شده و به هم چسبیده و از ته بوی برشتگی می‌آید؛ آن را در سینی پهن کنید تا بخارش برود و ته‌دیگ را جدا بگذارید.']],
 m:'chili-con-carne,chicken-enchiladas'});

R({id:'beef-burger',c:'main',min:30,sv:4,n:[610,35,32,38],app:'stove|grill',cu:'us',col:'#8A5A36',
 t:['Classic beef burger','همبرگر کلاسیک'],d:['Juicy seared beef patties in toasted buns with all the classic toppings.','همبرگر آبدار گوشت گوساله در نان برشته با همه‌ی مخلفات کلاسیک'],
 i:'ground meat:600:g;bread:4;tomato:1;onion:1;lettuce:::o;cheese:80:g:o;pickles:::o;ketchup:::o;mustard:::o;mayonnaise:::o;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[30,'Divide the meat into 4 and shape into patties about 1.5 cm thick and a little wider than the buns. Press a shallow dimple into the middle of each with your thumb and chill.','گوشت را ۴ قسمت کنید و به شکل همبرگرهایی به ضخامت حدود یک و نیم سانت و کمی پهن‌تر از نان درآورید. وسط هرکدام را با انگشت شست کمی گود کنید و در یخچال بگذارید.'],
  [20,'Slice the tomato and onion into rounds, wash the lettuce and split the buns.','گوجه و پیاز را حلقه‌ای ببرید، کاهو را بشویید و نان‌ها را از وسط باز کنید.'],
  [12,'Heat a heavy pan or grill until very hot and oil it lightly. Season the patties well with salt and pepper on both sides.','تابه‌ی سنگین یا گریل را خیلی داغ کنید و کمی چرب کنید. دو طرف همبرگرها را خوب نمک و فلفل بزنید.'],
  [10,'Cook the patties for 3–4 minutes without moving them until a dark crust forms, flip and cook 3–4 minutes more. Lay the cheese on top for the last minute and cover so it melts.','همبرگرها را ۳ تا ۴ دقیقه بدون جابه‌جا کردن بپزید تا رویه‌ی تیره‌ای بگیرند، برگردانید و ۳ تا ۴ دقیقه‌ی دیگر بپزید. دقیقه‌ی آخر پنیر را رویشان بگذارید و در تابه را ببندید تا آب شود.'],
  [3,'Toast the cut sides of the buns in the pan for a minute while the patties rest.','وقتی همبرگرها استراحت می‌کنند، سمت بریده‌ی نان‌ها را یک دقیقه در تابه برشته کنید.'],
  [0,'Spread the buns with the sauces and build with lettuce, patty, tomato, onion and pickles. Serve with fries.','نان‌ها را به سس آغشته کنید و کاهو، همبرگر، گوجه، پیاز و خیارشور را لایش بچینید. با سیب‌زمینی سرخ‌کرده سرو کنید.']],
 k:[['Pink juices pool on top and the patty feels soft and squishy when pressed.','A deep brown crust, clear juices and a springy centre when pressed (71 °C inside).','Shrunken, hard and grey all through with a burnt crust; add extra sauce and a slice of cheese to rescue it.'],
    ['روی همبرگر آب صورتی جمع شده و با فشار انگشت نرم و شل است.','رویه‌ی قهوه‌ای تیره دارد، آبش شفاف است و وسطش با فشار انگشت فنری است (دمای داخل ۷۱ درجه).','جمع شده، سفت و تا مغز خاکستری است و رویه‌اش سوخته؛ سس بیشتر و یک برش پنیر رویش بگذارید.']],
 m:'fried-potatoes'});

R({id:'mac-and-cheese',c:'main',min:35,sv:4,n:[730,32,68,36],app:'stove',cu:'us',col:'#F0B840',
 t:['Mac and cheese','مک اند چیز'],d:['Macaroni in a silky, rich cheese sauce — pure comfort food.','ماکارونی در سس پنیر لطیف و غلیظ؛ یک غذای دلچسب و آرامش‌بخش'],
 i:'pasta:300:g;cheese:250:g;milk:750:ml;butter:40:g;flour:3:tbsp;mustard:1:tsp:o;paprika::pinch:o;breadcrumbs:3:tbsp:o;salt::taste:s;black pepper::taste:s',
 s:[[35,'Put a big pot of salted water on to boil and grate the cheese.','یک قابلمه‌ی بزرگ آب و نمک روی گاز بگذارید تا جوش بیاید و پنیر را رنده کنید.'],
  [25,'Cook the macaroni for 1 minute less than the packet says, then drain. Meanwhile melt the butter in a saucepan, stir in the flour and cook for 1 minute.','ماکارونی را یک دقیقه کمتر از زمان روی بسته بپزید و آبکش کنید. در همین فاصله کره را در قابلمه‌ی کوچکی آب کنید، آرد را اضافه کنید و یک دقیقه هم بزنید.'],
  [20,'Whisk in the milk a little at a time, then simmer gently, whisking, for 5–6 minutes until it coats the back of a spoon.','شیر را کم‌کم اضافه کنید و مدام هم بزنید، بعد روی حرارت ملایم ۵ تا ۶ دقیقه بپزید و هم بزنید تا پشت قاشق را بپوشاند.'],
  [12,'Take off the heat and stir in the cheese, mustard, salt and pepper until smooth.','از روی حرارت بردارید و پنیر، خردل، نمک و فلفل را اضافه کنید و هم بزنید تا یکدست شود.'],
  [8,'Fold in the macaroni and stir over low heat for 2–3 minutes until hot and creamy. Toast the breadcrumbs in a dry pan until golden.','ماکارونی را اضافه کنید و روی حرارت ملایم ۲ تا ۳ دقیقه هم بزنید تا داغ و خامه‌ای شود. پودر سوخاری را در تابه‌ی خشک تفت دهید تا طلایی شود.'],
  [0,'Serve at once, sprinkled with paprika and the crisp breadcrumbs.','فوراً سرو کنید و رویش پاپریکا و پودر سوخاری برشته بپاشید.']],
 k:[['The sauce is thin like milk and runs straight off the spoon.','Smooth and glossy; it coats the back of a spoon and a finger drawn through leaves a clean line.','Grainy or stringy with oil separating because the cheese got too hot; take it off the heat and whisk in a splash of cold milk.'],
    ['سس مثل شیر رقیق است و فوراً از قاشق می‌ریزد.','سس یکدست و براق است، پشت قاشق را می‌پوشاند و وقتی انگشت رویش بکشید خط تمیزی می‌ماند.','سس دانه‌دانه یا کش‌دار شده و روغن انداخته چون پنیر زیادی داغ شده؛ از روی حرارت بردارید، کمی شیر سرد اضافه کنید و هم بزنید.']],
 m:'fried-chicken,bbq-chicken-wings'});

R({id:'fried-chicken',c:'main',min:75,sv:4,n:[720,48,34,43],app:'stove',cu:'us',col:'#B8752E',
 t:['Crispy fried chicken','مرغ سوخاری ترد'],d:['Juicy chicken in a crunchy, well-seasoned golden crust.','مرغ آبدار با پوسته‌ی طلایی، ترد و خوش‌ادویه'],
 i:'chicken:1.2:kg;flour:2:cup;yogurt:1:cup;milk:0.5:cup;cornstarch:0.5:cup;paprika:2:tsp;garlic:2:clove;baking powder:1:tsp:o;chili flakes:0.5:tsp:o;oil:1:l:s;salt:2:tsp:s;black pepper:1:tsp:s',
 s:[[75,'Mix the yogurt, milk, grated garlic, 1 tsp salt and half the paprika. Coat the chicken pieces in it and leave in the fridge for at least 30 minutes (or overnight).','ماست، شیر، سیر رنده‌شده، یک قاشق چای‌خوری نمک و نصف پاپریکا را مخلوط کنید. تکه‌های مرغ را در آن بخوابانید و دست‌کم ۳۰ دقیقه (یا یک شب) در یخچال بگذارید.'],
  [40,'In a wide bowl mix the flour, cornstarch, baking powder, the rest of the paprika, chili, pepper and 1 tsp salt. Heat the oil 4–5 cm deep in a heavy pot to 170 °C.','در کاسه‌ی پهنی آرد، نشاسته، بکینگ‌پودر، باقی پاپریکا، فلفل قرمز، فلفل سیاه و یک قاشق چای‌خوری نمک را مخلوط کنید. روغن را به عمق ۴ تا ۵ سانت در قابلمه‌ی سنگینی تا ۱۷۰ درجه داغ کنید.'],
  [35,'Lift the chicken from the marinade, let the excess drip off and press firmly into the flour to coat all over. Rest on a rack for 5 minutes.','مرغ را از مایه بیرون بیاورید، بگذارید اضافه‌اش بچکد و محکم در آرد بغلتانید تا همه‌جایش پوشیده شود. ۵ دقیقه روی توری بگذارید.'],
  [30,'Fry in two batches without crowding, 12–14 minutes each, turning now and then and keeping the oil at 160–170 °C.','در دو نوبت سرخ کنید و قابلمه را شلوغ نکنید؛ هر نوبت ۱۲ تا ۱۴ دقیقه، گاهی برگردانید و دمای روغن را بین ۱۶۰ تا ۱۷۰ درجه نگه دارید.'],
  [0,'Drain on a rack, sprinkle with salt right away and serve hot.','روی توری بگذارید تا روغنش برود، فوراً کمی نمک بپاشید و داغ سرو کنید.']],
 k:[['The crust is pale gold and the juices near the bone run pink when pierced.','Deep golden and crackly, the loud sizzle has quietened, and the juices run clear (74 °C in the thickest piece).','Dark brown and bitter-tasting with dry meat; lower the oil temperature for the next batch and serve with a dip.'],
    ['پوسته طلایی کم‌رنگ است و وقتی نزدیک استخوان را سوراخ کنید آبش صورتی است.','پوسته طلایی تیره و ترد است، صدای جلزوولز فروکش کرده و آبش شفاف است (دمای ضخیم‌ترین تکه ۷۴ درجه).','پوسته قهوه‌ای تیره و تلخ و گوشت خشک شده؛ برای نوبت بعد دمای روغن را پایین بیاورید و با سس سرو کنید.']],
 m:'mac-and-cheese,fried-potatoes'});

R({id:'beef-hot-dogs',c:'main',min:15,sv:4,n:[600,19,54,33],app:'stove|grill',cu:'us',col:'#B5533A',
 t:['Beef hot dogs','هات‌داگ گوشت گوساله'],d:['Browned beef franks in soft buns with sweet fried onions and mustard.','سوسیس گوساله‌ی برشته در نان نرم با پیاز داغ و خردل'],
 i:'sausage:8;bread:8;onion:2;pickles:::o;ketchup:::o;mustard:::o;oil:1:tbsp:s;salt::taste:s',
 s:[[15,'Thinly slice the onions and fry in the oil with a pinch of salt over medium heat, stirring, until soft and golden, about 10 minutes.','پیازها را نازک خلالی کنید و با کمی نمک در روغن روی حرارت متوسط حدود ۱۰ دقیقه تفت دهید و هم بزنید تا نرم و طلایی شود.'],
  [10,'Meanwhile score the beef sausages lightly and cook them in a pan or on the grill for 6–8 minutes, turning, until browned and hot through.','در همین فاصله روی سوسیس‌ها چند خط کم‌عمق بیندازید و در تابه یا روی گریل ۶ تا ۸ دقیقه بپزید و بچرخانید تا برشته و تا مغز داغ شوند.'],
  [2,'Split the buns and warm them in the pan for a minute.','نان‌ها را باز کنید و یک دقیقه در تابه گرم کنید.'],
  [0,'Tuck the sausages into the buns and top with the onions, pickles, ketchup and mustard.','سوسیس‌ها را لای نان بگذارید و رویش پیاز داغ، خیارشور، سس کچاپ و خردل بریزید.']],
 k:[['Still pale and smooth, and barely sizzling.','Browned all over, skins taut and lightly blistered, and piping hot in the middle.','Split open and shrivelled with charred ends; slice them and tuck them under plenty of onions.'],
    ['سوسیس هنوز رنگ‌پریده و صاف است و به‌زحمت جلز می‌کند.','همه‌جایش برشته شده، پوستش کشیده و کمی تاول‌زده است و وسطش حسابی داغ است.','سوسیس ترکیده، چروک شده و سرهایش سوخته؛ حلقه‌حلقه کنید و زیر مقدار زیادی پیاز داغ بگذارید.']],
 m:'fried-potatoes'});

R({id:'chicken-club-sandwich',c:'main',min:30,sv:2,n:[760,52,46,40],app:'stove',cu:'us',col:'#D9B27A',
 t:['Chicken club sandwich','کلاب ساندویچ مرغ'],d:['A triple-decker of golden chicken, egg, cheese and salad on toast.','ساندویچ سه‌طبقه با مرغ طلایی، تخم‌مرغ، پنیر، کاهو و گوجه روی نان تست'],
 i:'bread:6;chicken:300:g;tomato:1;lettuce;mayonnaise:3:tbsp;eggs:2::o;cheese:40:g:o;mustard:1:tsp:o;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[30,'Slice the chicken breast horizontally into thin cutlets and season with salt and pepper.','سینه‌ی مرغ را از پهنا به دو ورقه‌ی نازک ببرید و نمک و فلفل بزنید.'],
  [25,'Fry the chicken in half the oil over medium-high heat for 4–5 minutes a side until golden and cooked through. Rest, then slice.','مرغ را در نصف روغن روی حرارت نسبتاً زیاد هر طرف ۴ تا ۵ دقیقه سرخ کنید تا طلایی و کاملاً پخته شود. کمی صبر کنید و بعد برش بزنید.'],
  [14,'Fry the eggs in the rest of the oil, breaking the yolks so they cook flat. Slice the tomato and wash the lettuce.','تخم‌مرغ‌ها را در باقی روغن نیمرو کنید و زرده را بشکنید تا صاف بپزد. گوجه را حلقه‌ای ببرید و کاهو را بشویید.'],
  [8,'Toast the bread in the pan or a toaster until golden and spread with mayonnaise and mustard.','نان‌ها را در تابه یا توستر برشته کنید تا طلایی شوند و رویشان سس مایونز و خردل بمالید.'],
  [4,'Stack each sandwich: toast, lettuce, tomato and chicken; toast, cheese, egg and lettuce; then a final slice of toast. Press down lightly.','هر ساندویچ را این‌طور بچینید: نان، کاهو، گوجه و مرغ؛ نان، پنیر، تخم‌مرغ و کاهو؛ و در آخر یک نان دیگر. کمی فشار دهید.'],
  [0,'Hold together with toothpicks, cut into four triangles and serve.','با خلال دندان محکم کنید، به چهار مثلث ببرید و سرو کنید.']],
 k:[['Pink and glossy in the middle when you cut into the thickest part.','Golden outside, white and juicy right through, and the juices run clear.','Tough, dry and stringy; add an extra spread of mayonnaise when you build the sandwich.'],
    ['وقتی ضخیم‌ترین قسمت را می‌برید، وسطش صورتی و براق است.','بیرونش طلایی و داخلش تا مغز سفید و آبدار است و آبش شفاف است.','سفت، خشک و رشته‌رشته شده؛ موقع چیدن ساندویچ کمی سس مایونز بیشتر بزنید.']],
 m:'fried-potatoes'});

R({id:'chicken-caesar-salad',c:'salad',min:30,sv:4,n:[460,37,15,28],app:'stove',cu:'us',col:'#A9C46C',
 t:['Chicken Caesar salad','سالاد سزار با مرغ'],d:['Crisp lettuce, golden chicken and crunchy croutons in a creamy garlic-lemon dressing.','کاهوی ترد، مرغ طلایی و نان برشته با سس خامه‌ای سیر و لیمو'],
 i:'chicken:500:g;lettuce:1;bread:3;cheese:60:g;mayonnaise:4:tbsp;lemon:1;garlic:1:clove;mustard:1:tsp;oil:3:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[30,'Cut the bread into 2 cm cubes, toss with 1 tbsp oil and a pinch of salt and toast in a pan over medium heat, turning, for 6–8 minutes until golden and crunchy. Set aside.','نان را مکعب‌های ۲ سانتی ببرید، با یک قاشق روغن و کمی نمک مخلوط کنید و در تابه روی حرارت متوسط ۶ تا ۸ دقیقه تفت دهید و بچرخانید تا طلایی و ترد شود. کنار بگذارید.'],
  [22,'Flatten the chicken breasts a little, rub with 1 tbsp oil, salt and pepper and cook in the same pan for 5–6 minutes a side until golden and cooked through.','سینه‌های مرغ را کمی بکوبید تا صاف شوند، با یک قاشق روغن، نمک و فلفل آغشته کنید و در همان تابه هر طرف ۵ تا ۶ دقیقه بپزید تا طلایی و کاملاً پخته شوند.'],
  [16,'While the chicken cooks, whisk the mayonnaise with the grated garlic, lemon juice, mustard, half the grated cheese, the last 1 tbsp oil, 1–2 tbsp water and plenty of pepper.','در همین فاصله سس مایونز را با سیر رنده‌شده، آبلیمو، خردل، نصف پنیر رنده‌شده، باقی روغن، ۱ تا ۲ قاشق آب و مقدار زیادی فلفل سیاه هم بزنید.'],
  [8,'Let the chicken rest for 5 minutes, then slice it. Tear the lettuce into bite-sized pieces.','بگذارید مرغ ۵ دقیقه استراحت کند و بعد برش بزنید. کاهو را با دست به اندازه‌ی یک لقمه تکه کنید.'],
  [0,'Toss the lettuce with most of the dressing, top with the chicken, croutons and remaining cheese, drizzle over the rest of the dressing and serve at once.','کاهو را با بیشتر سس مخلوط کنید، مرغ، نان برشته و باقی پنیر را رویش بچینید، بقیه‌ی سس را رویش بریزید و فوراً سرو کنید.']],
 k:[['The croutons are still pale and give when squeezed.','Golden on all sides, they crunch loudly and rattle when you shake the pan.','Dark brown and smelling burnt; pick out the darkest ones and the rest will still be good.'],
    ['نان‌ها هنوز کم‌رنگ‌اند و با فشار دست نرم‌اند.','همه‌طرفشان طلایی شده، با صدا خرد می‌شوند و وقتی تابه را تکان می‌دهید صدای تق‌تق می‌دهند.','قهوه‌ای تیره شده و بوی سوختگی می‌دهد؛ تیره‌ترها را جدا کنید، بقیه هنوز خوب‌اند.']],
 m:'tomato-soup'});

R({id:'bbq-chicken-wings',c:'main',min:55,sv:4,n:[500,32,23,30],app:'oven|air fryer',cu:'us',col:'#8B3A1E',
 t:['BBQ chicken wings','بال مرغ باربیکیو'],d:['Crisp-skinned wings tossed in a sticky, sweet and smoky barbecue glaze.','بال مرغ با پوست ترد و سس باربیکیوی چسبناک، شیرین و دودی'],
 i:'chicken:1:kg;ketchup:0.5:cup;honey:3:tbsp;baking powder:1:tbsp;paprika:2:tsp;garlic:2:clove;vinegar:1:tbsp;soy sauce:1:tbsp;mustard:1:tsp:o;chili flakes::pinch:o;celery:::o;salt:1:tsp:s;black pepper::taste:s',
 s:[[55,'Heat the oven to 220 °C (air fryer to 200 °C). Pat the wings very dry and toss with the baking powder, salt, pepper and half the paprika.','فر را روی ۲۲۰ درجه (هواپز را روی ۲۰۰ درجه) روشن کنید. بال‌ها را کاملاً با دستمال خشک کنید و با بکینگ‌پودر، نمک، فلفل و نصف پاپریکا مخلوط کنید.'],
  [50,'Spread on a rack over a lined tray and bake for 40 minutes, turning halfway (air fryer: 22–25 minutes, shaking the basket halfway).','بال‌ها را روی توری بالای سینیِ کاغذ روغنی‌شده بچینید و ۴۰ دقیقه بپزید و وسط کار برگردانید (در هواپز ۲۲ تا ۲۵ دقیقه و وسط کار سبد را تکان دهید).'],
  [25,'Meanwhile whisk the ketchup, honey, vinegar, soy sauce, grated garlic, mustard, chili and the rest of the paprika into a smooth sauce.','در همین فاصله سس کچاپ، عسل، سرکه، سس سویا، سیر رنده‌شده، خردل، فلفل قرمز و باقی پاپریکا را هم بزنید تا سس یکدستی درست شود.'],
  [10,'Toss the hot wings in most of the sauce, spread them back on the tray and bake 6–8 minutes more until sticky and caramelised.','بال‌های داغ را با بیشتر سس مخلوط کنید، دوباره در سینی بچینید و ۶ تا ۸ دقیقه‌ی دیگر بپزید تا سس چسبناک و کاراملی شود.'],
  [0,'Brush with the remaining sauce and serve hot with celery sticks.','باقی سس را رویش بمالید و داغ با خلال کرفس سرو کنید.']],
 k:[['The skin is pale and soft with fat still bubbling under it, and the juices near the bone are pink.','The skin is crisp and deep golden, the glaze is sticky and caramelised at the edges, and the juices by the bone run clear.','The glaze has blackened at the tips and tastes bitter; brush on a little fresh sauce and serve.'],
    ['پوست رنگ‌پریده و نرم است، زیرش هنوز چربی قل می‌زند و آبِ نزدیک استخوان صورتی است.','پوست ترد و طلایی تیره است، سس چسبناک و لبه‌هایش کاراملی شده و آبِ کنار استخوان شفاف است.','سس سر بال‌ها سیاه و تلخ شده؛ کمی سس تازه رویش بمالید و سرو کنید.']],
 m:'mac-and-cheese,fried-potatoes'});

R({id:'brownies',c:'dessert',min:80,sv:16,n:[240,3,25,14],app:'oven,stove|microwave',cu:'us',col:'#4A2C1F',
 t:['Fudgy brownies','براونی شکلاتی'],d:['Dense, fudgy chocolate squares with a shiny, crackly top.','مربع‌های شکلاتی نرم و خیس با رویه‌ی براق و ترک‌خورده'],
 i:'chocolate:200:g;butter:150:g;eggs:3;flour:80:g;sugar:250:g:s;vanilla:1:tsp:o;walnuts:80:g:o;salt::pinch:s',
 s:[[80,'Heat the oven to 180 °C and line a 20 cm square tin with baking paper. Melt the chopped chocolate and butter together over very low heat (or in the microwave in short bursts), stir until smooth and let cool for 5 minutes.','فر را روی ۱۸۰ درجه روشن کنید و کف قالب مربع ۲۰ سانتی کاغذ روغنی بگذارید. شکلات خردشده و کره را با هم روی حرارت خیلی ملایم (یا در مایکروویو، چند ثانیه چند ثانیه) آب کنید، هم بزنید تا یکدست شود و بگذارید ۵ دقیقه خنک شود.'],
  [70,'Whisk the eggs, sugar and vanilla hard for 2–3 minutes until pale and thick, then whisk in the chocolate mixture.','تخم‌مرغ، شکر و وانیل را ۲ تا ۳ دقیقه محکم هم بزنید تا کم‌رنگ و غلیظ شود، بعد مخلوط شکلات را اضافه کنید و هم بزنید.'],
  [66,'Fold in the flour, salt and chopped walnuts just until no dry streaks remain, then pour into the tin and smooth the top.','آرد، نمک و گردوی خردشده را با لیسک آرام قاطی کنید، فقط تا جایی که ردِ آرد خشک نماند، بعد در قالب بریزید و رویش را صاف کنید.'],
  [63,'Bake for 22–25 minutes until the top is shiny and crackly and the centre has just set.','۲۲ تا ۲۵ دقیقه بپزید تا رویش براق و ترک‌خورده شود و وسطش تازه سفت شده باشد.'],
  [38,'Leave to cool in the tin for at least 35 minutes so the brownies firm up and turn fudgy.','بگذارید دست‌کم ۳۵ دقیقه در قالب خنک شود تا براونی جا بیفتد و نرم و خیس شود.'],
  [0,'Lift out with the paper and cut into 16 squares.','با کمک کاغذ از قالب دربیاورید و به ۱۶ مربع ببرید.']],
 k:[['A toothpick in the middle comes out wet with raw batter and the centre still wobbles.','Shiny, crackly top and set edges, and a toothpick in the middle comes out with a few moist, sticky crumbs.','The toothpick comes out clean and the edges are hard, so it is cakey, not fudgy; serve warm with a drizzle of melted chocolate or cream.'],
    ['خلال دندان را که وسطش فرو کنید با مایه‌ی خام خیس بیرون می‌آید و وسطش هنوز می‌لرزد.','رویش براق و ترک‌خورده است، لبه‌ها سفت شده و خلال دندان از وسط با چند خرده‌ی خیس و چسبناک بیرون می‌آید.','خلال دندان کاملاً تمیز بیرون می‌آید و لبه‌ها سفت شده، یعنی براونی کیکی شده نه خیس؛ گرم با کمی شکلات آب‌شده یا خامه سرو کنید.']],
 m:'shir-moz'});

R({id:'chocolate-chip-cookies',c:'dessert',min:45,sv:20,n:[205,2,27,10],app:'oven',cu:'us',col:'#C68A4E',
 t:['Chocolate chip cookies','کوکی چیپس شکلاتی'],d:['Golden-edged cookies with soft, chewy centres and melting chocolate chunks.','کوکی با لبه‌های طلایی، مغز نرم و تکه‌های شکلات آب‌شده'],
 i:'flour:280:g;butter:170:g;chocolate:200:g;eggs:1;baking powder:1:tsp;vanilla:1:tsp:o;sugar:200:g:s;salt:0.5:tsp:s',
 s:[[45,'Heat the oven to 180 °C and line two trays with baking paper. Beat the soft butter and sugar (half brown, if you have it) with a wooden spoon or mixer for 2–3 minutes until creamy.','فر را روی ۱۸۰ درجه روشن کنید و کف دو سینی کاغذ روغنی بگذارید. کره‌ی نرم و شکر (اگر دارید، نصفش شکر قهوه‌ای) را با قاشق چوبی یا همزن ۲ تا ۳ دقیقه بزنید تا کرمی شود.'],
  [40,'Beat in the egg and vanilla, then stir in the flour, baking powder and salt until just combined. Fold in the chopped chocolate.','تخم‌مرغ و وانیل را اضافه کنید و هم بزنید، بعد آرد، بکینگ‌پودر و نمک را فقط تا جایی قاطی کنید که یکدست شود. شکلات خردشده را اضافه کنید.'],
  [35,'Roll into balls of about 2 tbsp each and set them 5 cm apart on the trays.','خمیر را به اندازه‌ی حدود ۲ قاشق غذاخوری گلوله کنید و با فاصله‌ی ۵ سانت در سینی‌ها بچینید.'],
  [32,'Bake one tray at a time for 10–12 minutes until the edges are golden and the centres still look soft.','سینی‌ها را یکی‌یکی ۱۰ تا ۱۲ دقیقه بپزید تا لبه‌ها طلایی شوند و وسطشان هنوز نرم به نظر برسد.'],
  [8,'Leave on the tray for 5 minutes to firm up, then move to a rack.','۵ دقیقه در سینی بگذارید تا سفت شوند، بعد روی توری منتقل کنید.'],
  [0,'Serve warm or leave to cool completely.','گرم سرو کنید یا بگذارید کاملاً خنک شوند.']],
 k:[['Pale all over and still wet and glossy in the middle.','Golden edges and pale, puffy centres that look slightly underdone; they firm up as they cool and the kitchen smells of toffee.','Brown right across and already crisp out of the oven; still great dunked in milk, but take the next tray out 2 minutes sooner.'],
    ['همه‌جایش رنگ‌پریده است و وسطش هنوز خیس و براق است.','لبه‌ها طلایی و وسط کم‌رنگ و پف‌کرده و کمی نپخته به نظر می‌رسد؛ با خنک شدن سفت می‌شود و آشپزخانه بوی تافی می‌گیرد.','تا وسط قهوه‌ای شده و همان موقع بیرون آمدن از فر ترد است؛ باز هم با شیر خوشمزه است، ولی سینی بعدی را ۲ دقیقه زودتر دربیاورید.']],
 m:'shir-moz'});

R({id:'apple-pie',c:'dessert',min:150,sv:8,n:[450,5,61,21],app:'oven',cu:'us',col:'#C98B45',
 t:['Apple pie','پای سیب'],d:['Flaky butter pastry filled with tender cinnamon apples.','خمیر کره‌ای لایه‌لایه پر از سیب نرم و دارچینی'],
 i:'apple:1:kg;flour:300:g;butter:200:g;cinnamon:1.5:tsp;cornstarch:2:tbsp;lemon:1;eggs:1::o;cream:::o;sugar:130:g:s;salt::pinch:s',
 s:[[150,'For the pastry, rub the cold, cubed butter into the flour, 1 tbsp sugar and the salt with your fingertips until it looks like breadcrumbs. Add 6–8 tbsp ice-cold water, bring into a dough, divide into two discs, wrap and chill for 30 minutes.','برای خمیر، کره‌ی سرد و مکعبی‌شده را با آرد، یک قاشق شکر و نمک با نوک انگشتان بمالید تا شبیه پودر سوخاری شود. ۶ تا ۸ قاشق آب یخ اضافه کنید، خمیر را جمع کنید، دو قسمت کنید، به شکل دایره‌ی پهن درآورید، در سلفون بپیچید و ۳۰ دقیقه در یخچال بگذارید.'],
  [115,'Heat the oven to 200 °C. Peel, core and thinly slice the apples and toss with the rest of the sugar, the cinnamon, cornstarch and lemon juice.','فر را روی ۲۰۰ درجه روشن کنید. سیب‌ها را پوست بگیرید، هسته‌اش را دربیاورید، نازک برش بزنید و با باقی شکر، دارچین، نشاسته و آبلیمو مخلوط کنید.'],
  [105,'Roll out one disc and line a 23 cm pie dish, then pile in the apples. Roll out the second disc, lay it over, trim and crimp the edges, cut 4 slits in the top, brush with beaten egg and sprinkle with a little sugar.','یکی از خمیرها را باز کنید و کف و دیواره‌ی قالب پای ۲۳ سانتی را بپوشانید، بعد سیب‌ها را رویش بریزید. خمیر دوم را باز کنید و رویش بکشید، اضافه‌ی لبه‌ها را ببرید و لبه را با انگشت چین بدهید، روی پای ۴ شکاف بزنید، تخم‌مرغ زده بمالید و کمی شکر بپاشید.'],
  [95,'Bake for 20 minutes, then lower the oven to 180 °C and bake 30–35 minutes more until deep golden, with juices bubbling through the slits.','۲۰ دقیقه بپزید، بعد دمای فر را به ۱۸۰ درجه برسانید و ۳۰ تا ۳۵ دقیقه‌ی دیگر بپزید تا طلایی تیره شود و آب سیب از شکاف‌ها قل بزند.'],
  [40,'Cool on a rack for at least 40 minutes so the juices thicken.','دست‌کم ۴۰ دقیقه روی توری بگذارید تا خنک شود و آب سیب غلیظ شود.'],
  [0,'Slice and serve warm, with cream if you like.','برش بزنید و گرم سرو کنید؛ اگر دوست دارید با خامه.']],
 k:[['The crust is pale blond and the juice at the slits is thin and not yet bubbling.','A deep golden, flaky crust with thick, glossy juices bubbling slowly through the slits, and a knife slides easily into the apples.','The edges are dark brown and smell bitter; trim off the darkest bits, serve with cream, and cover the rim with foil next time.'],
    ['پوسته هنوز بور و کم‌رنگ است و آبِ کنار شکاف‌ها رقیق است و هنوز قل نمی‌زند.','پوسته طلایی تیره و پوسته‌پوسته است، آب غلیظ و براق آرام از شکاف‌ها قل می‌زند و چاقو راحت در سیب‌ها فرو می‌رود.','لبه‌ها قهوه‌ای تیره شده و بوی تلخی می‌دهد؛ قسمت‌های سوخته را جدا کنید، با خامه سرو کنید و دفعه‌ی بعد لبه را با فویل بپوشانید.']],
 m:'chai'});

R({id:'sushi-maki',c:'main',min:75,sv:4,n:[470,22,78,8],app:'stove|rice cooker',cu:'jp',col:'#39443A',
 t:['Sushi rolls (maki)','سوشی رول'],d:['Rolls of seasoned rice and nori filled with tuna, cucumber and avocado.','رول برنج طعم‌دار و جلبک نوری با تن ماهی، خیار و آووکادو'],
 i:'rice:2:cup;nori:6;tuna|fish:250:g;cucumber:1;avocado:1::o;vinegar:4:tbsp;sugar:2:tbsp:s;salt:1:tsp:s;mayonnaise:2:tbsp:o;soy sauce:4:tbsp;sesame:1:tbsp:o',
 s:[[75,'Rinse the short-grain rice in cold water, swirling and draining, until the water runs almost clear. Soak it in 500 ml fresh water for 15 minutes.','برنج دانه‌کوتاه را در آب سرد چند بار بشویید و آبکش کنید تا آبش تقریباً زلال شود. بعد ۱۵ دقیقه در ۵۰۰ میلی‌لیتر آب تازه خیس کنید.'],
  [60,'Bring the rice and its water to the boil, cover and cook on the lowest heat for 13 minutes (or use the rice cooker). Turn off the heat and leave it covered for 10 minutes.','برنج را با همان آب روی حرارت بگذارید تا جوش بیاید، درش را بگذارید و روی کمترین حرارت ۱۳ دقیقه بپزید (یا در پلوپز بپزید). بعد زیرش را خاموش کنید و ۱۰ دقیقه با در بسته دم بکشد.'],
  [50,'Meanwhile cut the cucumber into long thin strips. Drain the tuna (or flake cooked fish) and mix it with the mayonnaise.','در این فاصله خیار را خلال‌های بلند و باریک کنید. آب تن ماهی را بگیرید (یا ماهی پخته را ریش‌ریش کنید) و با سس مایونز مخلوط کنید.'],
  [37,'Warm the vinegar, sugar and salt until dissolved. Tip the rice into a wide bowl, pour over the vinegar mix and fold it in gently with a spatula while fanning it, until glossy and at room temperature.','سرکه، شکر و نمک را گرم کنید تا حل شوند. برنج را در ظرف پهنی بریزید، مخلوط سرکه را رویش بریزید و با کفگیر آرام زیر و رو کنید و هم‌زمان باد بزنید تا براق شود و به دمای اتاق برسد.'],
  [22,'Slice the avocado. Lay a nori sheet shiny side down on a bamboo mat or cling film and, with wet hands, spread a thin layer of rice over it, leaving 2 cm bare at the top. Lay a line of fillings near you, roll up tightly and seal the edge with a dab of water.','آووکادو را ورقه‌ای کنید. ورق نوری را از طرف براقش رو به پایین روی حصیر سوشی یا سلفون بگذارید و با دست خیس لایه‌ی نازکی برنج رویش پهن کنید و ۲ سانت از لبه‌ی بالا را خالی بگذارید. مواد را در یک ردیف نزدیک خودتان بچینید، محکم لوله کنید و لبه را با کمی آب بچسبانید.'],
  [0,'Slice each roll into 8 pieces with a wet, sharp knife and serve with soy sauce and sesame.','هر رول را با چاقوی تیز و خیس ۸ تکه کنید و با سس سویا و کنجد سرو کنید.']],
 k:[['The grains are still chalky in the middle and the rice looks wet and loose.','Each grain is tender but whole and glossy, smells gently of vinegar and sticks together when pressed.','Soft and pasty, and the rolls tear; spread a thinner layer and roll more gently.'],
    ['وسط دانه‌ها هنوز سفت است و برنج خیس و از هم وارفته به نظر می‌رسد.','هر دانه نرم ولی سالم و براق است، بوی ملایم سرکه می‌دهد و با فشار دست به هم می‌چسبد.','برنج نرم و خمیری شده و رول پاره می‌شود؛ لایه‌ی نازک‌تری پهن کنید و آرام‌تر لوله کنید.']],
 m:'tamagoyaki'});

R({id:'chicken-teriyaki',c:'main',min:30,sv:4,n:[340,34,12,17],app:'stove',cu:'jp',col:'#8A4B22',
 t:['Chicken teriyaki','مرغ تریاکی'],d:['Pan-seared chicken thighs in a glossy soy and ginger glaze.','ران مرغ سرخ‌شده در سس براق سویا و زنجبیل'],
 i:'chicken:700:g;soy sauce:4:tbsp;sugar:2:tbsp:s;honey:1:tbsp:o;vinegar:1:tbsp;ginger:1:tsp;garlic:2:clove;cornstarch:1:tsp:o;sesame:1:tsp:o;green onion:2::o;oil:1:tbsp:s',
 s:[[30,'Pat the boneless chicken thighs dry. Mix the soy sauce, sugar, honey, vinegar, grated ginger, crushed garlic and 3 tbsp water.','ران‌های بی‌استخوان مرغ را با دستمال خشک کنید. سس سویا، شکر، عسل، سرکه، زنجبیل رنده‌شده، سیر له‌شده و ۳ قاشق آب را مخلوط کنید.'],
  [22,'Heat the oil in a large pan and lay in the chicken, skin side down if it has skin. Cook over medium-high heat until deep golden, about 6 minutes.','روغن را در تابه‌ی بزرگی داغ کنید و مرغ‌ها را (اگر پوست دارند، از طرف پوست) در تابه بچینید. روی حرارت نسبتاً زیاد حدود ۶ دقیقه بپزید تا طلایی پررنگ شود.'],
  [15,'Turn and cook 5 minutes more, then wipe out most of the fat with kitchen paper.','برگردانید و ۵ دقیقه‌ی دیگر بپزید، بعد بیشتر چربی تابه را با دستمال کاغذی بگیرید.'],
  [9,'Pour in the sauce (with the cornstarch mixed into 1 tbsp water if you like it thicker) and simmer, turning the chicken often, until the sauce is sticky and coats it, 4–5 minutes.','سس را در تابه بریزید (اگر سس غلیظ‌تر دوست دارید، نشاسته را در ۱ قاشق آب حل کنید و اضافه کنید) و بگذارید بجوشد؛ مرغ را مدام برگردانید تا سس چسبناک شود و رویش را بپوشاند؛ ۴ تا ۵ دقیقه.'],
  [3,'Rest the chicken for 2 minutes, then slice it.','مرغ را ۲ دقیقه استراحت دهید و بعد ورقه‌ای ببرید.'],
  [0,'Spoon over the glaze, scatter with sesame and sliced green onion, and serve with rice.','سس را رویش بریزید، کنجد و پیازچه‌ی خردشده بپاشید و با برنج سرو کنید.']],
 k:[['The sauce is thin and runny and slides off the chicken.','The glaze is glossy and syrupy, coats the back of a spoon, and the chicken juices run clear.','The sauce is dark, tacky and smells burnt; add 2 tbsp water and take it off the heat.'],
    ['سس رقیق و آبکی است و از روی مرغ سُر می‌خورد.','سس براق و شیره‌ای شده، پشت قاشق را می‌پوشاند و آب مرغ شفاف است.','سس تیره و خیلی چسبناک شده و بوی سوختگی می‌دهد؛ ۲ قاشق آب اضافه کنید و از روی حرارت بردارید.']],
 m:'kateh,tamagoyaki'});

R({id:'chicken-ramen',c:'soup',min:60,sv:4,n:[620,42,74,17],app:'stove',cu:'jp',col:'#D9A85E',
 t:['Chicken ramen','رامن مرغ'],d:['Noodles in a rich ginger-garlic chicken broth with a jammy egg.','نودل در آب‌مرغ پرمایه با زنجبیل و سیر و تخم‌مرغ عسلی'],
 i:'noodles:400:g;chicken:600:g;eggs:4;onion:1;garlic:4:clove;ginger:30:g;soy sauce:5:tbsp;green onion:4;spinach:100:g:o;corn:0.5:cup:o;nori:2::o;sesame:1:tbsp:o;chili flakes::pinch:o;sugar:1:tsp:s;salt::taste:s;oil:1:tbsp:s',
 s:[[60,'Brown the chicken thighs in the oil in a large pot, 3 minutes a side. Add the halved onion, crushed garlic, sliced ginger and 2 litres of water.','ران‌های مرغ را در قابلمه‌ی بزرگ با روغن هر طرف ۳ دقیقه سرخ کنید. پیاز نصف‌شده، سیر له‌شده، زنجبیل ورقه‌ای و ۲ لیتر آب را اضافه کنید.'],
  [52,'Bring to the boil, skim off the foam, then simmer gently, half covered, for 35 minutes.','بگذارید جوش بیاید، کف رویش را بگیرید و بعد با در نیمه‌باز روی حرارت ملایم ۳۵ دقیقه بجوشد.'],
  [40,'Meanwhile boil the eggs for 6½ minutes, cool them in cold water and peel.','در این فاصله تخم‌مرغ‌ها را ۶ و نیم دقیقه بجوشانید، در آب سرد خنک کنید و پوست بگیرید.'],
  [15,'Lift out the chicken and shred or slice it. Strain the broth, stir in the soy sauce and sugar, season with salt and keep it hot.','مرغ را بیرون بیاورید و ریش‌ریش یا ورقه‌ای کنید. آب‌مرغ را صاف کنید، سس سویا و شکر را اضافه کنید، نمکش را تنظیم کنید و داغ نگه دارید.'],
  [8,'Cook the noodles in a separate pot of boiling water as the packet says (usually 3–4 minutes), adding the spinach for the last 30 seconds. Drain well.','نودل را در قابلمه‌ی جداگانه با آب جوش طبق دستور روی بسته بپزید (معمولاً ۳ تا ۴ دقیقه) و ۳۰ ثانیه‌ی آخر اسفناج را هم اضافه کنید. خوب آبکش کنید.'],
  [0,'Divide the noodles between deep bowls, pour over the hot broth and top with the chicken, halved eggs, corn, green onion, nori, sesame and chili.','نودل را در کاسه‌های گود تقسیم کنید، آب‌مرغ داغ را رویش بریزید و مرغ، تخم‌مرغ نصف‌شده، ذرت، پیازچه، نوری، کنجد و فلفل را رویش بچینید.']],
 k:[['The egg white is still loose and see-through near the yolk.','The white is just set and the yolk is deep orange and jammy, like thick honey.','The yolk is pale, dry and crumbly with a grey-green ring; next time take the eggs out a minute sooner.'],
    ['سفیده نزدیک زرده هنوز شل و شفاف است.','سفیده تازه بسته و زرده نارنجی پررنگ و غلیظ مثل عسل است.','زرده کم‌رنگ، خشک و پودری شده و دورش حلقه‌ی خاکستری دارد؛ دفعه‌ی بعد تخم‌مرغ‌ها را یک دقیقه زودتر بردارید.']],
 m:'chicken-dumplings'});

R({id:'onigiri',c:'rice',min:50,sv:4,n:[440,16,80,6],app:'stove|rice cooker',cu:'jp',col:'#EEEAE0',
 t:['Onigiri (rice balls)','اونیگیری (توپک برنج ژاپنی)'],d:['Hand-shaped rice triangles with a tuna-mayo filling and a strip of nori.','برنج مثلثی‌شکل با مغز تن ماهی و مایونز، پیچیده در نوار نوری'],
 i:'rice:2:cup;nori:2;tuna|fish:150:g;mayonnaise:2:tbsp;soy sauce:1:tsp:o;sesame:1:tbsp:o;salt:1:tsp:s',
 s:[[50,'Rinse the short-grain rice until the water runs almost clear, then soak it in 500 ml fresh water for 10 minutes.','برنج دانه‌کوتاه را بشویید تا آبش تقریباً زلال شود و بعد ۱۰ دقیقه در ۵۰۰ میلی‌لیتر آب تازه خیس کنید.'],
  [40,'Bring to the boil, cover and cook on the lowest heat for 13 minutes (or use the rice cooker), then leave covered off the heat for 10 minutes.','بگذارید جوش بیاید، درش را بگذارید و روی کمترین حرارت ۱۳ دقیقه بپزید (یا در پلوپز)، بعد زیرش را خاموش کنید و ۱۰ دقیقه با در بسته دم بکشد.'],
  [30,'Meanwhile drain the tuna and mix it with the mayonnaise and soy sauce. Cut each nori sheet into 4 strips.','در این فاصله آب تن ماهی را بگیرید و با مایونز و سس سویا مخلوط کنید. هر ورق نوری را به ۴ نوار ببرید.'],
  [15,'Spread the rice in a bowl for a few minutes until cool enough to handle. Wet your hands, rub them with a pinch of salt and take a handful of rice.','برنج را چند دقیقه در ظرفی پهن کنید تا آن‌قدر خنک شود که بشود با دست کار کرد. دست‌هایتان را خیس کنید، کمی نمک به کف دست بمالید و یک مشت برنج بردارید.'],
  [12,'Press a dip in the middle, add a spoonful of filling, cover with a little more rice and press firmly into a triangle, turning it in your cupped hands. Make 8.','وسط برنج را با انگشت گود کنید، یک قاشق از مواد را داخلش بگذارید، کمی برنج رویش بگذارید و با کف دست‌های نیمه‌بسته محکم فشار دهید و بچرخانید تا مثلثی شود. ۸ عدد درست کنید.'],
  [0,'Wrap a nori strip around the base of each one, sprinkle with sesame and eat soon, while the nori is crisp.','دور پایین هر مثلث یک نوار نوری بپیچید، کنجد بپاشید و زود بخورید تا نوری ترد بماند.']],
 k:[['The ball crumbles and falls apart as soon as you let go.','It holds a neat triangle, feels firm but not hard, and you can still see the separate grains.','Squashed into a dense, gluey lump; press more gently with wetter hands.'],
    ['تا دستتان را برمی‌دارید، توپک وا می‌رود و از هم می‌پاشد.','شکل مثلثی مرتبی دارد، سفت است ولی نه سنگ، و دانه‌های برنج هنوز جدا پیداست.','له و فشرده و مثل خمیر چسبناک شده؛ با دست خیس‌تر و آرام‌تر فشار دهید.']],
 m:'tamagoyaki'});

R({id:'chicken-katsu',c:'main',min:35,sv:4,n:[490,40,36,20],app:'stove',cu:'jp',col:'#C98A3C',
 t:['Chicken katsu','چیکن کاتسو'],d:['Crisp crumbed chicken cutlets with a tangy katsu sauce.','شنیسل مرغ ترد با پودر سوخاری و سس کاتسوی ملس'],
 i:'chicken:600:g;flour:50:g;eggs:2;breadcrumbs:120:g;cabbage:0.25::o;lemon:1::o;ketchup:4:tbsp;soy sauce:2:tbsp;sugar:1:tbsp:s;mustard:1:tsp:o;oil:250:ml:s;salt::taste:s;black pepper::taste:s',
 s:[[35,'Slice the chicken breasts in half horizontally and pound them to an even 1 cm thickness. Season with salt and pepper.','سینه‌های مرغ را از پهنا دو نیم کنید و با گوشت‌کوب بکوبید تا همه‌جا ۱ سانت ضخامت داشته باشد. نمک و فلفل بزنید.'],
  [27,'Set out three plates: flour, beaten eggs and breadcrumbs (panko if you have it). Coat each piece in flour, dip in egg, then press firmly into the crumbs.','سه بشقاب آماده کنید: آرد، تخم‌مرغ هم‌زده و پودر سوخاری (اگر پانکو دارید، بهتر). هر تکه را اول در آرد بغلتانید، بعد در تخم‌مرغ بزنید و آخر محکم در پودر سوخاری فشار دهید.'],
  [22,'Mix the ketchup, soy sauce, sugar and mustard for the sauce, and finely shred the cabbage.','برای سس، کچاپ، سس سویا، شکر و خردل را مخلوط کنید و کلم را خیلی نازک خلالی کنید.'],
  [18,'Heat 1 cm of oil in a frying pan to 170°C — a crumb should sizzle at once. Fry the cutlets in batches, 3–4 minutes a side, until deep golden.','به اندازه‌ی ۱ سانت روغن در تابه بریزید و تا ۱۷۰ درجه داغ کنید؛ یک ذره پودر سوخاری باید فوراً جلز و ولز کند. شنیسل‌ها را چندتا چندتا، هر طرف ۳ تا ۴ دقیقه، سرخ کنید تا طلایی پررنگ شوند.'],
  [3,'Drain on a rack or kitchen paper for 2 minutes, then slice into strips.','۲ دقیقه روی توری یا دستمال کاغذی بگذارید تا روغنش گرفته شود و بعد نواری ببرید.'],
  [0,'Serve with the shredded cabbage and a lemon wedge, with the sauce drizzled over.','با کلم خلالی و یک تکه لیمو سرو کنید و سس را رویش بریزید.']],
 k:[['The crust is pale and soft, and the centre is pink when you cut in.','Deep golden and crackly all over, it sounds hollow when tapped, and the centre is white and juicy.','Dark brown and bitter-smelling, with dry meat; lower the heat for the next batch.'],
    ['پوسته کم‌رنگ و نرم است و وقتی می‌برید، وسطش صورتی است.','همه‌جا طلایی پررنگ و ترد است، با ضربه صدای توخالی می‌دهد و وسطش سفید و آبدار است.','قهوه‌ای تیره شده، بوی تلخی می‌دهد و گوشت خشک است؛ برای دسته‌ی بعد حرارت را کم کنید.']],
 m:'kateh'});

R({id:'kung-pao-chicken',c:'main',min:30,sv:4,n:[430,36,14,26],app:'stove',cu:'cn',col:'#A63D1E',
 t:['Kung pao chicken','مرغ کونگ پائو'],d:['Spicy stir-fried chicken with peanuts, chili and a sweet-sour glaze.','مرغ تند تفت‌داده با بادام‌زمینی، فلفل تند و سس ترش و شیرین'],
 i:'chicken:600:g;peanuts:60:g;chili:4;chili flakes::pinch:o;garlic:3:clove;ginger:1:tsp;green onion:4;bell pepper:1::o;soy sauce:4:tbsp;vinegar:2:tbsp;sugar:1:tbsp:s;cornstarch:2:tsp;sesame:1:tsp:o;oil:3:tbsp:s',
 s:[[30,'Cut the chicken into 2 cm cubes and toss with 1 tbsp soy sauce and 1 tsp cornstarch. Leave for 10 minutes.','مرغ را مکعب‌های ۲ سانتی خرد کنید و با ۱ قاشق سس سویا و ۱ قاشق چای‌خوری نشاسته مخلوط کنید. ۱۰ دقیقه بماند.'],
  [20,'Mix the sauce: the rest of the soy sauce and cornstarch, the vinegar, sugar and 3 tbsp water. Cut the chilies (dried or fresh) into short pieces, slice the garlic, grate the ginger, chop the green onions and dice the pepper.','سس را آماده کنید: باقی سس سویا و نشاسته، سرکه، شکر و ۳ قاشق آب را مخلوط کنید. فلفل‌های تند (خشک یا تازه) را تکه‌های کوتاه ببرید، سیر را ورقه‌ای کنید، زنجبیل را رنده کنید، پیازچه را خرد و فلفل دلمه‌ای را نگینی کنید.'],
  [12,'Toast the peanuts in a dry wok until golden, about 3 minutes, and set aside.','بادام‌زمینی را در ووک یا تابه‌ی خشک حدود ۳ دقیقه تفت دهید تا طلایی شود و کنار بگذارید.'],
  [9,'Heat the oil until very hot, add the chilies and chili flakes for 20 seconds, then the chicken. Stir-fry until white all over and lightly browned, 4–5 minutes.','روغن را خیلی داغ کنید، فلفل‌ها و پول بیبر را ۲۰ ثانیه تفت دهید و بعد مرغ را اضافه کنید. با هم زدن مداوم ۴ تا ۵ دقیقه تفت دهید تا همه‌جا سفید و کمی طلایی شود.'],
  [4,'Add the garlic, ginger, pepper and green onion for 1 minute, then pour in the sauce and toss until thick and glossy. Stir in the peanuts and sesame oil.','سیر، زنجبیل، فلفل دلمه‌ای و پیازچه را اضافه کنید و ۱ دقیقه تفت دهید، بعد سس را بریزید و هم بزنید تا غلیظ و براق شود. بادام‌زمینی و روغن کنجد را اضافه کنید.'],
  [0,'Serve straight away with rice.','فوراً با برنج سرو کنید.']],
 k:[['The chicken is still pink inside and the sauce is thin and cloudy.','The chicken is white through and juicy, the sauce clings in a glossy coat and the chilies smell toasty.','The chilies have turned black and smell acrid and the chicken is chewy; pick out the burnt chilies and serve at once.'],
    ['وسط مرغ هنوز صورتی است و سس رقیق و کدر است.','مرغ تا وسط سفید و آبدار است، سس براق به آن چسبیده و فلفل‌ها بوی برشته می‌دهند.','فلفل‌ها سیاه شده و بوی تند سوختگی می‌دهند و مرغ سفت شده؛ فلفل‌های سوخته را بردارید و فوراً سرو کنید.']],
 m:'egg-fried-rice,egg-drop-soup'});

R({id:'sweet-sour-chicken',c:'main',min:40,sv:4,n:[450,34,38,17],app:'stove',cu:'cn',col:'#D9542B',
 t:['Sweet and sour chicken','مرغ ترش و شیرین'],d:['Crisp chicken and peppers tossed in a bright, tangy red sauce.','مرغ ترد و فلفل دلمه‌ای در سس قرمز ترش و شیرین'],
 i:'chicken:600:g;cornstarch:6:tbsp;eggs:1;bell pepper:2;onion:1;carrot:1::o;garlic:2:clove;ketchup:4:tbsp;vinegar:3:tbsp;sugar:3:tbsp:s;soy sauce:1:tbsp;orange:1::o;oil:200:ml:s;salt::taste:s',
 s:[[40,'Cut the chicken into 2–3 cm pieces, season with salt and toss with the beaten egg, then with 5 tbsp cornstarch until every piece is coated.','مرغ را تکه‌های ۲ تا ۳ سانتی ببرید، نمک بزنید و با تخم‌مرغ هم‌زده مخلوط کنید، بعد ۵ قاشق نشاسته رویش بریزید و هم بزنید تا همه‌ی تکه‌ها پوشیده شوند.'],
  [32,'Cut the peppers and onion into squares and the carrot into thin slices. Mix the ketchup, vinegar, sugar, soy sauce, the orange juice (or 4 tbsp water) and the last 1 tbsp cornstarch.','فلفل‌ها و پیاز را مربعی و هویج را حلقه‌های نازک خرد کنید. کچاپ، سرکه، شکر، سس سویا، آب پرتقال (یا ۴ قاشق آب) و ۱ قاشق نشاسته‌ی باقی‌مانده را مخلوط کنید.'],
  [25,'Heat 1–2 cm of oil in a pan and fry the chicken in batches, turning, until golden and crisp, 5–6 minutes a batch. Drain on kitchen paper.','۱ تا ۲ سانت روغن در تابه داغ کنید و مرغ را چندتا چندتا سرخ کنید و برگردانید تا طلایی و ترد شود؛ هر دسته ۵ تا ۶ دقیقه. روی دستمال کاغذی بگذارید.'],
  [8,'Pour off all but 1 tbsp oil. Stir-fry the onion, carrot, peppers and garlic over high heat for 3 minutes, keeping them crunchy.','جز ۱ قاشق، باقی روغن را خالی کنید. پیاز، هویج، فلفل‌ها و سیر را روی حرارت زیاد ۳ دقیقه تفت دهید تا هنوز ترد بمانند.'],
  [3,'Pour in the sauce and bubble until thick and glossy, about 1 minute, then toss in the chicken until coated.','سس را بریزید و بگذارید حدود ۱ دقیقه بجوشد تا غلیظ و براق شود، بعد مرغ را اضافه کنید و هم بزنید تا سس همه‌جایش را بگیرد.'],
  [0,'Serve at once with rice, while the coating is still crisp.','فوراً با برنج سرو کنید تا پوسته‌ی مرغ هنوز ترد باشد.']],
 k:[['The coating is pale and soft, and the pieces feel squishy in the tongs.','Golden and crisp, they rustle in the pan, and the chicken is white and juicy inside.','Dark and hard outside, with dry, stringy meat; use a lower heat and smaller batches.'],
    ['پوسته کم‌رنگ و نرم است و تکه‌ها زیر انبر وا می‌روند.','طلایی و ترد است، در تابه خش‌خش می‌کند و داخل مرغ سفید و آبدار است.','بیرونش تیره و سفت شده و گوشت خشک و رشته‌رشته است؛ حرارت را کمتر و دسته‌ها را کوچک‌تر کنید.']],
 m:'egg-fried-rice'});

R({id:'chicken-chow-mein',c:'main',min:30,sv:4,n:[510,36,66,13],app:'stove',cu:'cn',col:'#B07A3A',
 t:['Chicken chow mein','چائومین مرغ'],d:['Stir-fried noodles with chicken, cabbage and carrot in a savoury soy sauce.','نودل تفت‌داده با مرغ، کلم و هویج در سس سویا'],
 i:'noodles:300:g;chicken:400:g;cabbage:0.25;carrot:1;green onion:4;bell pepper:1::o;mushrooms:150:g:o;garlic:3:clove;ginger:1:tsp;soy sauce:5:tbsp;sugar:1:tsp:s;cornstarch:1:tsp;sesame:1:tsp:o;oil:3:tbsp:s;black pepper::taste:s',
 s:[[30,'Slice the chicken into thin strips and toss with 1 tbsp soy sauce and the cornstarch. Shred the cabbage, cut the carrot and pepper into matchsticks, and slice the mushrooms and green onions.','مرغ را نواری نازک ببرید و با ۱ قاشق سس سویا و نشاسته مخلوط کنید. کلم را خلالی، هویج و فلفل دلمه‌ای را خلال باریک، و قارچ و پیازچه را ورقه‌ای کنید.'],
  [20,'Cook the egg noodles in boiling water for 1 minute less than the packet says. Drain, rinse under cold water and toss with the sesame oil.','نودل را در آب جوش یک دقیقه کمتر از زمان روی بسته بپزید. آبکش کنید، زیر آب سرد بگیرید و با روغن کنجد مخلوط کنید.'],
  [14,'Heat 2 tbsp oil in a wok until just smoking and stir-fry the chicken until golden, about 4 minutes. Lift it out.','۲ قاشق روغن را در ووک یا تابه‌ی بزرگ آن‌قدر داغ کنید که کمی دود کند و مرغ را حدود ۴ دقیقه تفت دهید تا طلایی شود. بیرون بیاورید.'],
  [9,'Add the last of the oil, the garlic and ginger, then the vegetables, and stir-fry over high heat for 3 minutes.','باقی روغن، سیر و زنجبیل را بریزید، بعد سبزیجات را اضافه کنید و روی حرارت زیاد ۳ دقیقه تفت دهید.'],
  [5,'Add the noodles, chicken, remaining soy sauce, sugar and pepper and toss with tongs for 2–3 minutes until hot and evenly coloured.','نودل، مرغ، باقی سس سویا، شکر و فلفل را اضافه کنید و با انبر ۲ تا ۳ دقیقه زیر و رو کنید تا داغ شود و رنگش یکدست شود.'],
  [0,'Scatter with the green onions and serve hot.','پیازچه را رویش بپاشید و داغ سرو کنید.']],
 k:[['The noodles look pale and wet and stick together in clumps.','Every strand is glossy, evenly brown and separate, with a few toasty edges, and the vegetables still crunch.','The noodles are dry, brittle and catching on the pan; splash in 2 tbsp water and toss.'],
    ['نودل‌ها کم‌رنگ و خیس‌اند و گلوله‌گلوله به هم چسبیده‌اند.','همه‌ی رشته‌ها براق، یکدست قهوه‌ای و جدا از هم‌اند، جاهایی کمی برشته شده‌اند و سبزیجات هنوز ترد است.','نودل خشک و شکننده شده و به تابه می‌چسبد؛ ۲ قاشق آب بریزید و هم بزنید.']],
 m:'egg-drop-soup,chicken-dumplings'});

R({id:'chicken-dumplings',c:'main',min:90,sv:4,n:[540,30,62,19],app:'stove',cu:'cn',col:'#E3CFA2',
 t:['Chicken dumplings (gyoza)','دامپلینگ مرغ (گیوزا)'],d:['Homemade dumplings with a juicy chicken and cabbage filling, crisp on the bottom.','دامپلینگ خانگی با مغز مرغ و کلم، با کف ترد و طلایی'],
 i:'flour:300:g;chicken:400:g;cabbage:0.25;green onion:4;ginger:1:tsp;garlic:2:clove;soy sauce:4:tbsp;sesame:1:tbsp:o;vinegar:2:tbsp;chili flakes::pinch:o;salt:1:tsp:s;black pepper::taste:s;oil:2:tbsp:s',
 s:[[90,'Mix the flour with 160 ml just-boiled water and a pinch of salt, then knead for 5 minutes into a smooth, soft dough. Cover and rest for 30 minutes.','آرد را با ۱۶۰ میلی‌لیتر آب تازه جوش‌آمده و کمی نمک مخلوط کنید و ۵ دقیقه ورز دهید تا خمیر نرم و صافی شود. رویش را بپوشانید و ۳۰ دقیقه استراحت دهید.'],
  [80,'Meanwhile finely chop the cabbage, sprinkle with ½ tsp salt and leave 10 minutes, then squeeze out the water. Mince the chicken finely with a knife and mix it with the cabbage, green onion, ginger, garlic, 2 tbsp soy sauce, the sesame oil and pepper.','در این فاصله کلم را ریز خرد کنید، نیم قاشق چای‌خوری نمک بزنید و ۱۰ دقیقه بگذارید بماند، بعد آبش را خوب بگیرید. مرغ را با چاقو خیلی ریز خرد کنید و با کلم، پیازچه، زنجبیل، سیر، ۲ قاشق سس سویا، روغن کنجد و فلفل مخلوط کنید.'],
  [55,'Roll the dough into a log, cut it into 32 pieces and roll each into a thin 8 cm circle. Put a teaspoon of filling in the middle, fold in half and pinch the edges shut, pleating one side.','خمیر را لوله‌ای کنید، ۳۲ تکه ببرید و هر تکه را به شکل دایره‌ی نازک ۸ سانتی باز کنید. یک قاشق چای‌خوری از مواد را وسطش بگذارید، از وسط تا کنید و لبه‌ها را محکم به هم بچسبانید و یک طرف را چین بدهید.'],
  [22,'Heat 1 tbsp oil in a non-stick pan with a lid and set in half the dumplings, flat side down. Fry for 2 minutes until the bottoms are golden.','۱ قاشق روغن را در تابه‌ی نچسب درداری داغ کنید و نصف دامپلینگ‌ها را از طرف صاف در تابه بچینید. ۲ دقیقه سرخ کنید تا کفشان طلایی شود.'],
  [20,'Pour in 100 ml water, cover at once and steam for 7 minutes. Uncover and cook until the water is gone and the bottoms crisp up again. Repeat with the rest.','۱۰۰ میلی‌لیتر آب در تابه بریزید، فوراً درش را بگذارید و ۷ دقیقه بخارپز کنید. در را بردارید و بگذارید آب کاملاً تبخیر شود و کفشان دوباره ترد شود. باقی دامپلینگ‌ها را هم همین‌طور بپزید.'],
  [0,'Serve hot with a dip of the remaining soy sauce mixed with the vinegar and chili flakes.','داغ سرو کنید، همراه با سسی از باقی سس سویا، سرکه و پول بیبر.']],
 k:[['The wrappers look white and doughy and the bottoms are pale.','The wrappers are translucent and tender, the bottoms deep golden and crisp, and the filling is firm with clear juices.','The bottoms are dark and stuck to the pan; add a splash of water, cover for 1 minute and lift them off with a spatula.'],
    ['خمیر هنوز سفید و خام به نظر می‌رسد و کف دامپلینگ‌ها کم‌رنگ است.','خمیر نیمه‌شفاف و نرم شده، کفشان طلایی پررنگ و ترد است و مواد داخل سفت شده و آبش شفاف است.','کفشان تیره شده و به تابه چسبیده؛ کمی آب بریزید، ۱ دقیقه در را بگذارید و با کفگیر جدا کنید.']],
 m:'egg-drop-soup'});

R({id:'egg-drop-soup',c:'soup',min:35,sv:4,n:[170,20,9,7],app:'stove',cu:'cn',col:'#EFD36A',
 t:['Egg drop soup','سوپ تخم‌مرغ چینی'],d:['Silky ribbons of egg in a light ginger and chicken broth.','رشته‌های لطیف تخم‌مرغ در آب‌مرغ سبک با زنجبیل'],
 i:'eggs:3;chicken:250:g;ginger:10:g;green onion:3;cornstarch:2:tbsp;soy sauce:2:tbsp;corn:0.5:cup:o;sesame:1:tsp:o;salt::taste:s;black pepper::taste:s',
 s:[[35,'Put the chicken, sliced ginger and the white parts of the green onions in a pot with 1.2 litres of water. Bring to the boil, skim, and simmer gently for 15 minutes.','مرغ، زنجبیل ورقه‌ای و قسمت سفید پیازچه‌ها را با ۱٫۲ لیتر آب در قابلمه بریزید. بگذارید جوش بیاید، کفش را بگیرید و روی حرارت ملایم ۱۵ دقیقه بجوشد.'],
  [14,'Lift out the chicken and shred it finely; discard the ginger and onion. Return the chicken to the pot with the corn, soy sauce, salt and pepper.','مرغ را بیرون بیاورید و ریز ریش‌ریش کنید؛ زنجبیل و پیازچه را دور بریزید. مرغ را با ذرت، سس سویا، نمک و فلفل به قابلمه برگردانید.'],
  [8,'Mix the cornstarch with 4 tbsp cold water, stir it into the simmering soup and cook for 2 minutes until slightly thickened.','نشاسته را در ۴ قاشق آب سرد حل کنید، به سوپ در حال جوش اضافه کنید و ۲ دقیقه هم بزنید تا کمی غلیظ شود.'],
  [4,'Beat the eggs. Stir the soup in one direction to make a whirlpool, then slowly pour in the eggs in a thin stream. Wait 10 seconds, then stir gently once.','تخم‌مرغ‌ها را هم بزنید. سوپ را در یک جهت هم بزنید تا گرداب درست شود، بعد تخم‌مرغ را آرام و به شکل رشته‌ای باریک در سوپ بریزید. ۱۰ ثانیه صبر کنید و بعد یک بار آرام هم بزنید.'],
  [0,'Turn off the heat, drizzle with sesame oil, scatter with the sliced green onion tops and serve.','زیرش را خاموش کنید، کمی روغن کنجد رویش بریزید، سبزی پیازچه‌ی خردشده را بپاشید و سرو کنید.']],
 k:[['The egg clouds the soup and has not set into strands yet.','Soft, silky yellow ribbons float through a slightly thickened, glossy broth.','The egg has broken into small rubbery bits; next time pour more slowly and stir less.'],
    ['تخم‌مرغ سوپ را کدر کرده و هنوز رشته‌رشته نشده.','رشته‌های زرد، نرم و لطیف در آب‌مرغ براق و کمی غلیظ شناورند.','تخم‌مرغ تکه‌تکه و لاستیکی شده؛ دفعه‌ی بعد آرام‌تر بریزید و کمتر هم بزنید.']],
 m:'egg-fried-rice,chicken-dumplings'});

R({id:'beef-bulgogi',c:'main',min:50,sv:4,n:[400,38,16,20],app:'stove|grill',cu:'kr',col:'#6B3A22',
 t:['Beef bulgogi','بولگوگی گوشت'],d:['Thin slices of sweet, garlicky marinated beef, seared until caramelised.','ورقه‌های نازک گوشت مزه‌دارشده با سیر و سویا، سرخ و کاراملی'],
 i:'beef:600:g;soy sauce:5:tbsp;sugar:2:tbsp:s;apple:0.5;garlic:4:clove;ginger:1:tsp;sesame:1:tbsp;onion:1;green onion:3;carrot:1::o;lettuce:::o;black pepper::taste:s;oil:1:tbsp:s',
 s:[[50,'Put the beef (sirloin or rib-eye) in the freezer for 15 minutes to firm up. Meanwhile grate the apple and mix it with the soy sauce, sugar, crushed garlic, grated ginger, sesame oil, pepper and 2 tbsp water.','گوشت (راسته یا فیله) را ۱۵ دقیقه در فریزر بگذارید تا کمی سفت شود. در این فاصله سیب را رنده کنید و با سس سویا، شکر، سیر له‌شده، زنجبیل رنده‌شده، روغن کنجد، فلفل سیاه و ۲ قاشق آب مخلوط کنید.'],
  [35,'Slice the beef across the grain as thinly as you can. Toss it with the marinade, the thinly sliced onion and carrot and half the green onions, and leave for at least 20 minutes.','گوشت را در خلاف جهت رگه‌ها تا جایی که می‌توانید نازک ورقه‌ای کنید. با سس، پیاز نازک‌خردشده، هویج خلالی و نصف پیازچه‌ها مخلوط کنید و دست‌کم ۲۰ دقیقه بگذارید بماند.'],
  [12,'Heat a heavy pan or grill until very hot with a little oil. Cook the beef in batches in a single layer, 2–3 minutes, turning once, until browned with crisp edges.','تابه‌ی سنگین یا گریل را با کمی روغن خیلی داغ کنید. گوشت را چند دسته و در یک لایه ۲ تا ۳ دقیقه بپزید و یک بار برگردانید تا قهوه‌ای شود و لبه‌هایش برشته شود.'],
  [0,'Pile onto a plate, scatter with the remaining green onion and some sesame seeds, and serve with rice and lettuce leaves for wrapping.','گوشت را در دیس بریزید، باقی پیازچه و کمی کنجد رویش بپاشید و با برنج و برگ کاهو برای لقمه گرفتن سرو کنید.']],
 k:[['The beef is grey and stewing in its juices, with no browning.','The slices are browned and glossy with caramelised, slightly crisp edges, and smell sweet and garlicky.','The meat is dark, dry and chewy and the sugar smells burnt; cook smaller batches for less time.'],
    ['گوشت خاکستری است و در آب خودش می‌جوشد و هیچ جایش قهوه‌ای نشده.','ورقه‌ها قهوه‌ای و براق‌اند، لبه‌هایشان کاراملی و کمی ترد است و بوی شیرین سیر می‌دهند.','گوشت تیره، خشک و سفت شده و شکرش بوی سوختگی می‌دهد؛ دسته‌ها را کوچک‌تر و زمان پخت را کوتاه‌تر کنید.']],
 m:'kateh,steamed-egg'});

R({id:'bibimbap',c:'rice',min:50,sv:4,n:[620,28,76,22],app:'stove',cu:'kr',col:'#C8552E',
 t:['Bibimbap','بیبیمباپ'],d:['A bowl of rice topped with seasoned vegetables, beef, a fried egg and chili sauce.','کاسه‌ی برنج با سبزیجات مزه‌دار، گوشت، تخم‌مرغ نیمرو و سس تند'],
 i:'rice:1.5:cup;beef|ground meat:250:g;eggs:4;spinach:200:g;carrot:1;zucchini:1;mushrooms:150:g:o;cucumber:1::o;garlic:3:clove;soy sauce:4:tbsp;sesame:2:tbsp;chili flakes|paprika:1:tbsp;honey|sugar:1:tbsp;vinegar:1:tsp;oil:3:tbsp:s;salt::taste:s',
 s:[[50,'Rinse the rice and cook it in 450 ml water: bring to the boil, cover and cook on the lowest heat for 15 minutes, then rest for 10. Marinate the beef strips (or mince) in 2 tbsp soy sauce, 1 crushed garlic clove and 1 tsp sesame oil.','برنج را بشویید و با ۴۵۰ میلی‌لیتر آب بپزید: بگذارید جوش بیاید، درش را بگذارید و روی کمترین حرارت ۱۵ دقیقه بپزد و بعد ۱۰ دقیقه دم بکشد. گوشت نواری (یا چرخ‌کرده) را با ۲ قاشق سس سویا، ۱ حبه سیر له‌شده و ۱ قاشق چای‌خوری روغن کنجد مزه‌دار کنید.'],
  [40,'Make the sauce: mix the chili flakes (or paprika for a milder one), honey, 1 tbsp soy sauce, 1 tbsp sesame oil, the vinegar and 1 tbsp water. Cut the carrot, zucchini and cucumber into matchsticks and slice the mushrooms.','برای سس، پول بیبر (یا پاپریکا برای سس ملایم‌تر)، عسل، ۱ قاشق سس سویا، ۱ قاشق روغن کنجد، سرکه و ۱ قاشق آب را مخلوط کنید. هویج، کدو و خیار را خلال باریک و قارچ را ورقه‌ای کنید.'],
  [30,'Blanch the spinach in boiling water for 30 seconds, squeeze it dry and toss with a little salt, garlic and sesame oil. Stir-fry the carrot, zucchini and mushrooms one at a time in a little oil with a pinch of salt and garlic, 2 minutes each, keeping them in separate piles.','اسفناج را ۳۰ ثانیه در آب جوش بگذارید، آبش را خوب بگیرید و با کمی نمک، سیر و روغن کنجد مخلوط کنید. هویج، کدو و قارچ را جداجدا در تابه با کمی روغن، نمک و سیر هر کدام ۲ دقیقه تفت دهید و جدا از هم کنار بگذارید.'],
  [14,'Fry the beef in the same pan over high heat until browned, about 4 minutes.','گوشت را در همان تابه روی حرارت زیاد حدود ۴ دقیقه تفت دهید تا قهوه‌ای شود.'],
  [7,'Fry the eggs in a little oil until the whites are set and the edges lacy, with the yolks still runny.','تخم‌مرغ‌ها را با کمی روغن نیمرو کنید تا سفیده ببندد و لبه‌هایش توری و ترد شود ولی زرده هنوز شل بماند.'],
  [0,'Put rice in each bowl, arrange the vegetables and beef in sections on top, add an egg in the middle and a spoonful of sauce. Mix everything together at the table.','در هر کاسه برنج بریزید، سبزیجات و گوشت را دسته‌دسته رویش بچینید، تخم‌مرغ را وسط بگذارید و یک قاشق سس رویش بریزید. سر میز همه را با هم مخلوط کنید.']],
 k:[['The egg white is still clear and jelly-like around the yolk.','The white is fully set with crisp, lacy edges, and the yolk is bright and still runny.','The yolk is firm and pale; it still tastes good — add an extra spoon of sauce so the bowl isn’t dry.'],
    ['سفیده دور زرده هنوز شفاف و ژله‌ای است.','سفیده کامل بسته، لبه‌هایش توری و ترد است و زرده براق و هنوز شل است.','زرده سفت و کم‌رنگ شده؛ باز هم خوشمزه است، فقط یک قاشق سس بیشتر بریزید تا کاسه خشک نباشد.']],
 m:'steamed-egg'});

R({id:'chicken-pad-thai',c:'main',min:35,sv:4,n:[560,34,62,20],app:'stove',cu:'th',col:'#D39A52',
 t:['Chicken pad thai','پد تای مرغ'],d:['Rice noodles stir-fried with chicken, egg and peanuts in a sweet-sour sauce.','نودل برنجی تفت‌داده با مرغ، تخم‌مرغ و بادام‌زمینی در سس ترش و شیرین'],
 i:'noodles:250:g;chicken:400:g;eggs:2;peanuts:50:g;green onion:4;garlic:3:clove;lemon:2;soy sauce:4:tbsp;vinegar:2:tbsp;sugar:2:tbsp:s;tofu:150:g:o;chili flakes::pinch:o;coriander:0.5:bunch:o;oil:3:tbsp:s',
 s:[[35,'Soak the flat rice noodles in warm water for 15–20 minutes until bendy but still firm, then drain.','نودل برنجی پهن را ۱۵ تا ۲۰ دقیقه در آب ولرم خیس کنید تا نرم و خم‌شو ولی هنوز کمی سفت باشد، بعد آبکش کنید.'],
  [30,'Mix the sauce: soy sauce, vinegar, sugar and the juice of 1 lemon. Slice the chicken thinly, cube the tofu, crush the garlic, cut the green onions into 3 cm lengths and roughly chop the peanuts.','برای سس، سس سویا، سرکه، شکر و آب ۱ لیمو را مخلوط کنید. مرغ را نازک ورقه‌ای کنید، توفو را مکعبی خرد کنید، سیر را له کنید، پیازچه را تکه‌های ۳ سانتی ببرید و بادام‌زمینی را درشت بکوبید.'],
  [14,'Heat 2 tbsp oil in a wok over high heat. Stir-fry the chicken and tofu for 4 minutes until golden, add the garlic for 30 seconds, then push everything to one side.','۲ قاشق روغن را در ووک یا تابه‌ی بزرگ روی حرارت زیاد داغ کنید. مرغ و توفو را ۴ دقیقه تفت دهید تا طلایی شوند، سیر را اضافه کنید و ۳۰ ثانیه تفت دهید، بعد همه را به یک طرف تابه ببرید.'],
  [9,'Add the last of the oil to the empty side, crack in the eggs and scramble until just set.','باقی روغن را در طرف خالی تابه بریزید، تخم‌مرغ‌ها را بشکنید و هم بزنید تا تازه ببندد.'],
  [7,'Add the noodles and sauce and toss for 3–4 minutes until the noodles are soft and have soaked up the sauce. Toss in the green onions and half the peanuts.','نودل و سس را اضافه کنید و ۳ تا ۴ دقیقه زیر و رو کنید تا نودل نرم شود و سس را به خودش بگیرد. پیازچه و نصف بادام‌زمینی را اضافه کنید.'],
  [0,'Serve topped with the remaining peanuts, coriander, chili flakes and lemon wedges.','باقی بادام‌زمینی، گشنیز، پول بیبر و قاچ‌های لیمو را رویش بریزید و سرو کنید.']],
 k:[['The noodles are still stiff and white in the middle and the pan looks wet.','The noodles are soft, chewy and glossy, evenly tan, and the pan is almost dry.','The noodles have gone mushy and are breaking up in clumps; stop tossing and serve straight away.'],
    ['نودل هنوز سفت است، وسطش سفید مانده و تابه خیس است.','نودل نرم، کش‌دار و براق و یکدست قهوه‌ای روشن شده و تابه تقریباً خشک است.','نودل له شده و تکه‌تکه به هم چسبیده؛ دیگر هم نزنید و فوراً سرو کنید.']],
 m:'fresh-spring-rolls'});

R({id:'thai-chicken-curry',c:'main',min:40,sv:4,n:[470,31,11,33],app:'stove',cu:'th',col:'#E1A93E',
 t:['Thai coconut chicken curry','کاری مرغ تایلندی با شیر نارگیل'],d:['Tender chicken in a creamy, fragrant coconut sauce with ginger and chili.','مرغ نرم در سس خامه‌ای و معطر شیر نارگیل با زنجبیل و فلفل تند'],
 i:'chicken:600:g;coconut milk:400:ml;curry powder:2:tbsp;ginger:20:g;garlic:4:clove;chili:2;onion:1;bell pepper:1::o;basil:0.5:bunch:o;coriander:0.5:bunch:o;lemon:1;soy sauce:1:tbsp;sugar:1:tsp:s;turmeric:0.5:tsp:s;oil:2:tbsp:s;salt::taste:s',
 s:[[40,'Cut the chicken (thighs are best) into bite-size pieces. Slice the onion and pepper, and grate or finely chop the ginger, garlic and chili.','مرغ (ران بهتر است) را تکه‌های لقمه‌ای ببرید. پیاز و فلفل دلمه‌ای را خلالی کنید و زنجبیل، سیر و فلفل تند را رنده یا ریز خرد کنید.'],
  [32,'Fry the onion in the oil for 5 minutes until soft. Add the ginger, garlic, chili, curry powder and turmeric and stir for 1 minute until fragrant.','پیاز را ۵ دقیقه در روغن تفت دهید تا نرم شود. زنجبیل، سیر، فلفل تند، پودر کاری و زردچوبه را اضافه کنید و ۱ دقیقه هم بزنید تا عطرش بلند شود.'],
  [26,'Stir in 3 tbsp of the thick coconut cream from the top of the can and fry for 1 minute, then add the chicken and turn to coat.','۳ قاشق از خامه‌ی غلیظ روی قوطی شیر نارگیل را اضافه کنید و ۱ دقیقه تفت دهید، بعد مرغ را اضافه کنید و هم بزنید تا به ادویه آغشته شود.'],
  [23,'Pour in the rest of the coconut milk, the soy sauce, sugar and 100 ml water. Simmer gently, uncovered, for 15 minutes, adding the pepper for the last 5.','باقی شیر نارگیل، سس سویا، شکر و ۱۰۰ میلی‌لیتر آب را اضافه کنید. بدون در، روی حرارت ملایم ۱۵ دقیقه بجوشد و ۵ دقیقه‌ی آخر فلفل دلمه‌ای را اضافه کنید.'],
  [5,'Squeeze in the lemon juice, season with salt and stir in the torn basil leaves.','آب لیمو را بریزید، نمکش را تنظیم کنید و برگ‌های ریحان را با دست ریز کنید و اضافه کنید.'],
  [0,'Scatter with coriander and serve with rice.','گشنیز رویش بپاشید و با برنج سرو کنید.']],
 k:[['The sauce is thin and pale and the chicken is still pink in the middle.','The sauce is creamy and golden with tiny beads of oil on top, and the chicken is tender and white through.','The sauce has split into oily curds or is catching on the bottom; take it off the heat and stir in a splash of water.'],
    ['سس رقیق و کم‌رنگ است و وسط مرغ هنوز صورتی است.','سس خامه‌ای و طلایی است، دانه‌های ریز روغن رویش پیدا شده و مرغ نرم و تا وسط سفید است.','سس بریده و روغنی شده یا ته گرفته؛ از روی حرارت بردارید، کمی آب اضافه کنید و هم بزنید.']],
 m:'kateh'});

R({id:'thai-basil-chicken',c:'main',min:20,sv:4,n:[400,35,9,25],app:'stove',cu:'th',col:'#7A5C33',
 t:['Thai basil chicken','مرغ ریحان تایلندی'],d:['Minced chicken stir-fried with garlic, chili and plenty of basil, topped with a crispy egg.','مرغ ریزشده تفت‌داده با سیر، فلفل تند و ریحان فراوان، با تخم‌مرغ نیمروی ترد'],
 i:'chicken:600:g;basil:1:bunch;garlic:5:clove;chili:3;onion:1::o;green beans:100:g:o;soy sauce:3:tbsp;sugar:2:tsp:s;eggs:4::o;oil:4:tbsp:s',
 s:[[20,'Chop the chicken thighs finely with a knife, or use minced chicken. Pound or finely chop the garlic and chili together. Slice the onion and cut the green beans into short pieces.','ران مرغ را با چاقو ریز خرد کنید یا از مرغ چرخ‌کرده استفاده کنید. سیر و فلفل تند را با هم بکوبید یا ریز خرد کنید. پیاز را خلالی و لوبیا سبز را تکه‌های کوتاه ببرید.'],
  [13,'Fry the eggs one at a time in 2 tbsp very hot oil, spooning the oil over, until the edges are brown and crispy and the yolk is still soft. Set aside.','تخم‌مرغ‌ها را یکی‌یکی در ۲ قاشق روغن خیلی داغ نیمرو کنید و روغن را با قاشق رویشان بریزید تا لبه‌ها قهوه‌ای و ترد شود و زرده هنوز نرم بماند. کنار بگذارید.'],
  [7,'Heat the remaining oil in a wok, add the garlic and chili for 20 seconds, then the chicken, onion and beans. Stir-fry over high heat for 4–5 minutes, breaking up the meat.','باقی روغن را در ووک یا تابه داغ کنید، سیر و فلفل را ۲۰ ثانیه تفت دهید، بعد مرغ، پیاز و لوبیا سبز را اضافه کنید. روی حرارت زیاد ۴ تا ۵ دقیقه تفت دهید و گوشت را با قاشق از هم باز کنید.'],
  [2,'Add the soy sauce, sugar and 2 tbsp water and toss, then turn off the heat and stir in the basil leaves until just wilted.','سس سویا، شکر و ۲ قاشق آب را اضافه کنید و هم بزنید، بعد زیرش را خاموش کنید و برگ‌های ریحان را اضافه کنید و هم بزنید تا تازه پلاسیده شوند.'],
  [0,'Serve over rice with a crispy fried egg on top.','روی برنج بکشید و یک تخم‌مرغ نیمروی ترد رویش بگذارید.']],
 k:[['The chicken is still pink and watery and the basil is not in yet.','The chicken is cooked through with browned bits, the sauce just coats it, and the basil is bright green, freshly wilted and smells peppery.','The basil is black and slimy and the chicken dry; stir in a handful of fresh leaves and a splash of water.'],
    ['مرغ هنوز صورتی و آبکی است و ریحان هنوز اضافه نشده.','مرغ کامل پخته و جاهایی قهوه‌ای شده، سس فقط رویش را پوشانده و ریحان سبز روشن و تازه پلاسیده است و عطر تندی دارد.','ریحان سیاه و لزج و مرغ خشک شده؛ یک مشت برگ تازه و کمی آب اضافه کنید و هم بزنید.']],
 m:'kateh'});

R({id:'beef-pho',c:'soup',min:145,sv:4,n:[530,38,64,13],app:'stove',cu:'vn',col:'#C9A26B',
 t:['Beef pho','فو گوشت (سوپ ویتنامی)'],d:['Fragrant spiced beef broth poured over rice noodles, with fresh herbs and lemon.','آب‌گوشت معطر و ادویه‌دار روی نودل برنجی، با سبزی تازه و لیمو'],
 i:'beef:700:g;noodles:300:g;onion:2;ginger:40:g;cinnamon:1;cardamom:4;soy sauce:3:tbsp;sugar:1:tbsp:s;salt::taste:s;black pepper:1:tsp:s;green onion:3;coriander:1:bunch;basil:0.5:bunch:o;mint:0.5:bunch:o;lemon:2;chili:2::o',
 s:[[145,'Halve the onions and cut the ginger into thick slices, skin on. Char them in a dry pan or straight over the gas flame until blackened in spots, about 8 minutes.','پیازها را از وسط نصف کنید و زنجبیل را با پوست ورقه‌های ضخیم ببرید. آن‌ها را در تابه‌ی خشک یا مستقیم روی شعله‌ی گاز حدود ۸ دقیقه بگذارید تا جاهایی سیاه شوند.'],
  [135,'Toast the cinnamon stick, cardamom pods and whole peppercorns in a large pot for 1 minute. Add the beef (brisket or shank, in one or two large pieces), the charred onion and ginger, and 2.5 litres of water.','چوب دارچین، هل و دانه‌های فلفل سیاه را ۱ دقیقه در قابلمه‌ی بزرگ تفت دهید. گوشت (ماهیچه یا سردست، یکی دو تکه‌ی بزرگ)، پیاز و زنجبیل کبابی و ۲٫۵ لیتر آب را اضافه کنید.'],
  [130,'Bring to the boil, skim off all the foam, then simmer very gently, half covered, for about 1½ hours until the beef is tender.','بگذارید جوش بیاید، کف رویش را کامل بگیرید و بعد با در نیمه‌باز روی حرارت خیلی ملایم حدود یک ساعت و نیم بجوشد تا گوشت نرم شود.'],
  [25,'Lift out the beef and slice it thinly across the grain. Strain the broth, season it with the soy sauce, sugar and salt, and keep it at a gentle boil.','گوشت را بیرون بیاورید و در خلاف جهت رگه‌ها نازک ورقه‌ای کنید. آب گوشت را صاف کنید، با سس سویا، شکر و نمک مزه‌دار کنید و بگذارید آرام بجوشد.'],
  [12,'Soak or cook the rice noodles as the packet says, drain and divide between large bowls. Slice the green onions and chili, pick the herb leaves and cut the lemons into wedges.','نودل برنجی را طبق دستور روی بسته خیس یا آب‌پز کنید، آبکش کنید و در کاسه‌های بزرگ تقسیم کنید. پیازچه و فلفل تند را خرد کنید، برگ سبزی‌ها را جدا کنید و لیموها را قاچ کنید.'],
  [0,'Top the noodles with the beef and green onion, ladle over the boiling broth and serve with the herbs, chili and lemon for everyone to add at the table.','گوشت و پیازچه را روی نودل بچینید، آب گوشت جوشان را رویش بریزید و سبزی، فلفل و لیمو را کنارش بگذارید تا هر کس سر میز خودش اضافه کند.']],
 k:[['The beef resists a fork and the broth tastes thin and watery.','A fork slides easily into the beef, and the broth is clear and amber and smells warmly of cinnamon and ginger.','The beef falls into shreds and the broth has gone cloudy from boiling hard; strain it again and serve the beef shredded.'],
    ['چنگال به‌سختی در گوشت فرو می‌رود و آب گوشت بی‌مزه و آبکی است.','چنگال راحت در گوشت فرو می‌رود و آب گوشت زلال و کهربایی است و بوی گرم دارچین و زنجبیل می‌دهد.','گوشت ریش‌ریش شده و آب گوشت از جوشیدن تند کدر شده؛ دوباره صافش کنید و گوشت را ریش‌ریش سرو کنید.']],
 m:'fresh-spring-rolls'});

R({id:'fresh-spring-rolls',c:'side',min:40,sv:4,n:[340,18,56,6],app:'stove',cu:'vn',col:'#DDE8CC',
 t:['Fresh spring rolls','اسپرینگ رول تازه (رول ویتنامی)'],d:['Soft rice-paper rolls packed with shrimp, noodles, crunchy vegetables and herbs.','رول‌های نرم رایس‌پیپر پر از میگو، نودل، سبزیجات ترد و سبزی تازه'],
 i:'noodles:100:g;shrimp|chicken:250:g;lettuce:1;cucumber:1;carrot:1;mint:0.5:bunch;coriander:0.5:bunch;basil:0.5:bunch:o;peanuts:40:g;soy sauce:3:tbsp;lemon:1;sugar:1:tbsp:s;garlic:1:clove;chili:1::o',
 s:[[40,'Cook the peeled shrimp in simmering water for 2–3 minutes until pink (or poach a chicken breast for 15 minutes), cool, and halve lengthways or cut into strips.','میگوی پوست‌کنده را ۲ تا ۳ دقیقه در آب در حال جوش بپزید تا صورتی شود (یا سینه‌ی مرغ را ۱۵ دقیقه آب‌پز کنید)، خنک کنید و از طول نصف یا نواری ببرید.'],
  [32,'Cook the rice vermicelli as the packet says (usually 3–4 minutes), rinse under cold water and drain well. Cut the cucumber and carrot into thin matchsticks and pick the herb leaves.','رشته‌ی برنجی (ورمیشل) را طبق دستور روی بسته بپزید (معمولاً ۳ تا ۴ دقیقه)، زیر آب سرد بگیرید و خوب آبکش کنید. خیار و هویج را خلال باریک کنید و برگ سبزی‌ها را جدا کنید.'],
  [22,'Make the dip: mix the soy sauce, lemon juice, sugar, crushed garlic, sliced chili and 3 tbsp water. Toast and roughly chop the peanuts.','برای سس، سس سویا، آب لیمو، شکر، سیر له‌شده، فلفل تند خردشده و ۳ قاشق آب را مخلوط کنید. بادام‌زمینی را تفت دهید و درشت خرد کنید.'],
  [17,'Dip a rice-paper sheet in warm water for 5 seconds and lay it on a damp board. Put a lettuce leaf, some noodles, vegetables and herbs on the lower third, add the shrimp, fold in the sides and roll up tightly. Make 12. No rice paper? Wrap the filling in large lettuce leaves.','یک ورق رایس‌پیپر را ۵ ثانیه در آب ولرم فرو کنید و روی تخته‌ی مرطوب پهن کنید. یک برگ کاهو، کمی نودل، سبزیجات و سبزی را روی یک‌سوم پایین ورق بگذارید، میگو را اضافه کنید، دو طرف را تا کنید و محکم لوله کنید. ۱۲ عدد درست کنید. اگر رایس‌پیپر ندارید، مواد را لای برگ‌های بزرگ کاهو بپیچید.'],
  [0,'Serve right away with the dip, with the peanuts scattered over it.','فوراً با سس سرو کنید و بادام‌زمینی را روی سس بپاشید.']],
 k:[['The rice paper is still stiff and cracks when you fold it.','The sheet is soft, pliable and slightly tacky, and the finished roll is tight and see-through, showing the shrimp.','The sheet is limp, sticky and tears; dip the next one for just 2–3 seconds — it keeps softening on the board.'],
    ['رایس‌پیپر هنوز خشک است و موقع تا کردن ترک می‌خورد.','ورق نرم، انعطاف‌پذیر و کمی چسبناک است و رول آماده سفت و نیمه‌شفاف است و میگو از پشتش پیداست.','ورق شل و چسبناک شده و پاره می‌شود؛ ورق بعدی را فقط ۲ تا ۳ ثانیه در آب بزنید، روی تخته خودش نرم‌تر می‌شود.']],
 m:'beef-pho,chicken-pad-thai'});

R({id:'butter-chicken',c:'main',min:60,sv:4,n:[560,40,14,38],app:'stove',cu:'in',col:'#D9722F',
 t:['Butter chicken','باتر چیکن'],d:['Yogurt-marinated chicken in a silky tomato, butter and cream sauce.','مرغ خوابانده در ماست با سس لطیف گوجه، کره و خامه'],
 i:'chicken:700:g;yogurt:0.5:cup;tomato:5;butter:50:g;cream:150:ml;garlic:4:clove;ginger:1:tbsp;curry powder:2:tsp;paprika:2:tsp;cumin:1:tsp;cardamom:3::o;cinnamon::pinch:o;chili flakes::pinch:o;fenugreek:1:tbsp:o;coriander:::o;sugar:1:tsp:s;oil:1:tbsp:s;salt::taste:s',
 s:[[60,'Cut the chicken into bite-size pieces and mix with the yogurt, half the garlic and ginger, 1 tsp curry powder, 1 tsp paprika and a good pinch of salt. Leave for 30 minutes.','مرغ را لقمه‌ای خرد کنید و با ماست، نصف سیر و زنجبیل، یک قاشق چای‌خوری پودر کاری، یک قاشق چای‌خوری پاپریکا و کمی نمک مخلوط کنید. ۳۰ دقیقه بگذارید بماند.'],
  [30,'Brown the chicken in the oil in a wide pan over high heat, 2–3 minutes a side — it doesn’t need to cook through. Lift it out.','مرغ را در تابه‌ی پهن با روغن، روی حرارت زیاد هر طرف ۲ تا ۳ دقیقه سرخ کنید؛ لازم نیست کامل بپزد. مرغ را بردارید.'],
  [25,'Melt the butter in the same pan, add the rest of the garlic and ginger, the cumin, cardamom, cinnamon, chili and remaining spices and stir for a minute. Add the grated tomatoes and simmer until thick and glossy, about 10 minutes.','کره را در همان تابه آب کنید، باقی سیر و زنجبیل، زیره، هل، دارچین، فلفل و بقیه‌ی ادویه‌ها را اضافه کنید و یک دقیقه هم بزنید. گوجه‌ی رنده‌شده را بریزید و حدود ۱۰ دقیقه بپزید تا غلیظ و براق شود.'],
  [14,'For a restaurant-smooth sauce, blend it now. Return the chicken with its juices and simmer gently for 10 minutes, until cooked through.','اگر سس کاملاً یکدست می‌خواهید، حالا آن را با گوشکوب برقی بزنید. مرغ را با آبش به تابه برگردانید و ۱۰ دقیقه روی حرارت ملایم بپزید تا کامل پخته شود.'],
  [4,'Crumble the dried fenugreek between your palms and stir it in with the cream and sugar; warm through without boiling. Taste for salt.','شنبلیله‌ی خشک را کف دست بمالید و همراه خامه و شکر اضافه کنید؛ بگذارید گرم شود ولی نجوشد. نمکش را بچشید.'],
  [0,'Scatter over coriander and serve with naan or rice.','گشنیز خردشده رویش بریزید و با نان یا برنج سرو کنید.']],
 k:[['The sauce is thin and tastes of raw tomato; the chicken is still pink in the middle.','The sauce is thick, glossy and bright orange with butter pooling at the edges; the chicken is white right through and tender.','The sauce has split or caught on the bottom and the chicken is stringy; take it off the heat and stir in a splash of cream and water.'],
    ['سس رقیق است و مزه‌ی گوجه‌ی خام می‌دهد؛ مرغ وسطش هنوز صورتی است.','سس غلیظ، براق و نارنجی روشن است و کره کناره‌هایش جمع شده؛ مرغ تا وسط سفید و نرم است.','سس بریده یا ته گرفته و مرغ رشته‌رشته شده؛ از روی حرارت بردارید، کمی خامه و آب اضافه کنید و هم بزنید.']],
 m:'garlic-naan,kateh'});

R({id:'chana-masala',c:'main',min:40,sv:4,n:[340,12,42,14],app:'stove',cu:'in',col:'#A6582B',
 t:['Chana masala','چانا ماسالا'],d:['Chickpeas simmered in a tangy, spiced onion and tomato gravy.','نخود پخته در سس ترش و ادویه‌دار پیاز و گوجه'],
 i:'chickpeas:500:g;onion:2;tomato:3;garlic:4:clove;ginger:1:tbsp;chili:1::o;cumin:1:tsp;curry powder:2:tsp;paprika:1:tsp:o;lemon:1::o;coriander:::o;turmeric:0.5:tsp:s;oil:3:tbsp:s;salt::taste:s',
 s:[[40,'Finely chop the onions, tomatoes and chili and grate the garlic and ginger. Drain and rinse the canned or cooked chickpeas.','پیاز، گوجه و فلفل تند را ریز خرد کنید و سیر و زنجبیل را رنده کنید. نخود پخته یا کنسروی را آبکش کنید و بشویید.'],
  [33,'Heat the oil, add the cumin and let it sizzle for a few seconds, then fry the onions until deep golden, 10–12 minutes.','روغن را داغ کنید و زیره را بریزید تا چند ثانیه جلز و ولز کند، بعد پیاز را اضافه کنید و ۱۰ تا ۱۲ دقیقه تفت دهید تا کاملاً طلایی شود.'],
  [21,'Add the garlic, ginger and chili for a minute, then the turmeric, curry powder and paprika for 30 seconds. Add the tomatoes and cook until they break down and the oil shines at the edges, about 6 minutes.','سیر، زنجبیل و فلفل تند را اضافه کنید و یک دقیقه تفت دهید، بعد زردچوبه، پودر کاری و پاپریکا را ۳۰ ثانیه تفت دهید. گوجه را بریزید و حدود ۶ دقیقه بپزید تا له شود و سس روغن بیندازد.'],
  [14,'Add the chickpeas, salt and 1 cup water and simmer for 12 minutes, mashing a few chickpeas against the pan to thicken the gravy.','نخود، نمک و یک پیمانه آب را اضافه کنید و ۱۲ دقیقه بپزید؛ چند دانه نخود را با پشت قاشق به دیواره‌ی قابلمه له کنید تا سس غلیظ شود.'],
  [0,'Squeeze in lemon, scatter over coriander and serve with rice or naan.','آبلیمو بزنید، گشنیز رویش بریزید و با برنج یا نان سرو کنید.']],
 k:[['The tomatoes are still in pieces and the gravy is watery and tastes raw.','The masala is dark and jammy, oil glistens at the edges and the gravy coats the chickpeas thickly.','The gravy is dry and sticking, with a bitter scorched smell; loosen it with a splash of hot water and stop cooking.'],
    ['گوجه هنوز تکه‌تکه است، سس آبکی است و مزه‌ی خامی می‌دهد.','سس تیره و مربایی شده، روغن کناره‌ها برق می‌زند و سس غلیظ روی نخودها را پوشانده است.','سس خشک شده و ته گرفته و بوی سوختگی تلخ می‌دهد؛ کمی آب داغ اضافه کنید و دیگر نپزید.']],
 m:'garlic-naan,kateh'});

R({id:'dal-tadka',c:'stew',min:40,sv:4,n:[270,13,34,9],app:'stove',cu:'in',col:'#E3A82B',
 t:['Dal tadka','دال تادکا'],d:['Soft spiced lentils topped with sizzling garlic and cumin ghee.','عدس نرم و ادویه‌دار با داغ سیر و زیره در روغن حیوانی'],
 i:'lentils:200:g;onion:1;tomato:2;garlic:4:clove;ghee|butter:2:tbsp;cumin:1:tsp;ginger:1:tsp:o;chili:2::o;chili flakes::pinch:o;lemon:1::o;coriander:::o;turmeric:1:tsp:s;salt::taste:s',
 s:[[40,'Rinse the red lentils until the water runs clear, then simmer them in 3½ cups water with the turmeric for about 25 minutes, skimming off the foam, until completely soft.','عدس قرمز را چند بار بشویید تا آبش زلال شود، بعد با ۳ و نیم پیمانه آب و زردچوبه حدود ۲۵ دقیقه بپزید تا کاملاً نرم شود؛ کفش را بگیرید.'],
  [32,'Meanwhile chop the onion and tomatoes and fry the onion in half the ghee until golden. Add the tomatoes, ginger and chili and cook to a soft paste, about 8 minutes.','در این فاصله پیاز و گوجه را خرد کنید. پیاز را در نصف روغن حیوانی طلایی کنید، گوجه، زنجبیل و فلفل تند را اضافه کنید و حدود ۸ دقیقه بپزید تا له و خمیری شود.'],
  [15,'Whisk the soft lentils, stir in the onion and tomato mixture and the salt, and simmer for 8 minutes, adding hot water until it’s like a thick soup.','عدس پخته را با همزن دستی کمی هم بزنید تا یکدست شود، مخلوط پیاز و گوجه و نمک را اضافه کنید و ۸ دقیقه بپزید؛ اگر لازم شد آب داغ اضافه کنید تا غلظتش مثل سوپ غلیظ شود.'],
  [4,'For the tadka, heat the rest of the ghee until very hot, add the cumin and sliced garlic and fry until the garlic is golden, then take off the heat and add the chili flakes.','برای داغ (تادکا)، باقی روغن حیوانی را خوب داغ کنید، زیره و سیر خلالی را بریزید و تفت دهید تا سیر طلایی شود؛ بعد از روی حرارت بردارید و پول بیبر را اضافه کنید.'],
  [0,'Pour the sizzling tadka over the dal, squeeze in lemon, scatter with coriander and serve with rice.','روغن داغ و ادویه را همان‌طور که جلز و ولز می‌کند روی دال بریزید، آبلیمو بزنید، گشنیز بپاشید و با برنج سرو کنید.']],
 k:[['The cumin barely sizzles and the garlic is still pale and smells raw.','The cumin crackles and darkens a shade, the garlic is light golden and the kitchen smells nutty.','The garlic is dark brown and smells bitter; wipe out the pan and make the tadka again — it only takes two minutes.'],
    ['زیره به‌زور جلز و ولز می‌کند و سیر هنوز سفید است و بوی خامی می‌دهد.','زیره ترق‌تروق می‌کند و کمی تیره می‌شود، سیر طلایی روشن است و بوی بوداده در آشپزخانه می‌پیچد.','سیر قهوه‌ای تیره شده و بوی تلخی می‌دهد؛ تابه را پاک کنید و داغ را دوباره درست کنید؛ فقط دو دقیقه طول می‌کشد.']],
 m:'kateh,aloo-gobi'});

R({id:'chicken-biryani',c:'rice',min:90,sv:6,n:[700,38,82,24],app:'stove',cu:'in',col:'#D8A445',
 t:['Chicken biryani','بریانی مرغ هندی'],d:['Spiced chicken layered with fragrant saffron rice and crisp onions.','مرغ ادویه‌دار لایه‌لایه با برنج معطر زعفرانی و پیاز داغ ترد'],
 i:'rice:3:cup;chicken:1:kg;yogurt:1:cup;onion:3;garlic:5:clove;ginger:1:tbsp;curry powder:1:tbsp;cardamom:5;cinnamon:0.5:tsp;cumin:1:tsp;saffron::pinch;milk:3:tbsp;mint:1:bunch;ghee|butter:3:tbsp;tomato:2::o;chili flakes:1:tsp:o;coriander:1:bunch:o;lemon:1::o;oil:4:tbsp:s;turmeric:0.5:tsp:s;salt::taste:s',
 s:[[90,'Cut the chicken into large pieces and mix with the yogurt, grated garlic and ginger, curry powder, chili, turmeric, lemon juice and 1 tsp salt. Rinse the rice until the water runs clear and leave it to soak. Leave both for 30 minutes.','مرغ را درشت خرد کنید و با ماست، سیر و زنجبیل رنده‌شده، پودر کاری، فلفل، زردچوبه، آبلیمو و یک قاشق چای‌خوری نمک مخلوط کنید. برنج را بشویید تا آبش زلال شود و در آب خیس کنید. هر دو ۳۰ دقیقه بمانند.'],
  [75,'Meanwhile slice the onions thinly and fry them in the oil in a heavy pot, stirring, until deep golden and crisp, 15–20 minutes. Lift half out onto paper towels. Warm the milk and steep the saffron in it.','در این فاصله پیاز را نازک خلالی کنید و در قابلمه‌ی سنگین با روغن ۱۵ تا ۲۰ دقیقه تفت دهید تا طلایی تیره و ترد شود. نصفش را روی دستمال کاغذی بردارید. شیر را گرم کنید و زعفران را در آن دم کنید.'],
  [58,'Add the chicken and its marinade (and the chopped tomatoes, if using) to the onions left in the pot and cook, stirring now and then, until the chicken is just cooked and the sauce is thick, about 20 minutes.','مرغ را با مایه‌اش (و گوجه‌ی خردشده، اگر دوست دارید) روی پیاز داخل قابلمه بریزید و حدود ۲۰ دقیقه بپزید و گاهی هم بزنید تا مرغ تازه پخته و سس غلیظ شود.'],
  [40,'Meanwhile bring a big pan of well-salted water to the boil with the cardamom, cinnamon and cumin. Drain the rice, boil it for 5–6 minutes until two-thirds cooked — the grain should still snap in the middle — and drain.','در این فاصله یک قابلمه‌ی بزرگ آب پرنمک را با هل، دارچین و زیره بجوشانید. برنج را آبکش کنید، ۵ تا ۶ دقیقه بجوشانید تا دو سوم پخته شود (وسط دانه هنوز کمی سفت باشد) و دوباره آبکش کنید.'],
  [32,'Spread the rice over the chicken, scatter with the mint, coriander and crisp onions, drizzle over the saffron milk and melted ghee, cover with a towel-wrapped lid and cook on the lowest heat for 25 minutes.','برنج را روی مرغ پهن کنید، نعناع، گشنیز و پیاز داغ ترد را رویش بپاشید، شیر زعفرانی و روغن حیوانی آب‌شده را رویش بریزید، در قابلمه را با دم‌کنی ببندید و ۲۵ دقیقه روی کمترین حرارت دم بگذارید.'],
  [0,'Rest for 5 minutes, then scoop from the side down to the bottom so every plate gets rice, chicken and onions. Serve with yogurt or mast-o-khiar.','۵ دقیقه صبر کنید، بعد از کناره‌ی قابلمه تا ته بکشید تا به هر بشقاب هم برنج برسد، هم مرغ و هم پیاز. با ماست یا ماست و خیار سرو کنید.']],
 k:[['The rice is still chalky in the middle and no steam rises when you lift the lid.','Long, separate grains tender right through, a cloud of saffron-scented steam when you lift the lid, and the bottom moist but not soupy.','The rice is mushy and clumped, or there’s a burnt smell from the bottom; lift the top layers out gently and leave the base behind.'],
    ['وسط دانه‌های برنج هنوز سفت و گچی است و با برداشتن در، بخاری بلند نمی‌شود.','دانه‌های برنج بلند، جدا از هم و کاملاً نرم‌اند، با برداشتن در بخار معطر زعفران بلند می‌شود و ته قابلمه نمناک است ولی آبکی نیست.','برنج شفته و به هم چسبیده است یا از ته قابلمه بوی سوختگی می‌آید؛ لایه‌های رویی را آرام بردارید و ته آن را رها کنید.']],
 m:'mast-o-khiar'});

R({id:'palak-paneer',c:'main',min:40,sv:4,n:[380,17,13,29],app:'stove,blender|food processor',cu:'in',col:'#3E7B35',
 t:['Palak paneer','پالاک پنیر'],d:['Soft paneer cubes in a smooth, gently spiced spinach sauce.','مکعب‌های پنیر نرم در سس یکدست و ملایم اسفناج'],
 i:'spinach:500:g;cheese:250:g;onion:1;tomato:1;garlic:3:clove;ginger:1:tsp;cumin:1:tsp;curry powder:1:tsp;ghee|butter:2:tbsp;chili:1::o;cream:3:tbsp:o;fenugreek:1:tsp:o;lemon:1::o;oil:1:tbsp:s;turmeric:0.25:tsp:s;salt::taste:s',
 s:[[40,'Wash the spinach well. Cut the paneer (or halloumi) into 2 cm cubes, chop the onion and tomato and grate the garlic and ginger.','اسفناج را خوب بشویید. پنیر سفت (پنیر هندی یا حلومی) را مکعب‌های ۲ سانتی خرد کنید، پیاز و گوجه را خرد کنید و سیر و زنجبیل را رنده کنید.'],
  [33,'Blanch the spinach in boiling water for 2 minutes, plunge it into iced water, drain and blend smooth with the chili and a splash of the cold water.','اسفناج را ۲ دقیقه در آب جوش بیندازید، فوراً در آب یخ بریزید، آبکش کنید و با فلفل تند و کمی از همان آب سرد در مخلوط‌کن کاملاً یکدست کنید.'],
  [26,'Fry the paneer in the oil until golden on a few sides, 3–4 minutes, then drop it into warm salted water so it stays soft.','پنیر را در روغن ۳ تا ۴ دقیقه سرخ کنید تا چند طرفش طلایی شود، بعد در آب ولرم نمک‌دار بریزید تا نرم بماند.'],
  [20,'Melt the ghee, sizzle the cumin, then fry the onion until golden. Add the garlic, ginger, turmeric and curry powder for a minute, then the tomato, and cook to a soft paste, about 5 minutes.','روغن حیوانی را داغ کنید و زیره را بریزید تا جلز و ولز کند، بعد پیاز را طلایی کنید. سیر، زنجبیل، زردچوبه و پودر کاری را یک دقیقه تفت دهید، گوجه را اضافه کنید و حدود ۵ دقیقه بپزید تا له شود.'],
  [8,'Stir in the spinach purée and salt and simmer for 5 minutes — no longer, or it loses its colour. Add the drained paneer and the dried fenugreek, crumbled between your palms.','پوره‌ی اسفناج و نمک را اضافه کنید و فقط ۵ دقیقه بپزید؛ بیشتر بپزد رنگش را از دست می‌دهد. پنیر آبکش‌شده و شنبلیله‌ی خشک را که کف دست خرد کرده‌اید اضافه کنید.'],
  [0,'Swirl in the cream, add a squeeze of lemon and serve with naan or rice.','خامه را رویش بچرخانید، کمی آبلیمو بزنید و با نان یا برنج سرو کنید.']],
 k:[['The sauce is watery and tastes grassy and raw.','Bright, deep green and thick enough to coat a spoon; the paneer is soft and hot right through.','The sauce has turned khaki and dull and the paneer is rubbery; take it off the heat and brighten it with lemon and a spoonful of cream.'],
    ['سس آبکی است و مزه‌ی سبزی خام می‌دهد.','سس سبز پررنگ و روشن است و آن‌قدر غلیظ که پشت قاشق را بپوشاند؛ پنیر نرم و تا وسط داغ است.','سس خاکی و کدر شده و پنیر لاستیکی است؛ از روی حرارت بردارید و با آبلیمو و یک قاشق خامه جانش را برگردانید.']],
 m:'garlic-naan'});

R({id:'aloo-gobi',c:'side',min:35,sv:4,n:[270,6,32,13],app:'stove',cu:'in',col:'#DDA734',
 t:['Aloo gobi','سیب‌زمینی و گل‌کلم هندی (آلو گوبی)'],d:['Potatoes and cauliflower pan-cooked with turmeric, cumin and ginger.','سیب‌زمینی و گل‌کلم تفت‌داده با زردچوبه، زیره و زنجبیل'],
 i:'potato:3;cauliflower:1;onion:1;tomato:1;garlic:3:clove;ginger:1:tsp;cumin:1:tsp;curry powder:1:tsp;chili:1::o;coriander:::o;lemon:1::o;turmeric:1:tsp:s;oil:4:tbsp:s;salt::taste:s',
 s:[[35,'Cut the cauliflower into small florets and the potatoes into 2 cm cubes; chop the onion and tomato and grate the garlic and ginger.','گل‌کلم را گل‌های کوچک جدا کنید و سیب‌زمینی را مکعب‌های ۲ سانتی خرد کنید؛ پیاز و گوجه را خرد کنید و سیر و زنجبیل را رنده کنید.'],
  [28,'Heat the oil in a wide pan, sizzle the cumin, then fry the onion until soft and golden, about 5 minutes. Add the garlic, ginger, chili, turmeric and curry powder and stir for a minute.','روغن را در تابه‌ی پهن داغ کنید و زیره را بریزید تا جلز و ولز کند، بعد پیاز را حدود ۵ دقیقه تفت دهید تا نرم و طلایی شود. سیر، زنجبیل، فلفل تند، زردچوبه و پودر کاری را اضافه کنید و یک دقیقه هم بزنید.'],
  [21,'Add the potatoes and cauliflower and toss until coated and starting to brown at the edges, about 5 minutes.','سیب‌زمینی و گل‌کلم را اضافه کنید و حدود ۵ دقیقه هم بزنید تا به ادویه آغشته شوند و لبه‌هایشان کمی طلایی شود.'],
  [16,'Add the tomato, salt and 3 tbsp water, cover and cook on low for 12–15 minutes, stirring gently now and then, until tender. Uncover for the last few minutes to dry it out.','گوجه، نمک و ۳ قاشق آب را اضافه کنید، در تابه را بگذارید و روی حرارت کم ۱۲ تا ۱۵ دقیقه بپزید تا نرم شوند؛ گاهی آرام هم بزنید. چند دقیقه‌ی آخر در را بردارید تا آبش کشیده شود.'],
  [0,'Finish with lemon and coriander and serve with dal and naan or rice.','آبلیمو و گشنیز رویش بریزید و با دال و نان یا برنج سرو کنید.']],
 k:[['A knife meets resistance in the middle of the potato and the cauliflower still crunches.','A knife slides into the potato easily, the florets are tender with golden-brown edges and the pan is dry.','The cauliflower is falling apart and mushy; stop stirring, turn up the heat for a minute to crisp the bottom and serve.'],
    ['چاقو وسط سیب‌زمینی گیر می‌کند و گل‌کلم هنوز زیر دندان خام است.','چاقو راحت در سیب‌زمینی فرو می‌رود، گل‌کلم نرم است و لبه‌هایش طلایی و برشته است و ته تابه خشک است.','گل‌کلم له و وارفته شده؛ دیگر هم نزنید، یک دقیقه حرارت را زیاد کنید تا ته آن برشته شود و سرو کنید.']],
 m:'dal-tadka,garlic-naan'});

R({id:'chicken-tikka',c:'kebab',min:90,sv:4,n:[340,44,7,15],app:'oven|grill|air fryer',cu:'in',col:'#C4502A',
 t:['Chicken tikka','چیکن تیکا'],d:['Yogurt and spice marinated chicken, charred on skewers.','مرغ خوابانده در ماست و ادویه، کبابی و برشته روی سیخ'],
 i:'chicken:800:g;yogurt:0.75:cup;lemon:1;garlic:4:clove;ginger:1:tbsp;curry powder:2:tsp;paprika:2:tsp;cumin:1:tsp;chili flakes:1:tsp:o;onion:1::o;bell pepper:1::o;butter:1:tbsp:o;oil:2:tbsp:s;salt::taste:s',
 s:[[90,'Cut the chicken into 4 cm chunks (thighs stay juiciest). Mix the yogurt, lemon juice, grated garlic and ginger, spices, oil and 1 tsp salt, stir in the chicken and chill for at least an hour.','مرغ را تکه‌های ۴ سانتی خرد کنید (ران مرغ آبدارتر می‌ماند). ماست، آبلیمو، سیر و زنجبیل رنده‌شده، ادویه‌ها، روغن و یک قاشق چای‌خوری نمک را مخلوط کنید، مرغ را در آن بخوابانید و دست‌کم یک ساعت در یخچال بگذارید.'],
  [30,'Heat the oven to its hottest setting, about 240 °C (or heat the grill or air fryer). Cut the onion and pepper into squares.','فر را روی بالاترین دما، حدود ۲۴۰ درجه، روشن کنید (یا منقل یا سرخ‌کن بدون روغن را گرم کنید). پیاز و فلفل دلمه‌ای را مربعی خرد کنید.'],
  [20,'Thread the chicken onto skewers, alternating with the onion and pepper, and lay them on a rack over a lined tray.','مرغ را یکی در میان با پیاز و فلفل به سیخ بکشید و روی توری، بالای سینی کاغذ روغنی‌دار، بچینید.'],
  [17,'Cook for 14–16 minutes, turning once and brushing with melted butter, until charred at the edges and cooked through.','۱۴ تا ۱۶ دقیقه بپزید، یک بار برگردانید و کره‌ی آب‌شده بمالید تا لبه‌ها برشته و مرغ کامل پخته شود.'],
  [0,'Squeeze over lemon and serve with naan, sliced onion and mast-o-khiar.','آبلیمو رویش بزنید و با نان، پیاز حلقه‌شده و ماست و خیار سرو کنید.']],
 k:[['Pale with no charred spots, and the juices run pink when you cut the thickest piece.','Charred at the edges with a red-orange crust, the juices run clear and the meat is white and moist in the middle.','Black edges and dry, tight meat; brush with melted butter and lemon and serve at once.'],
    ['رنگ مرغ روشن است و هیچ جای برشته‌ای ندارد و وقتی کلفت‌ترین تکه را می‌برید، آبش صورتی است.','لبه‌ها برشته و رویش پوسته‌ی نارنجی‌قرمز بسته، آبش شفاف است و وسط گوشت سفید و آبدار است.','لبه‌ها سیاه شده و گوشت خشک و سفت است؛ کره‌ی آب‌شده و آبلیمو رویش بزنید و فوراً سرو کنید.']],
 m:'garlic-naan,mast-o-khiar'});

R({id:'garlic-naan',c:'side',min:90,sv:6,n:[280,7,40,10],app:'stove',cu:'in',col:'#E6C58A',
 t:['Garlic naan','نان سیر هندی'],d:['Soft, blistered pan-cooked flatbreads brushed with garlic butter.','نان نرم و پف‌کرده‌ی تابه‌ای با کره‌ی سیر'],
 i:'flour:300:g;yogurt:0.5:cup;milk:0.5:cup;yeast:1:tsp;butter|ghee:3:tbsp;garlic:4:clove;baking powder:0.5:tsp:o;coriander:::o;sugar:1:tsp:s;salt:1:tsp:s;oil:1:tbsp:s',
 s:[[90,'Warm the milk until lukewarm, stir in the sugar and yeast and leave for 5 minutes until foamy. Mix with the flour, salt, baking powder, yogurt and oil into a soft, slightly sticky dough and knead for 5 minutes until smooth.','شیر را ولرم کنید، شکر و خمیرمایه را در آن حل کنید و ۵ دقیقه بگذارید تا کف کند. با آرد، نمک، بکینگ‌پودر، ماست و روغن مخلوط کنید تا خمیری نرم و کمی چسبناک شود و ۵ دقیقه ورز دهید تا صاف شود.'],
  [80,'Cover and leave in a warm place until doubled, about 1 hour.','روی خمیر را بپوشانید و حدود یک ساعت در جای گرم بگذارید تا دو برابر شود.'],
  [20,'Melt the butter with the finely chopped garlic and coriander. Divide the dough into 6 balls and roll each into an oval about 5 mm thick.','کره را با سیر ریز خردشده و گشنیز آب کنید. خمیر را ۶ چانه کنید و هر کدام را به شکل بیضی و به ضخامت حدود نیم سانت باز کنید.'],
  [14,'Heat a heavy pan (cast iron is best) until very hot. Cook each naan until big bubbles puff up and the underside is spotted brown, about 1 minute, then flip and cook 1 minute more.','یک تابه‌ی سنگین (چدنی بهتر است) را خیلی داغ کنید. هر نان را حدود یک دقیقه بپزید تا حباب‌های درشت بزند و زیرش خال‌خال قهوه‌ای شود، بعد برگردانید و یک دقیقه‌ی دیگر بپزید.'],
  [0,'Brush each naan with garlic butter as it comes off the pan and keep them wrapped in a towel. Serve warm.','هر نان را که از تابه برداشتید با کره‌ی سیر چرب کنید و لای دستمال بپیچید تا گرم بماند. گرم سرو کنید.']],
 k:[['Pale and doughy, with only a few small bubbles.','Big puffed bubbles with dark blistered spots, soft and bendy, and it smells toasty.','Stiff and dry, cracking like a cracker; brush with butter and wrap in a warm towel for a few minutes to soften.'],
    ['نان رنگ‌پریده و خمیری است و فقط چند حباب کوچک زده.','حباب‌های درشت پف‌کرده با خال‌های قهوه‌ای تیره دارد، نرم است و خم می‌شود و بوی نان برشته می‌دهد.','سفت و خشک شده و مثل بیسکویت ترک می‌خورد؛ کره بمالید و چند دقیقه لای دستمال گرم بپیچید تا نرم شود.']],
 m:'butter-chicken,dal-tadka'});

R({id:'hummus',c:'side',min:15,sv:6,n:[250,8,19,16],app:'food processor|blender',cu:'me',col:'#E2CFA3',
 t:['Hummus','حمص'],d:['Silky chickpea and tahini dip with lemon and garlic.','دیپ لطیف نخود و ارده با لیمو و سیر'],
 i:'chickpeas:500:g;sesame:80:g;lemon:1;garlic:1:clove;cumin:0.5:tsp:o;paprika::pinch:o;parsley:::o;bread:::o;oil:3:tbsp:s;salt::taste:s',
 s:[[15,'Drain the canned or cooked chickpeas, keeping the liquid, and rub off any loose skins.','نخود پخته یا کنسروی را آبکش کنید، آبش را نگه دارید و پوست‌های جداشده را بگیرید.'],
  [10,'Blend the tahini, lemon juice, garlic and salt until thick and pale, then add 3 tbsp ice-cold water and blend until smooth and creamy.','ارده، آبلیمو، سیر و نمک را با غذاساز بزنید تا غلیظ و روشن شود، بعد ۳ قاشق آب یخ اضافه کنید و بزنید تا صاف و خامه‌ای شود.'],
  [6,'Add the chickpeas and cumin and blend for 3–4 minutes, scraping down the sides and adding splashes of the chickpea liquid, until very smooth and fluffy.','نخود و زیره را اضافه کنید و ۳ تا ۴ دقیقه بزنید؛ دیواره‌ها را با کاردک پایین بکشید و کم‌کم از آب نخود اضافه کنید تا کاملاً لطیف و پفکی شود.'],
  [0,'Spread in a shallow bowl, make a swirl with the back of a spoon, fill it with olive oil and dust with paprika and parsley. Serve with warm bread.','در کاسه‌ی کم‌عمق پهن کنید، با پشت قاشق گودی چرخشی درست کنید، رویش روغن زیتون بریزید و پاپریکا و جعفری بپاشید. با نان گرم سرو کنید.']],
 k:[['Grainy and stiff, sitting in a clump on the spoon.','Silky, pale and fluffy; it holds soft swirls and tastes of lemon and tahini, not raw garlic.','Runny and loose, sliding off the spoon; blend in a few more chickpeas or a spoonful of tahini to thicken it.'],
    ['دانه‌دانه و سفت است و گلوله‌ای روی قاشق می‌ماند.','لطیف، روشن و پفکی است، شکل چرخش قاشق را نگه می‌دارد و مزه‌ی لیمو و ارده می‌دهد، نه سیر خام.','شل و آبکی شده و از قاشق سر می‌خورد؛ چند نخود دیگر یا یک قاشق ارده اضافه کنید و دوباره بزنید تا غلیظ شود.']],
 m:'falafel,tabbouleh'});

R({id:'falafel',c:'main',min:60,sv:4,n:[370,14,42,17],app:'stove|air fryer,food processor',cu:'me',col:'#8E5B2C',
 t:['Falafel','فلافل'],d:['Crisp, herby chickpea fritters, green and fluffy inside.','فلافل ترد نخود و سبزی، داخلش سبز و پفکی'],
 i:'chickpeas:250:g;onion:1;garlic:4:clove;parsley:1:bunch;coriander:1:bunch;cumin:2:tsp;flour:2:tbsp;baking powder:1:tsp;chili flakes:0.5:tsp:o;sesame:1:tbsp:o;bread:4::o;tomato:::o;pickles:::o;oil:750:ml:s;salt:1:tsp:s;black pepper::taste:s',
 s:[[60,'Soak the dried chickpeas in plenty of cold water overnight — canned ones won’t hold together. Drain them very well and pat dry.','نخود خشک را از شب قبل در آب سرد فراوان خیس کنید (نخود کنسروی به هم نمی‌چسبد). خوب آبکش کنید و با دستمال خشک کنید.'],
  [55,'Pulse the chickpeas, roughly chopped onion, garlic, herbs, spices and salt in a food processor, scraping down often, until it looks like fine, damp couscous — not a paste.','نخود، پیاز درشت‌خردشده، سیر، سبزی‌ها، ادویه‌ها و نمک را در غذاساز چند بار با پالس بزنید و دیواره‌ها را پایین بکشید تا مثل بلغور ریز و نمناک شود، نه خمیر.'],
  [45,'Stir in the flour and baking powder, cover and chill for at least 20 minutes so the mix holds together.','آرد و بکینگ‌پودر را اضافه کنید و هم بزنید، رویش را بپوشانید و دست‌کم ۲۰ دقیقه در یخچال بگذارید تا خودش را بگیرد.'],
  [25,'Heat 5 cm of oil to 175 °C — a cube of bread should turn golden in 30 seconds. Squeeze the mix into walnut-size balls or small patties and roll some in sesame seeds.','روغن را به عمق ۵ سانت تا ۱۷۵ درجه داغ کنید (یک تکه نان باید در ۳۰ ثانیه طلایی شود). از مایه گلوله‌هایی به اندازه‌ی گردو یا کتلت کوچک درست کنید، محکم فشار دهید و بعضی را در کنجد بغلتانید.'],
  [14,'Fry in batches for 3–4 minutes, turning, until deep golden brown, and drain on paper towels. (Air fryer: brush with oil and cook at 200 °C for 12–14 minutes, turning halfway.)','در چند نوبت ۳ تا ۴ دقیقه سرخ کنید و برگردانید تا طلایی تیره شوند، بعد روی دستمال کاغذی بگذارید. (در سرخ‌کن بدون روغن: کمی روغن بمالید و در ۲۰۰ درجه ۱۲ تا ۱۴ دقیقه بپزید و وسط کار برگردانید.)'],
  [0,'Serve hot in warm bread with hummus, tomato, pickles and a drizzle of tahini.','داغ‌داغ لای نان گرم با حمص، گوجه، خیارشور و کمی ارده سرو کنید.']],
 k:[['Pale gold outside, and wet and pasty inside when you break one open.','Deep golden brown and crackly outside, bright green, fluffy and steaming inside.','Dark brown, hard and bitter; the oil is too hot — lower the heat and fry the next batch for less time.'],
    ['بیرونش طلایی کم‌رنگ است و وقتی یکی را می‌شکنید، داخلش خیس و خمیری است.','بیرونش قهوه‌ای طلایی و ترد است و داخلش سبز روشن، پفکی و پر از بخار.','قهوه‌ای تیره، سفت و تلخ شده؛ روغن خیلی داغ است، حرارت را کم کنید و نوبت بعدی را کوتاه‌تر سرخ کنید.']],
 m:'hummus,tabbouleh'});

R({id:'chicken-shawarma',c:'main',min:75,sv:4,n:[680,46,50,32],app:'oven|stove',cu:'me',col:'#B97638',
 t:['Chicken shawarma','شاورما مرغ'],d:['Spiced roast chicken wrapped in bread with garlic sauce and pickles.','مرغ ادویه‌دار کبابی لای نان با سس سیر و خیارشور'],
 i:'chicken:800:g;lemon:2;garlic:5:clove;yogurt:0.5:cup;cumin:2:tsp;paprika:2:tsp;cinnamon:0.5:tsp;onion:1;bread:4;tomato:2;cardamom::pinch:o;cucumber:1::o;pickles:::o;parsley:::o;mayonnaise:2:tbsp:o;turmeric:1:tsp:s;oil:4:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[75,'Slice the chicken thighs into strips and mix with the juice of 1 lemon, 3 grated garlic cloves, the cumin, paprika, cinnamon, cardamom, turmeric, 3 tbsp oil, salt and pepper. Marinate for at least 30 minutes (or overnight in the fridge).','ران مرغ را نواری خرد کنید و با آب یک لیمو، ۳ حبه سیر رنده‌شده، زیره، پاپریکا، دارچین، هل، زردچوبه، ۳ قاشق روغن، نمک و فلفل مخلوط کنید. دست‌کم ۳۰ دقیقه (یا یک شب در یخچال) بخوابانید.'],
  [40,'Heat the oven to 220 °C. Slice the onion and spread it on a tray with the chicken in one layer.','فر را روی ۲۲۰ درجه روشن کنید. پیاز را خلالی کنید و با مرغ در یک لایه در سینی پهن کنید.'],
  [35,'Roast for 25–30 minutes, stirring once, until cooked through and charred at the edges. (Or fry in batches in a very hot pan, 6–8 minutes each.)','۲۵ تا ۳۰ دقیقه در فر بپزید و یک بار هم بزنید تا کامل پخته و لبه‌هایش برشته شود. (یا در تابه‌ی خیلی داغ در چند نوبت، هر نوبت ۶ تا ۸ دقیقه سرخ کنید.)'],
  [20,'Meanwhile make the garlic sauce: stir together the yogurt, mayonnaise, 2 grated garlic cloves, a squeeze of lemon and a pinch of salt. Slice the tomatoes, cucumber and pickles.','در این فاصله سس سیر را درست کنید: ماست، مایونز، ۲ حبه سیر رنده‌شده، کمی آبلیمو و یک ذره نمک را هم بزنید. گوجه، خیار و خیارشور را حلقه کنید.'],
  [5,'Warm the bread. Chop the chicken roughly and toss it in the tray juices.','نان را گرم کنید. مرغ را درشت خرد کنید و در آب ته سینی بغلتانید.'],
  [0,'Spread the bread with garlic sauce, fill with chicken, tomato, cucumber, pickles and parsley, roll up tightly and serve.','روی نان سس سیر بمالید، مرغ، گوجه، خیار، خیارشور و جعفری را رویش بچینید، محکم لوله کنید و سرو کنید.']],
 k:[['Pale and sitting in watery juices, still pink in the thickest strips.','Crisp, charred edges, juicy inside with no pink, and the tray smells of cumin, cinnamon and garlic.','Dry, chewy and dark all over; chop it small and toss with extra garlic sauce and lemon before wrapping.'],
    ['مرغ رنگ‌پریده است، در آب خودش مانده و کلفت‌ترین تکه‌ها هنوز صورتی‌اند.','لبه‌ها ترد و برشته است، داخلش آبدار و بدون صورتی است و بوی زیره، دارچین و سیر از سینی بلند می‌شود.','همه‌جا تیره، خشک و سفت شده؛ ریزتر خرد کنید و قبل از پیچیدن با سس سیر و آبلیموی بیشتر مخلوط کنید.']],
 m:'hummus,fried-potatoes'});

R({id:'tabbouleh',c:'salad',min:25,sv:4,n:[190,3,14,14],app:'',cu:'me',col:'#5C9A3B',
 t:['Tabbouleh','تبوله'],d:['A bright, lemony parsley salad with tomato, mint and bulgur.','سالاد جعفری تازه و لیمویی با گوجه، نعناع و بلغور'],
 i:'parsley:3:bunch;mint:0.5:bunch;wheat:50:g;tomato:3;green onion:3;lemon:2;cinnamon::pinch:o;lettuce:::o;oil:4:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[25,'Rinse the fine bulgur (cracked wheat), cover it with the juice of 1 lemon and 2 tbsp water and leave for 15 minutes to soften.','بلغور ریز گندم را بشویید، آب یک لیمو و ۲ قاشق آب رویش بریزید و ۱۵ دقیقه بگذارید تا نرم شود.'],
  [20,'Wash the parsley and mint and dry them completely — wet herbs make a soggy salad. Pick off the thick stems.','جعفری و نعناع را بشویید و کاملاً خشک کنید (سبزی خیس سالاد را وا می‌دهد). ساقه‌های کلفت را جدا کنید.'],
  [12,'With a sharp knife, chop the herbs finely without bruising them. Dice the tomatoes small and slice the green onions.','سبزی‌ها را با چاقوی تیز ریز خرد کنید ولی له نکنید. گوجه را ریز نگینی و پیازچه را خرد کنید.'],
  [3,'Toss everything with the bulgur, the rest of the lemon juice, the olive oil, salt, pepper and a pinch of cinnamon.','همه را با بلغور، باقی آبلیمو، روغن زیتون، نمک، فلفل و یک ذره دارچین مخلوط کنید.'],
  [0,'Taste — it should be bright and lemony — and serve straight away, with lettuce leaves for scooping.','بچشید؛ باید ترش و تازه باشد. فوراً سرو کنید و برگ کاهو کنارش بگذارید تا با آن بردارید.']],
 k:[['The bulgur still crunches hard between your teeth.','Tender bulgur with a little bite, glossy bright-green herbs and just a spoonful of juice at the bottom of the bowl.','Soggy and dark, the herbs wilting in a pool of juice; drain it and toss in a handful of freshly chopped parsley.'],
    ['بلغور هنوز زیر دندان سفت و خام است.','بلغور نرم است ولی کمی زیر دندان می‌آید، سبزی‌ها سبز روشن و براق‌اند و ته کاسه فقط یک قاشق آب جمع شده.','سالاد وا رفته و تیره شده و سبزی‌ها در آب خوابیده‌اند؛ آبش را خالی کنید و یک مشت جعفری تازه‌خردشده اضافه کنید.']],
 m:'falafel,chicken-shawarma'});

R({id:'baba-ghanoush',c:'side',min:55,sv:4,n:[170,4,12,13],app:'stove|oven|grill',cu:'me',col:'#A99272',
 t:['Baba ghanoush','بابا غنوش'],d:['Smoky charred eggplant mashed with tahini, lemon and garlic.','بادمجان کبابی دودی، له‌شده با ارده، لیمو و سیر'],
 i:'eggplant:2;sesame:3:tbsp;lemon:1;garlic:1:clove;yogurt:2:tbsp:o;cumin::pinch:o;parsley:::o;pomegranate:::o;bread:::o;oil:2:tbsp:s;salt::taste:s',
 s:[[55,'Prick the eggplants a few times and char them directly over a gas flame, turning with tongs, for 15–20 minutes until black all over and collapsed, then cover them in a bowl to steam (or roast them in a 230 °C oven for 35–40 minutes).','بادمجان‌ها را چند جا سوراخ کنید و مستقیم روی شعله‌ی گاز ۱۵ تا ۲۰ دقیقه کباب کنید و با انبر بچرخانید تا همه‌جا سیاه و وارفته شوند؛ بعد در کاسه‌ای دربسته بگذارید تا عرق کنند (یا ۳۵ تا ۴۰ دقیقه در فر ۲۳۰ درجه بپزید).'],
  [15,'When cool enough to handle, peel off the skin and let the flesh drain in a sieve for 5 minutes so the dip isn’t watery.','وقتی کمی خنک شد پوستش را بگیرید و گوشت بادمجان را ۵ دقیقه در صافی بگذارید تا آبش برود و دیپ آبکی نشود.'],
  [8,'Mash the flesh with a fork — not a blender, it should keep a little texture — then stir in the tahini, grated garlic, lemon juice, yogurt, cumin and salt.','بادمجان را با چنگال له کنید (نه با مخلوط‌کن؛ باید کمی بافت داشته باشد)، بعد ارده، سیر رنده‌شده، آبلیمو، ماست، زیره و نمک را اضافه کنید و هم بزنید.'],
  [0,'Spread on a plate, drizzle with olive oil and scatter with parsley and pomegranate seeds. Serve with warm bread.','در بشقاب پهن کنید، روغن زیتون رویش بریزید و جعفری و دانه‌ی انار بپاشید. با نان گرم سرو کنید.']],
 k:[['The skin is only blistered in patches and the eggplant is still firm when pressed.','The skin is black and papery all over, the eggplant has collapsed and is soft to the core, and it smells smoky.','The flesh is dry and burnt under the skin; scrape away the bitter dark bits and add an extra spoonful of yogurt and tahini.'],
    ['پوست فقط جاهایی تاول زده و بادمجان با فشار انگشت هنوز سفت است.','پوست همه‌جا سیاه و کاغذی شده، بادمجان وا رفته و تا مغزش نرم است و بوی دود می‌دهد.','گوشت بادمجان زیر پوست خشک و سوخته شده؛ قسمت‌های تیره و تلخ را جدا کنید و یک قاشق ماست و ارده‌ی بیشتر اضافه کنید.']],
 m:'chicken-shawarma,tabbouleh'});

R({id:'mercimek',c:'soup',min:40,sv:4,n:[300,13,40,10],app:'stove,blender|food processor',cu:'tr',col:'#E08631',
 t:['Mercimek (Turkish red lentil soup)','سوپ مرجمک ترکی'],d:['Velvety red lentil soup with a sizzle of paprika-mint butter and lemon.','سوپ مخملی عدس قرمز با کره‌ی داغ پاپریکا و نعناع و لیمو'],
 i:'lentils:1:cup;onion:1;carrot:1;tomato paste:1:tbsp;butter:2:tbsp;cumin:1:tsp;paprika:1:tsp;lemon:1;potato:1::o;flour:1:tbsp:o;chili flakes:1:tsp:o;dried mint:1:tsp:o;bread:::o;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[40,'Rinse the red lentils well. Chop the onion, carrot and potato.','عدس قرمز را خوب بشویید. پیاز، هویج و سیب‌زمینی را خرد کنید.'],
  [35,'Soften the onion in the oil and 1 tbsp of the butter for 5 minutes, then stir in the flour and tomato paste for a minute.','پیاز را با روغن و یک قاشق از کره ۵ دقیقه تفت دهید تا نرم شود، بعد آرد و رب گوجه را اضافه کنید و یک دقیقه تفت دهید.'],
  [28,'Add the lentils, carrot, potato, cumin and 6 cups hot water, bring to the boil, then simmer, partly covered, for 20–25 minutes until everything is very soft.','عدس، هویج، سیب‌زمینی، زیره و ۶ پیمانه آب داغ را اضافه کنید و بگذارید جوش بیاید، بعد با در نیمه‌باز ۲۰ تا ۲۵ دقیقه آرام بپزید تا همه‌چیز کاملاً نرم شود.'],
  [6,'Blend until smooth, season with salt and pepper and thin with a little hot water if needed.','با گوشکوب برقی کاملاً یکدست کنید، نمک و فلفل بزنید و اگر غلیظ بود کمی آب داغ اضافه کنید.'],
  [2,'Melt the rest of the butter and stir in the paprika, chili flakes and dried mint until it sizzles and turns red.','باقی کره را آب کنید و پاپریکا، پول بیبر و نعناع خشک را در آن هم بزنید تا جلز و ولز کند و سرخ شود.'],
  [0,'Ladle into bowls, drizzle over the red butter and serve with lemon wedges and bread.','سوپ را در کاسه بکشید، کره‌ی سرخ را رویش بریزید و با برش لیمو و نان سرو کنید.']],
 k:[['The lentils still hold their shape and feel grainy when pressed against the spoon.','The lentils collapse to a mush and the soup blends velvety smooth and warm orange.','Thick as porridge and catching on the bottom; stir in hot water and don’t scrape up the stuck layer.'],
    ['عدس‌ها هنوز شکلشان را حفظ کرده‌اند و وقتی با قاشق فشارشان می‌دهید دانه‌دانه‌اند.','عدس‌ها کاملاً له شده‌اند و سوپ بعد از میکس، مخملی و نارنجی گرم می‌شود.','مثل فرنی غلیظ شده و ته گرفته؛ آب داغ اضافه کنید و هم بزنید ولی لایه‌ی ته‌گرفته را نتراشید.']],
 m:'lahmacun'});

R({id:'menemen',c:'breakfast',min:20,sv:2,n:[290,14,10,21],app:'stove',cu:'tr',col:'#D65A2C',
 t:['Menemen','منمن (املت ترکی)'],d:['Turkish soft-scrambled eggs with green peppers and tomatoes.','تخم‌مرغ نرم و هم‌زده‌ی ترکی با فلفل سبز و گوجه'],
 i:'eggs:4;tomato:3;bell pepper:2;butter:1:tbsp;onion:1::o;chili flakes:0.5:tsp:o;cheese:50:g:o;parsley:::o;bread:::o;oil:1:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[20,'Chop the green peppers (and the onion, if using) and grate the tomatoes or chop them finely.','فلفل سبز (و پیاز، اگر دوست دارید) را خرد کنید و گوجه را رنده یا ریز خرد کنید.'],
  [15,'Soften the peppers (and onion) in the butter and oil over medium heat for 5 minutes.','فلفل (و پیاز) را روی حرارت متوسط با کره و روغن ۵ دقیقه تفت دهید تا نرم شود.'],
  [10,'Add the tomatoes, chili flakes and salt and cook until most of the liquid has gone and it looks saucy, about 6 minutes.','گوجه، پول بیبر و نمک را اضافه کنید و حدود ۶ دقیقه بپزید تا بیشتر آبش کشیده شود و سس‌مانند شود.'],
  [3,'Beat the eggs lightly, pour them in and stir slowly just 2–3 times, until softly set in big creamy folds. Take off the heat while still a little wet.','تخم‌مرغ‌ها را کمی هم بزنید، روی گوجه بریزید و فقط ۲ تا ۳ بار آرام هم بزنید تا به شکل تکه‌های درشت و خامه‌ای ببندد. وقتی هنوز کمی خیس است از روی حرارت بردارید.'],
  [0,'Scatter with parsley and cheese and serve straight from the pan with bread and tea.','جعفری و پنیر رویش بپاشید و در همان تابه با نان و چای سرو کنید.']],
 k:[['Raw egg white still runs clear through the tomato.','Soft, glossy curds swirled with red tomato, still moist and a little loose — the heat of the pan finishes them.','Dry, rubbery crumbs in a watery puddle; stir in a knob of butter off the heat and eat right away.'],
    ['سفیده‌ی خام هنوز شفاف لای گوجه روان است.','تکه‌های نرم و براق تخم‌مرغ لای گوجه‌ی سرخ، هنوز نمناک و کمی شل است؛ حرارت تابه بقیه‌اش را می‌پزد.','تخم‌مرغ خشک، لاستیکی و ریزریز شده و آب انداخته؛ بیرون از حرارت یک تکه کره اضافه کنید و فوراً بخورید.']],
 m:'chai'});

R({id:'lahmacun',c:'main',min:100,sv:4,n:[630,28,80,22],app:'oven',cu:'tr',col:'#B04A2E',
 t:['Beef lahmacun','لاهماجون گوشت'],d:['Thin, crisp flatbreads topped with spiced beef, rolled up with lemon and parsley.','نان نازک و ترد با گوشت چرخ‌کرده‌ی ادویه‌دار، لوله‌شده با لیمو و جعفری'],
 i:'flour:400:g;yeast:1:tsp;ground meat:300:g;onion:2;tomato:2;bell pepper:1;garlic:2:clove;parsley:1:bunch;tomato paste:2:tbsp;paprika:1:tsp;lemon:1;chili flakes:1:tsp:o;cumin:1:tsp:o;sumac:1:tsp:o;sugar:1:tsp:s;oil:2:tbsp:s;salt::taste:s;black pepper::taste:s',
 s:[[100,'Mix the flour, yeast, sugar, 1 tsp salt, the oil and about 250 ml lukewarm water into a soft dough and knead for 5 minutes until smooth. Cover and leave to rise for 1 hour.','آرد، خمیرمایه، شکر، یک قاشق چای‌خوری نمک، روغن و حدود ۲۵۰ میلی‌لیتر آب ولرم را مخلوط کنید تا خمیری نرم شود و ۵ دقیقه ورز دهید تا صاف شود. رویش را بپوشانید و یک ساعت بگذارید تا ور بیاید.'],
  [90,'Meanwhile make the topping: very finely chop one onion, the tomatoes, pepper, garlic and half the parsley (a food processor helps — pulse, don’t purée), then mix well with the beef, tomato paste, paprika, chili, cumin, salt and pepper.','در این فاصله مایه‌ی رویی را آماده کنید: یک پیاز، گوجه، فلفل دلمه‌ای، سیر و نصف جعفری را خیلی ریز خرد کنید (با غذاساز چند بار پالس بزنید، پوره نکنید)، بعد با گوشت، رب گوجه، پاپریکا، پول بیبر، زیره، نمک و فلفل خوب ورز دهید.'],
  [45,'Heat the oven as hot as it goes — 250 °C or more — with a baking tray inside. Divide the dough into 8 balls.','فر را روی بالاترین دما (۲۵۰ درجه یا بیشتر) روشن کنید و سینی را داخلش بگذارید تا داغ شود. خمیر را ۸ چانه کنید.'],
  [38,'Roll each ball out very thin, about 25 cm across, and spread a thin layer of topping right to the edges, pressing it in.','هر چانه را خیلی نازک، به قطر حدود ۲۵ سانت، باز کنید و لایه‌ی نازکی از مایه را تا لبه‌ها رویش پهن کنید و کمی فشار دهید.'],
  [28,'Slide two at a time onto the hot tray and bake for 6–8 minutes, until the edges are crisp and the meat is cooked. Stack them under a towel so they stay soft enough to roll.','هر بار دو تا را روی سینی داغ بگذارید و ۶ تا ۸ دقیقه بپزید تا لبه‌ها ترد و گوشت پخته شود. نان‌ها را روی هم زیر دستمال بچینید تا برای لوله‌کردن نرم بمانند.'],
  [0,'Top with parsley and the second onion, thinly sliced and tossed with sumac, squeeze over lemon, roll up and eat.','جعفری و پیاز دوم را که نازک خلالی کرده و با سماق مخلوط کرده‌اید رویش بریزید، آبلیمو بزنید، لوله کنید و بخورید.']],
 k:[['The dough is pale and floppy and the meat still looks wet and pink.','The edges are crisp and browned in spots and the meat is cooked and sizzling, yet it’s still thin and bendy enough to roll.','Hard and cracker-like, snapping instead of rolling; brush with water and cover with a towel for a few minutes to soften.'],
    ['خمیر رنگ‌پریده و شل است و گوشت هنوز خیس و صورتی به نظر می‌رسد.','لبه‌ها ترد و جابه‌جا طلایی است، گوشت پخته و جلز و ولز می‌کند ولی نان هنوز نازک و آن‌قدر نرم است که لوله شود.','سفت و بیسکویتی شده و به‌جای لوله‌شدن می‌شکند؛ کمی آب رویش بزنید و چند دقیقه زیر دستمال بگذارید تا نرم شود.']],
 m:'mercimek,doogh'});

R({id:'beef-kofte',c:'kebab',min:45,sv:4,n:[450,30,10,32],app:'stove|grill',cu:'tr',col:'#7B4229',
 t:['Beef köfte','کوفته‌ی ترکی'],d:['Juicy grilled beef patties with onion, parsley and cumin.','کوفته‌های کبابی آبدار با گوشت، پیاز، جعفری و زیره'],
 i:'ground meat:600:g;onion:1;garlic:2:clove;parsley:0.5:bunch;breadcrumbs|bread:40:g;cumin:1:tsp;paprika:1:tsp;eggs:1::o;chili flakes:0.5:tsp:o;tomato:2::o;bell pepper:2::o;oil:1:tbsp:s;salt:1:tsp:s;black pepper:0.5:tsp:s',
 s:[[45,'Grate the onion and squeeze out its juice. Finely chop the parsley and crush the garlic.','پیاز را رنده کنید و آبش را بگیرید. جعفری را ریز خرد کنید و سیر را له کنید.'],
  [40,'Mix the beef with the onion, garlic, parsley, breadcrumbs, egg, spices, salt and pepper and knead for 3–4 minutes until sticky and smooth. Cover and chill for 20–30 minutes.','گوشت را با پیاز، سیر، جعفری، پودر سوخاری، تخم‌مرغ، ادویه‌ها، نمک و فلفل مخلوط کنید و ۳ تا ۴ دقیقه ورز دهید تا چسبناک و یکدست شود. رویش را بپوشانید و ۲۰ تا ۳۰ دقیقه در یخچال بگذارید.'],
  [15,'With wet hands, shape into small flat patties about the length of a finger and 1.5 cm thick.','با دست خیس، مایه را به شکل کوفته‌های کوچک و پهن، به درازای یک انگشت و ضخامت ۱٫۵ سانت، درآورید.'],
  [10,'Heat a griddle, heavy pan or grill until very hot, brush with oil and cook the köfte in batches for 3–4 minutes a side. Char the tomatoes and peppers alongside.','گریل، تابه‌ی سنگین یا منقل را خیلی داغ کنید، کمی روغن بزنید و کوفته‌ها را در چند نوبت هر طرف ۳ تا ۴ دقیقه بپزید. گوجه و فلفل را هم کنارش کباب کنید.'],
  [0,'Serve hot with bread, sliced onion, the charred vegetables and a salad.','داغ با نان، پیاز خلالی، گوجه و فلفل کبابی و سالاد سرو کنید.']],
 k:[['Soft and pink in the middle, with red juices when you press one.','Browned and striped with char, springy when pressed, the juices run clear and the inside is just cooked and juicy.','Hard, dry and crumbly with a burnt crust; serve with yogurt or tomato sauce to bring back some moisture.'],
    ['وسطش نرم و صورتی است و با فشار، آب قرمز بیرون می‌دهد.','رویش قهوه‌ای و خط‌خط برشته است، با فشار فنری است، آبش شفاف است و داخلش تازه پخته و آبدار است.','سفت، خشک و خردشونده با رویه‌ی سوخته؛ با ماست یا سس گوجه سرو کنید تا کمی آبداری‌اش برگردد.']],
 m:'salad-shirazi,doogh'});


/* ---------- how to tell it’s done (almost there, perfect, overcooked) — English, then Persian ---------- */
var DP_DONE={
"ghormeh-sabzi":[["Beans are soft, but the stew is still thin and light green, with no oil on top yet.", "Dark green-brown and thick, a layer of oil shines on top, and the beans and meat fall apart easily.", "The herbs taste bitter or burnt and the bottom has stuck. Add hot water and don’t scrape the bottom."],["لوبیا نرم شده ولی خورش هنوز رقیق و سبز روشن است و روغن نینداخته.", "سبز تیره و غلیظ است، روغن رویش آمده و لوبیا و گوشت راحت له می‌شوند.", "سبزی تلخ یا سوخته مزه می‌دهد و ته گرفته. آب داغ اضافه کنید و ته قابلمه را نتراشید."]],
"gheymeh":[["The split peas hold their shape but are still firm in the middle.", "Split peas soft but whole, the sauce thick and reddish with oil on top.", "Split peas turn to mush and the sauce sticks to the pot; fries go soggy if added too early."],["لپه‌ها شکلشان را دارند ولی وسطشان هنوز سفت است.", "لپه نرم ولی سالم است، سس غلیظ و قرمز است و روغن انداخته.", "لپه له شده و خورش ته گرفته؛ اگر سیب‌زمینی را زود بریزید خمیر می‌شود."]],
"fesenjan":[["The sauce is brown and still grainy and tastes of raw walnut.", "Deep chocolate-brown and glossy, walnut oil pooling on top, smooth and sweet-sour.", "Almost black, pasty and bitter, stuck to the bottom. Loosen it with a little hot water."],["سس قهوه‌ای و هنوز دانه‌دانه است و طعم گردوی خام می‌دهد.", "قهوه‌ای تیره و براق است، روغن گردو رویش آمده و ملس و یکدست است.", "تقریباً سیاه، خمیری و تلخ شده و ته گرفته. با کمی آب داغ رقیقش کنید."]],
"khoresh-bademjan":[["The eggplant is soft but still holds its shape; the sauce is thin.", "The eggplant is silky and melts on the tongue; the sauce is thick and red with oil on top.", "The eggplant has turned to mush and the sauce is burning on the bottom."],["بادمجان نرم شده ولی هنوز شکلش را دارد و سس رقیق است.", "بادمجان لطیف است و در دهان آب می‌شود؛ سس غلیظ و قرمز با روغن روی آن.", "بادمجان کاملاً له شده و سس ته گرفته."]],
"khoresh-karafs":[["The celery is bright green and still crunchy.", "The celery is tender, not stringy; the stew is deep green with oil on top.", "The celery turns grey-brown and falls apart; the herbs taste bitter."],["کرفس سبز روشن و هنوز ترد است.", "کرفس نرم شده ولی له نیست و خورش سبز تیره با روغن روی آن است.", "کرفس خاکستری و قهوه‌ای و له شده و سبزی تلخ است."]],
"abgoosht":[["The chickpeas are soft but the meat still resists a fork.", "The meat falls off the bone, chickpeas and potatoes crush easily, and the broth is rich and golden-red.", "The broth has boiled away and everything is dry and stuck. Top it up with boiling water."],["نخود نرم شده ولی گوشت هنوز جلوی چنگال مقاومت می‌کند.", "گوشت از استخوان جدا می‌شود، نخود و سیب‌زمینی راحت له می‌شوند و آبش جاافتاده و خوش‌رنگ است.", "آبش تمام شده و همه‌چیز خشک و ته‌گرفته است. آب جوش اضافه کنید."]],
"chelo":[["When parboiling, the grains are soft outside with a tiny hard core when you bite one.", "Grains long, separate and fluffy, steam holes on top, and the tahdig crackles when you tap the pot.", "The grains break and go mushy, or the tahdig smells burnt and turns black."],["موقع آبکش کردن، بیرون دانه نرم است ولی وسطش کمی سفت است.", "دانه‌ها قد کشیده، جدا و پفکی‌اند، روی برنج سوراخ‌های بخار هست و ته‌دیگ جزجز می‌کند.", "دانه‌ها شکسته و شفته شده‌اند یا ته‌دیگ بوی سوختگی می‌دهد و سیاه شده."]],
"kateh":[["The water is almost gone and small holes appear on the surface.", "No water left, the rice is soft and slightly sticky, with a golden crust at the bottom.", "The rice is mushy and wet, or the bottom smells burnt."],["آب تقریباً کشیده شده و روی برنج سوراخ‌های کوچک پیدا شده.", "آبی نمانده، برنج نرم و کمی چسبناک است و ته آن طلایی شده.", "برنج شفته و خیس است یا ته آن بوی سوختگی می‌دهد."]],
"zereshk-polo":[["The barberries are plump and bright red.", "Barberries glossy red and sweet-sour, rice fluffy, chicken juices clear.", "The barberries turn dark brown or black and bitter — they burn in seconds."],["زرشک پف کرده و قرمز روشن است.", "زرشک قرمز و براق و ملس است، برنج پفکی و آب مرغ شفاف است.", "زرشک قهوه‌ای یا سیاه و تلخ شده؛ زرشک در چند ثانیه می‌سوزد."]],
"loobia-polo":[["The green beans are bright green and still squeaky.", "Beans tender, rice red, fluffy and separate, tahdig golden.", "The rice goes mushy and the tomato mix burns on the bottom."],["لوبیا سبز روشن و هنوز کمی سفت است.", "لوبیا نرم است، برنج قرمز، پفکی و دانه‌دانه است و ته‌دیگ طلایی.", "برنج شفته شده و مایه‌ی گوجه ته گرفته."]],
"adas-polo":[["The lentils are cooked but still a little firm.", "Lentils soft but whole, rice fluffy, raisins plump and dates soft.", "The lentils burst and the rice goes mushy; raisins burn fast in hot oil."],["عدس پخته ولی هنوز کمی سفت است.", "عدس نرم ولی سالم است، برنج پفکی، کشمش پف‌کرده و خرما نرم است.", "عدس ترکیده و برنج شفته شده؛ کشمش در روغن داغ زود می‌سوزد."]],
"baghali-polo":[["The lamb shank still resists a fork.", "The meat slides off the bone and the dill rice is fluffy.", "The shank is dry and stringy and the rice mushy."],["ماهیچه هنوز جلوی چنگال مقاومت می‌کند.", "گوشت از استخوان جدا می‌شود و برنج شوید باقالی پفکی است.", "ماهیچه خشک و ریش‌ریش شده و برنج شفته است."]],
"sabzi-polo":[["The rice is bright green and a little firm.", "Rice fluffy, herbs fragrant; the fish flakes easily and is opaque inside.", "Herbs dark and rice mushy; the fish is dry and crumbles."],["برنج سبز روشن و کمی سفت است.", "برنج پفکی و سبزی معطر است؛ ماهی راحت ورقه می‌شود و داخلش مات است.", "سبزی تیره و برنج شفته شده؛ ماهی خشک و خرد شده."]],
"tahchin":[["The edges pull away from the dish and look pale gold.", "A deep golden crust all round; it slides out in one piece when turned over.", "The crust is dark brown or black and bitter, and the inside is dry."],["لبه‌ها از ظرف جدا شده و طلایی کم‌رنگ است.", "دورتادور طلایی پررنگ است و موقع برگرداندن یکپارچه بیرون می‌آید.", "ته آن قهوه‌ای تیره یا سیاه و تلخ است و داخل خشک شده."]],
"estamboli":[["The water is almost gone but the rice is still a little firm.", "Rice red, soft and separate, potatoes tender, the bottom lightly crisp.", "The rice is mushy, or burnt on the bottom."],["آب تقریباً کشیده شده ولی برنج هنوز کمی سفت است.", "برنج قرمز، نرم و دانه‌دانه است، سیب‌زمینی نرم و ته کمی برشته.", "برنج شفته شده یا ته سوخته است."]],
"joojeh-kabab":[["Golden at the edges but still pink in the middle when you cut a piece.", "Charred spots, juicy, white all the way through with clear juices.", "Dry, hard and stringy, with black edges."],["لبه‌ها طلایی شده ولی وسط تکه هنوز صورتی است.", "جای کباب‌شده دارد، آبدار است و داخلش کاملاً سفید و آبش شفاف است.", "خشک، سفت و ریش‌ریش شده و لبه‌هایش سیاه است."]],
"koobideh":[["The outside is browning but the inside is still soft and pale.", "Browned outside, juicy inside with no pink, firm when pressed.", "Dry and crumbly; it cracks and falls off the skewer."],["رویش قهوه‌ای شده ولی داخلش هنوز نرم و کم‌رنگ است.", "بیرونش برشته و داخلش آبدار و بدون صورتی است و با فشار سفت است.", "خشک و ترد شده، ترک برداشته و از سیخ می‌افتد."]],
"kabab-tabei":[["Brown underneath but the top still looks raw.", "Both sides brown, juicy inside, no pink.", "Dry, shrunken, dark and hard."],["زیرش قهوه‌ای شده ولی رویش هنوز خام به نظر می‌رسد.", "هر دو طرف قهوه‌ای، داخلش آبدار و بدون صورتی است.", "خشک و جمع شده، تیره و سفت است."]],
"ash-reshteh":[["The beans are soft but the noodles are firm and the soup is thin.", "Thick and creamy, noodles soft, beans tender, deep green.", "The noodles dissolve and it’s so thick it sticks to the pot. Add hot water."],["حبوبات نرم شده ولی رشته هنوز سفت و آش رقیق است.", "غلیظ و لعاب‌دار است، رشته نرم، حبوبات پخته و رنگ سبز تیره.", "رشته وا رفته و آش آن‌قدر غلیظ شده که ته می‌گیرد. آب داغ اضافه کنید."]],
"adasi":[["The lentils are soft but the broth is still thin.", "Lentils creamy and just starting to break down; the soup is thick.", "It has turned to paste and sticks to the bottom."],["عدس نرم شده ولی آبش هنوز رقیق است.", "عدس کرمی و در حال له شدن است و عدسی جاافتاده و غلیظ است.", "خمیر شده و ته گرفته."]],
"soup-jo":[["The barley is swollen but still chewy.", "The barley is soft and the soup thick and creamy.", "The barley is gluey and the soup so thick it sticks."],["جو پف کرده ولی هنوز سفت است.", "جو نرم است و سوپ غلیظ و لعاب‌دار.", "جو چسبناک شده و سوپ آن‌قدر غلیظ است که ته می‌گیرد."]],
"nimroo":[["The whites are set at the edges but clear and runny near the yolk.", "Whites fully white, yolk still glossy and runny.", "Pale, hard yolk and rubbery whites with brown, crispy edges."],["لبه‌ی سفیده بسته ولی کنار زرده هنوز شفاف و آبکی است.", "سفیده کاملاً سفید و زرده هنوز براق و عسلی است.", "زرده سفت و کم‌رنگ و سفیده لاستیکی با لبه‌های قهوه‌ای است."]],
"noon-panir-sabzi":[["The herbs are washed but still wet.", "Herbs dry and crisp, bread warm and soft, cheese at room temperature.", "Herbs wilted or bread dried out from sitting too long."],["سبزی شسته شده ولی هنوز خیس است.", "سبزی خشک و ترد، نان گرم و نرم و پنیر هم‌دمای اتاق است.", "سبزی پلاسیده یا نان خشک شده، چون زیاد مانده."]],
"halim":[["The wheat is soft but you can still see whole grains and pieces of meat.", "Smooth and stretchy — lift the spoon and it pulls into threads.", "A scorched smell from the bottom, and it’s too thick to stir."],["گندم نرم شده ولی هنوز دانه‌ها و تکه‌های گوشت پیداست.", "یکدست و کش‌دار است؛ قاشق را بلند کنید رشته‌رشته کش می‌آید.", "از ته بوی سوختگی می‌آید و آن‌قدر غلیظ شده که هم نمی‌خورد."]],
"kotlet":[["Brown at the edges but soft and pale in the middle.", "Deep brown and crisp on both sides, firm when pressed.", "A black crust and dry inside; they taste bitter."],["لبه‌ها قهوه‌ای شده ولی وسط کتلت نرم و کم‌رنگ است.", "هر دو طرف قهوه‌ای پررنگ و ترد است و با فشار سفت است.", "رویش سیاه و داخلش خشک شده و تلخ است."]],
"kuku-sabzi":[["The edges are set but the middle wobbles when you shake the pan.", "Firm all through, a toothpick comes out clean, dark green with a brown crust.", "Dry and crumbly, with a black, bitter crust."],["لبه‌ها بسته ولی وسطش با تکان دادن تابه می‌لرزد.", "کاملاً سفت شده، خلال دندان تمیز بیرون می‌آید، سبز تیره با رویه‌ی قهوه‌ای.", "خشک و ترد شده و رویه‌اش سیاه و تلخ است."]],
"kuku-sibzamini":[["Golden at the edges but soft in the middle.", "Golden-brown on both sides and holds together when lifted.", "Dark brown to black, greasy and dry."],["لبه‌ها طلایی شده ولی وسطش هنوز نرم است.", "هر دو طرف طلایی-قهوه‌ای است و با برداشتن از هم نمی‌پاشد.", "قهوه‌ای تیره تا سیاه شده و خشک و چرب است."]],
"mirza-ghasemi":[["The eggplant is soft and the eggs are just in and still wet.", "The eggs are cooked into the eggplant; it’s smoky, thick and orange-brown.", "Dry and dark, with burnt, bitter garlic."],["بادمجان نرم شده و تخم‌مرغ تازه اضافه شده و هنوز خیس است.", "تخم‌مرغ با بادمجان پخته و یکی شده؛ دودی، غلیظ و نارنجی-قهوه‌ای است.", "خشک و تیره شده و سیر سوخته و تلخ است."]],
"kashk-bademjan":[["The eggplant is soft but still in pieces.", "The eggplant mashes into a smooth, creamy dip and the onion and mint toppings are crisp.", "The fried onion or mint is burnt and bitter; the eggplant is greasy and dark."],["بادمجان نرم شده ولی هنوز تکه‌تکه است.", "بادمجان یکدست و کرمی له می‌شود و پیاز داغ و نعناع داغ ترد است.", "پیاز داغ یا نعناع داغ سوخته و تلخ است و بادمجان چرب و تیره."]],
"omlet":[["The tomato is thick but the eggs are still runny.", "The eggs have just set in soft, glossy curds.", "The eggs are dry and grainy and the tomato has stuck to the pan."],["گوجه غلیظ شده ولی تخم‌مرغ هنوز آبکی است.", "تخم‌مرغ تازه بسته و نرم و هنوز براق است.", "تخم‌مرغ خشک و دانه‌دانه شده و گوجه ته گرفته."]],
"makaroni":[["The pasta bends but has a firm white core.", "Tender with a slight bite, the sauce clings, and the tahdig is golden and crisp.", "The pasta is soft and mushy and the tahdig black."],["ماکارونی خم می‌شود ولی وسطش سفید و سفت است.", "ماکارونی نرم با کمی مقاومت است، سس به آن چسبیده و ته‌دیگ طلایی و ترد است.", "ماکارونی وا رفته و ته‌دیگ سیاه شده."]],
"yatimcheh":[["The eggplant is soft but the sauce is still watery.", "Silky eggplant, a thick sauce, and oil rising to the top.", "Everything is mushy and stuck to the pan."],["بادمجان نرم شده ولی سس هنوز آبکی است.", "بادمجان لطیف و سس غلیظ است و روغن رویش آمده.", "همه‌چیز له شده و ته گرفته."]],
"salad-shirazi":[["Chopped but not dressed yet.", "Dressed with lime and mint just before serving — crisp and bright.", "It sat too long and went watery and soft. Pour off the extra liquid."],["خرد شده ولی هنوز آبلیمو و نعناع نخورده.", "درست پیش از سرو آبلیمو و نعناع خورده؛ ترد و تازه است.", "زیاد مانده، آب انداخته و نرم شده. آب اضافه‌اش را بریزید."]],
"mast-o-khiar":[["Just mixed; the flavours are still separate.", "Chilled for 10 minutes, the cucumber crunchy and the mint fragrant.", "Left too long, it’s watery and the cucumber limp. Stir and drain."],["تازه مخلوط شده و طعم‌ها هنوز جدا هستند.", "ده دقیقه در یخچال مانده، خیار ترد و نعناع معطر است.", "زیاد مانده، آب انداخته و خیار شل شده. هم بزنید و آبش را بگیرید."]],
"borani-esfenaj":[["The spinach is wilted but still wet.", "The spinach is dry and cool and mixed smoothly into thick yogurt.", "Watery spinach makes the yogurt runny."],["اسفناج پلاسیده ولی هنوز خیس است.", "اسفناج خشک و خنک است و با ماست غلیظ یکدست شده.", "اسفناج آب انداخته و ماست را آبکی کرده."]],
"olivieh":[["The potatoes and eggs are boiled but still warm.", "Everything completely cold before mixing; creamy and holds its shape.", "Overcooked potatoes turn the salad into paste."],["سیب‌زمینی و تخم‌مرغ پخته ولی هنوز گرم است.", "همه‌چیز قبل از مخلوط کردن کاملاً سرد شده؛ کرمی است و فرمش را نگه می‌دارد.", "سیب‌زمینی بیش از حد پخته و سالاد خمیری شده."]],
"sabzi-khordan":[["Washed but still wet.", "Dry, crisp and bright green, the radishes crunchy.", "Wilted or slimy from sitting wet."],["شسته شده ولی هنوز خیس است.", "خشک، ترد و سبز روشن است و تربچه ترد است.", "پلاسیده یا لزج شده، چون خیس مانده."]],
"sholeh-zard":[["The rice is soft but the pudding is still runny.", "Thick, glossy and golden; it falls slowly from the spoon and the grains are soft.", "Too thick to pour, and scorched on the bottom."],["برنج نرم شده ولی شله‌زرد هنوز آبکی است.", "غلیظ و براق و طلایی است، آرام از قاشق می‌ریزد و دانه‌ها نرم‌اند.", "آن‌قدر سفت شده که نمی‌ریزد و ته گرفته."]],
"shir-berenj":[["The rice is soft but the milk is still thin.", "Creamy and thick like custard; it coats the back of a spoon.", "A thick paste with a brown, scorched layer on the bottom."],["برنج نرم شده ولی شیر هنوز رقیق است.", "کرمی و غلیظ است و پشت قاشق را می‌پوشاند.", "خمیر شده و ته آن قهوه‌ای و سوخته است."]],
"halva":[["The flour is light beige and smells of raw dough.", "The flour is deep golden-brown with a toasted, nutty smell; after the syrup it pulls away from the pan.", "Dark brown and bitter — burnt flour can’t be saved; start again."],["آرد بژ روشن است و بوی خامی می‌دهد.", "آرد طلایی-قهوه‌ای است و بوی برشته و مغزدار می‌دهد؛ بعد از شربت از کناره‌ها جدا می‌شود.", "قهوه‌ای تیره و تلخ شده؛ آرد سوخته درست‌شدنی نیست، از نو شروع کنید."]],
"fereni":[["The milk is warm and just starting to thicken.", "Smooth and thick; it coats a spoon and a finger line stays clear.", "Lumpy, or scorched on the bottom."],["شیر گرم شده و تازه دارد غلیظ می‌شود.", "یکدست و غلیظ است، پشت قاشق را می‌پوشاند و خط انگشت روی آن می‌ماند.", "گلوله‌گلوله شده یا ته گرفته."]],
"cake-yazdi":[["Risen but pale; a toothpick comes out wet.", "Domed and golden, springs back when touched, and a toothpick comes out clean.", "Dark brown and dry, or bitter."],["پف کرده ولی رویش کم‌رنگ است و خلال دندان خیس بیرون می‌آید.", "گنبدی و طلایی است، با لمس برمی‌گردد و خلال دندان تمیز بیرون می‌آید.", "قهوه‌ای تیره و خشک یا تلخ شده."]],
"doogh":[["Just mixed and not cold yet.", "Ice cold and frothy, salty-sour with mint.", "Left out too long, it separates and turns too sour. Shake it well."],["تازه مخلوط شده و هنوز خنک نیست.", "یخ و کف‌دار است، شور و ترش با عطر نعناع.", "زیاد بیرون مانده، دو فاز شده و خیلی ترش است. خوب تکان دهید."]],
"sekanjabin":[["The syrup is still thin like water.", "It coats a spoon like runny honey and smells strongly of mint.", "Thick and dark like caramel — it will set hard. Stir in a little water."],["شربت هنوز رقیق مثل آب است.", "مثل عسل رقیق پشت قاشق را می‌پوشاند و بوی نعناع تند است.", "غلیظ و تیره مثل کارامل شده و سفت می‌شود. کمی آب اضافه کنید."]],
"chai":[["The tea is light amber and the leaves are still floating.", "Deep red-amber, the leaves have sunk and the smell is rich.", "Dark, cloudy and bitter — it brewed too long or boiled."],["چای کهربایی روشن است و برگ‌ها هنوز روی آب‌اند.", "قرمز خوش‌رنگ است، برگ‌ها ته نشسته‌اند و عطرش بلند شده.", "تیره، کدر و تلخ شده؛ زیاد دم کشیده یا جوشیده."]],
"shakshuka":[["The whites are set at the edges but clear around the yolks.", "Whites fully set, yolks still wobbling when you shake the pan.", "Hard, chalky yolks and a sauce drying at the edges."],["لبه‌ی سفیده بسته ولی دور زرده هنوز شفاف است.", "سفیده کامل بسته و زرده با تکان دادن تابه هنوز می‌لرزد.", "زرده سفت و گچی شده و سس کنار تابه خشک شده."]],
"egg-fried-rice":[["The rice is warm but still in clumps.", "The grains are hot, separate and lightly toasted, with a slight smoky smell.", "The rice is hard and crunchy, or stuck and burnt."],["برنج گرم شده ولی هنوز به هم چسبیده.", "دانه‌ها داغ، جدا و کمی برشته‌اند و بوی دودی ملایمی دارند.", "برنج سفت و خشک شده یا ته گرفته و سوخته."]],
"chicken-curry":[["The chicken is white outside but pink inside when cut.", "The chicken is white through and tender; the sauce is thick with oil separating at the edges.", "Dry, stringy chicken and a sauce stuck to the pan."],["مرغ بیرونش سفید شده ولی داخلش هنوز صورتی است.", "مرغ کاملاً سفید و نرم است و سس غلیظ شده و روغن در کناره‌ها جدا شده.", "مرغ خشک و ریش‌ریش شده و سس ته گرفته."]],
"pasta-pomodoro":[["The pasta bends but has a white, chalky core.", "Al dente — tender with a slight bite, and the sauce glossy and clinging.", "The pasta is soft and bloated and the sauce dried out."],["پاستا خم می‌شود ولی مغزش سفید و گچی است.", "پاستا نرم با کمی مقاومت زیر دندان است و سس براق به آن چسبیده.", "پاستا وا رفته و باد کرده و سس خشک شده."]],
"roast-chicken":[["The skin is golden but the juices from the thigh are still pink.", "Skin deep golden and crisp, thigh juices clear, the leg wiggles loosely (75 °C in the thigh).", "The breast is dry and stringy and the skin dark and shrunken."],["پوست طلایی شده ولی آب ران هنوز صورتی است.", "پوست طلایی پررنگ و ترد، آب ران شفاف است و ران راحت تکان می‌خورد (۷۵ درجه در ران).", "سینه خشک و ریش‌ریش شده و پوست تیره و جمع شده."]],
"pancakes":[["Bubbles appear on top but the edges look wet.", "The bubbles pop and stay open and the edges look dry; golden-brown after flipping.", "Dark brown, dry and bitter."],["روی پنکیک حباب می‌زند ولی لبه‌ها هنوز خیس است.", "حباب‌ها می‌ترکند و باز می‌مانند و لبه‌ها خشک است؛ بعد از برگرداندن طلایی-قهوه‌ای است.", "قهوه‌ای تیره، خشک و تلخ شده."]],
"boiled-eggs":[["At 5–6 minutes the whites are set and the yolk is fully runny.", "8 minutes for a jammy yolk; 10–11 minutes for a firm, bright yellow yolk.", "A grey-green ring round the yolk, rubbery whites and a sulfur smell."],["در ۵ تا ۶ دقیقه سفیده بسته و زرده کاملاً آبکی است.", "۸ دقیقه برای زرده‌ی عسلی؛ ۱۰ تا ۱۱ دقیقه برای زرده‌ی سفت و زرد روشن.", "دور زرده حلقه‌ی سبز-خاکستری افتاده، سفیده لاستیکی است و بوی گوگرد می‌دهد."]],
"scrambled-eggs":[["Soft curds are forming but there’s still a lot of liquid egg.", "Creamy, soft curds that still look slightly wet and glossy.", "Dry, rubbery pieces with liquid seeping out."],["لخته‌های نرم دارد شکل می‌گیرد ولی هنوز تخم‌مرغ آبکی زیاد است.", "لخته‌های نرم و کرمی که هنوز کمی خیس و براق‌اند.", "تکه‌های خشک و لاستیکی که از آن‌ها آب بیرون می‌زند."]],
"folded-omelette":[["The bottom is set but the top is still liquid.", "The top has just set but is still soft and shiny, pale yellow with little or no browning.", "Brown, dry and rubbery."],["زیرش بسته ولی رویش هنوز مایع است.", "رویش تازه بسته ولی هنوز نرم و براق است؛ زرد روشن و تقریباً بدون قهوه‌ای شدن.", "قهوه‌ای، خشک و لاستیکی شده."]],
"poached-eggs":[["The white is cloudy and loose, still see-through in places.", "The white is fully set and the yolk soft and wobbly when lifted.", "The yolk is firm when pressed and the white tough."],["سفیده کدر و شل است و جاهایی هنوز شفاف است.", "سفیده کامل بسته و زرده موقع برداشتن نرم و لرزان است.", "زرده با فشار سفت است و سفیده سفت و کش‌دار."]],
"tamagoyaki":[["The layer is still wet on top when you start rolling.", "Each layer has just set and is pale yellow; the roll is springy and moist.", "Brown spots, dry and rubbery, and the layers come apart."],["وقتی شروع به لوله کردن می‌کنید رویه هنوز خیس است.", "هر لایه تازه بسته و زرد روشن است و لوله فنری و مرطوب است.", "لکه‌های قهوه‌ای دارد، خشک و لاستیکی است و لایه‌ها جدا می‌شوند."]],
"steamed-egg":[["The edges are set but the middle is liquid.", "It wobbles like soft tofu, the top is smooth, and clear liquid comes out when poked.", "Full of holes like a sponge, watery and tough."],["لبه‌ها بسته ولی وسطش مایع است.", "مثل توفوی نرم می‌لرزد، سطحش صاف است و با فرو کردن چاقو مایع شفاف بیرون می‌آید.", "مثل اسفنج پر از سوراخ، آبکی و سفت شده."]],
"meringues":[["Dry outside but still sticky and stuck to the paper.", "Crisp and white or very pale cream; they lift off easily and sound hollow.", "Beige or brown and cracked, with syrupy beads leaking out."],["بیرونش خشک است ولی هنوز چسبناک است و به کاغذ می‌چسبد.", "ترد و سفید یا کرم خیلی روشن است، راحت از کاغذ جدا می‌شود و صدای توخالی می‌دهد.", "بژ یا قهوه‌ای و ترک‌دار شده و قطره‌های شربت از آن بیرون زده."]],
"khagineh":[["Golden underneath but the top is still runny.", "Golden and puffed on both sides, springy, soaking up the syrup.", "Dark brown and dry, tasting burnt."],["زیرش طلایی شده ولی رویش هنوز آبکی است.", "هر دو طرف طلایی و پف‌کرده و فنری است و شربت را به خود می‌کشد.", "قهوه‌ای تیره و خشک شده و مزه‌ی سوختگی می‌دهد."]],
"eshkeneh":[["The onions are soft but pale and the eggs have just gone in.", "The onions are golden and sweet, the eggs just set, and the soup smells of mint.", "Burnt, bitter onions and rubbery eggs."],["پیاز نرم ولی کم‌رنگ است و تخم‌مرغ تازه اضافه شده.", "پیاز طلایی و شیرین، تخم‌مرغ تازه بسته و سوپ پر از عطر نعناع است.", "پیاز سوخته و تلخ و تخم‌مرغ لاستیکی شده."]],
"nargesi":[["The spinach is wilted but watery and the egg whites are still clear.", "The spinach is dry and dark green, the whites set and the yolks soft.", "Hard yolks and spinach stuck to the pan."],["اسفناج خوابیده ولی هنوز آب دارد و سفیده شفاف است.", "اسفناج آبش کشیده و سبز تیره است، سفیده بسته و زرده نرم است.", "زرده سفت شده و اسفناج ته گرفته."]],
"potato-eggs":[["The potatoes are golden outside but hard inside — test one with a fork.", "Crisp outside and soft inside, with the eggs just set.", "Dark brown, dry potatoes and rubbery eggs."],["بیرون سیب‌زمینی طلایی ولی داخلش سفت است؛ با چنگال امتحان کنید.", "سیب‌زمینی بیرون ترد و داخل نرم است و تخم‌مرغ تازه بسته.", "سیب‌زمینی قهوه‌ای تیره و خشک و تخم‌مرغ لاستیکی شده."]],
"spanish-tortilla":[["The edges are set but the middle is liquid when you shake the pan.", "Golden on both sides and just slightly soft and juicy in the very centre.", "Dry and dense all the way through, dark brown outside."],["لبه‌ها بسته ولی وسطش با تکان دادن تابه مایع است.", "هر دو طرف طلایی و وسطش کمی نرم و آبدار است.", "کاملاً خشک و سفت شده و بیرونش قهوه‌ای تیره است."]],
"french-toast":[["Lightly golden underneath but still wet and soggy in the middle.", "Golden and crisp outside, soft and custardy inside, with no wet egg.", "Dark brown and hard, dry inside."],["زیرش کمی طلایی ولی وسطش هنوز خیس و وارفته است.", "بیرونش طلایی و ترد، داخلش نرم و کرمی و بدون تخم‌مرغ خام است.", "قهوه‌ای تیره و سفت و داخلش خشک شده."]],
"egg-sandwich":[["Eggs boiled 7–8 minutes: the yolks are still soft.", "Eggs boiled 10 minutes: firm yellow yolks and a creamy filling.", "Grey-green yolks and a sulfur smell from boiling too long."],["تخم‌مرغ ۷ تا ۸ دقیقه جوشیده و زرده هنوز نرم است.", "تخم‌مرغ ۱۰ دقیقه جوشیده؛ زرده سفت و زرد و مایه کرمی است.", "زرده سبز-خاکستری شده و بوی گوگرد می‌دهد، چون زیاد جوشیده."]],
"egg-in-a-hole":[["The bread is golden underneath but the white is still clear.", "Golden toast, a set white and a runny yolk.", "Dark, hard toast and a firm yolk."],["زیر نان طلایی شده ولی سفیده هنوز شفاف است.", "نان طلایی، سفیده بسته و زرده عسلی است.", "نان تیره و سفت شده و زرده سفت."]],
"deviled-eggs":[["The eggs are boiled but still warm, which makes the filling runny.", "The eggs are fully cold, the yolks bright yellow and the filling smooth.", "Grey-green yolks from overboiling and a filling that tastes of sulfur."],["تخم‌مرغ پخته ولی هنوز گرم است و مایه شل می‌شود.", "تخم‌مرغ کاملاً سرد، زرده زرد روشن و مایه یکدست است.", "زرده از زیاد جوشیدن سبز-خاکستری شده و مایه بوی گوگرد می‌دهد."]],
"egg-custard":[["The edges are set but the middle ripples like liquid.", "Set, with a gentle jelly-like wobble in the centre; a knife comes out clean.", "Bubbles and holes, watery liquid seeping out, and a grainy texture."],["لبه‌ها بسته ولی وسطش مثل مایع موج برمی‌دارد.", "بسته شده و وسطش مثل ژله کمی می‌لرزد؛ چاقو تمیز بیرون می‌آید.", "حباب و سوراخ دارد، آب از آن بیرون زده و بافتش دانه‌دانه است."]],
"banana-pancakes":[["The edges are set but the middle is wet and falls apart if you flip it.", "Golden on both sides, soft and set in the middle.", "Dark and bitter — banana sugar burns fast."],["لبه‌ها بسته ولی وسطش خیس است و با برگرداندن از هم می‌پاشد.", "هر دو طرف طلایی و وسطش نرم و بسته است.", "تیره و تلخ شده؛ قند موز زود می‌سوزد."]],
"egg-curry":[["The sauce is thin and the onions still sharp.", "The sauce is thick, oil separates at the edges, and the eggs are coated and hot through.", "The sauce has dried and stuck and the eggs are rubbery."],["سس رقیق است و پیاز هنوز تند است.", "سس غلیظ شده، روغن در کناره‌ها جدا شده و تخم‌مرغ‌ها سس‌دار و داغ‌اند.", "سس خشک شده و ته گرفته و تخم‌مرغ لاستیکی شده."]],
"baked-potatoes":[["The skin is crisp but a knife meets resistance in the centre.", "A knife slides in with no resistance; crisp skin, fluffy inside.", "Hard, leathery skin and a dry, shrunken inside."],["پوست ترد شده ولی چاقو در وسط به مقاومت برمی‌خورد.", "چاقو بدون مقاومت فرو می‌رود؛ پوست ترد و داخل پفکی است.", "پوست سفت و چرمی و داخل خشک و جمع شده."]],
"mashed-potatoes":[["A fork goes in but the centre still feels firm.", "The potatoes fall apart when pierced; the mash is smooth, creamy and fluffy.", "Waterlogged potatoes make a sticky, gluey mash — and don’t over-mash."],["چنگال فرو می‌رود ولی وسطش هنوز سفت است.", "سیب‌زمینی با چنگال از هم می‌پاشد و پوره صاف، کرمی و پفکی است.", "سیب‌زمینی آب کشیده و پوره چسبناک شده؛ زیاد هم له نکنید."]],
"fried-potatoes":[["Pale and limp, bubbling fast in the oil.", "Golden and crisp, the bubbles slow down, fluffy inside.", "Dark brown, hard and bitter."],["کم‌رنگ و شل است و در روغن تند حباب می‌زند.", "طلایی و ترد است، حباب‌ها کم شده و داخلش پفکی است.", "قهوه‌ای تیره، سفت و تلخ شده."]],
"grilled-cheese":[["The bread is browning but the cheese hasn’t melted.", "Deep golden bread with cheese oozing at the edges.", "Black bread with a bitter smell and cheese burning in the pan."],["نان دارد قهوه‌ای می‌شود ولی پنیر هنوز آب نشده.", "نان طلایی پررنگ و پنیر از کناره‌ها بیرون زده.", "نان سیاه شده و بوی تلخ می‌دهد و پنیر در تابه سوخته."]],
"tomato-soup":[["The tomatoes are soft but the soup tastes sharp and thin.", "The tomatoes have broken down and the soup is smooth, sweet and slightly thick.", "Reduced too far and sticking, bitter at the bottom."],["گوجه نرم شده ولی سوپ هنوز ترش و رقیق است.", "گوجه کاملاً وا رفته و سوپ صاف، شیرین و کمی غلیظ است.", "زیاد جا افتاده، ته گرفته و ته آن تلخ است."]],
"garlic-bread":[["The butter has melted but the bread is still soft and pale.", "Golden, crisp edges and fragrant, pale garlic.", "Brown, bitter garlic and black edges."],["کره آب شده ولی نان هنوز نرم و کم‌رنگ است.", "لبه‌ها طلایی و ترد و سیر معطر ولی کم‌رنگ است.", "سیر قهوه‌ای و تلخ شده و لبه‌ها سیاه."]],
"aglio-olio":[["The garlic is sizzling but still white.", "The garlic is pale golden and fragrant; the pasta al dente and glossy.", "Brown garlic turns bitter — throw it out and start the garlic again."],["سیر جلز و ولز می‌کند ولی هنوز سفید است.", "سیر طلایی کم‌رنگ و معطر است و پاستا نرم با کمی مقاومت و براق.", "سیر قهوه‌ای و تلخ شده؛ دورش بریزید و دوباره سیر داغ کنید."]],
"shir-moz":[["There are still banana lumps.", "Smooth, frothy and cold, with a sweet banana smell.", "Left standing it browns and separates — drink it right away."],["هنوز تکه‌های موز در آن هست.", "یکدست، کف‌دار و سرد است و بوی شیرین موز می‌دهد.", "اگر بماند قهوه‌ای می‌شود و دو فاز می‌شود؛ فوراً بنوشید."]],
"tuna-sandwich":[["The tuna is still wet with oil — drain it more.", "The tuna is flaky and moist but not dripping, and the bread fresh.", "The filling is watery and the bread soggy from sitting too long."],["تن ماهی هنوز روغن دارد؛ بیشتر آبکش کنید.", "تن ماهی ورقه‌ای و نمناک است، نه چکه‌کننده، و نان تازه است.", "مایه آب انداخته و نان وارفته، چون زیاد مانده."]]
};
DP_RECIPES.forEach(function(r){if(DP_DONE[r.id])r.k=DP_DONE[r.id];});

